/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20221102-14","meetingId":"r04-cm11","date":"2022年11月2日","dateIso":"2022-11-02","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新庁舎建築ともなると相当な税金が使われるはずで、高い税金がさらに上がったりしないのだろうかということに対して、国および都からの分担金で確保することを予定していますということで書かれているのですけれども、庁舎の国と都からの分担金というのは、どういう仕組みで、４００億円以上と想定されていますが、それに対して、どれぐらい分担金が来ることになるのかを教えていただきたいのが１点です。","respondent":"大友新庁舎建設担当課長","answer":"こちらの土地の交換で、適正化の根拠、大体幾らなのかというところです。今回、土地の交換や売買という形で取得するものではなくて、土地区画整理事業によって再編されるもので、土地の評価につきましては、売買という金額の形で評価されているものではないと認識しております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが、およそ何％とか、４００億円に対してどれぐらいとか、試算されているものがどれぐらいなのかということをお聞かせいただきたいのと、土地区画整理事業の再編なので、それが的確かどうかというところがよく分からないのです。土地区画整理事業の再編で７,５００平米が８,３００平米になるということが適正だということは、何を基にして言えるのかというところを教えていただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"２点目の土地区画整理事業に伴う評価ですけれども、建設委員会の報告であったかと思いますが、土地区画整理事業の中で土地評価基準というものが示される中、私どもが聞いておりますところは、その評価基準について、評価委員という方が選任されて。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"その妥当だという根拠はどのような形で示されているのかという辺りは、そういう評価委員が妥当だと言っているので妥当だと判断しているということではないと思うのです。評価委員が妥当だと示している根拠は、議会の中でどこかで報告されているのでしょうか。そこら辺のところを伺いたい。そこの確認をお願いしたいと思います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"１点目の議会に報告されているのかという点ですけれども、私どもが認識していますのは、今年の６月２８日の建設委員会で、広町二丁目土地区画整理事業の進捗ということでのご報告があったかと認識しています。２点目の東京都と国の所有につきましては、今、おっしゃっていただいたとおり、所有する割合に応じて、これだけの面積を使うから、そのための分担金ということで、所有割合に応じた分担金となっています。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちなみに、今は何％ぐらい使われているということが分かったら教えていただけたらと思います。それと、３３ページに「保健センター機能」というところがあるのです。これも、前に伺ったことがあるのですけれども、別紙２のＳＤＧｓのところでも、３に新たに付け加えたというところで、新庁舎での保健所機能の強化というものが入っているのです。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"１点目、国・都・区の割合についてですけれども、ざっくりで申しますと、今の現庁舎をベースに考えますと、区が約８割、東京都が２割弱、国が数％という形になるかと思われます。もともとは、ある意味では感染症対策ということを主眼に置きまして、今回、そういった打ち出しをしていったわけですけれども、今回、特に３３ページに多く出てありますし、実際。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"感染症対策ということであれば、今でも庁舎の中に保健所機能があって、保健予防課で感染症対策はやってきたので、これをさらに強化するというのは、強化する保健所機能だけでなく、検査なども含めて、感染症対策ということで強化していくということでしょうか。続いて、別紙２のＳＤＧｓで、８項目の記載を新たに追加ということです。","respondent":"山下新庁舎整備課長","answer":"実際に検査室を新庁舎に設置するとなると、その動線の区分けや、いわゆる医療法的な難しさが出てくるのかなというところ等々、いろいろございまして、それは、これから研究・検討、また、設計の中でどこまで行けるのかというところを考えていく必要があるのかなと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、最後に伺いたいのは、これは策定委員会の中でも何度か共産党から出て、また、安藤区議からも申し上げておりますし、本会議の中でも申し上げたことですけれども、この要約版の２の検討経緯というところで、一番初めの行財政改革特別委員会での新庁舎の方針についての検討が平成２９年からということで始まっているのです。このようなものは、なぜ検討の中に入らないのでしょうか。","respondent":"山下新庁舎整備課長","answer":"１点目に具体的なセンターの名前がございましたけれども、そういったところを含めまして、今現在、窓口機能については低層階に集約する形で、やはり区民の利便性の向上につなげることを大きな柱として考えておりますので、そういった中での検討と考えています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この基本設計の案というのは、今回の基本設計の案には一切関わりがないのですか。これだけの税金を使って、同じ基本計画案を委託してきたわけですから、そこのところを入れないというのは、もう絶対おかしな話だと思うのです。なぜ入れないのか。これだけ長い間にわたって、これだけ税金を使って検討し続けてきたことを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"委員長。繰り返しの質問になっているので、そこについては、速やかなご進行をお願いしたいと思います。ご主張はご主張として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"同じ品川区の中でありながら、これだけの税金をかけてやってきた基本計画案というものは、こちらとは全く連動していないということですか。","respondent":"榎本新庁舎整備担当部長","answer":"ほとんどは連動していないということで、全くというわけではないですけれども、要は、広町全体を考えるときと、新庁舎の建設予定地が分かって、それに対してどうやろうかというところとレベルが違いますので、そういった意味では。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、私は、この基本計画案というものが、丸々基本計画案となっているにもかかわらず、そのような形でこれが連動していない、それから、これを踏まえていないということであれば、これまで業務委託して３億円を使った、それから、この問題で言えば、１億何千万円と九百九十何万円ですから、１億６,０００万円。そのような税金の使い方そのものが壊れるということになってくるのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３億円もかけて広町の開発について検討し、庁舎も、それから、隣のにぎわい施設も検討するということで、日建設計と、ＪＲと、品川区が一緒になって、これだけの税金を使って検討してきているわけですから、そこのところと切り離して考えるということはあり得ないと思います。これは、引き続き、様々なところで聞いていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"そういったことについて、この回答では触れていない。そこまで細かく触れられないのかもしれませんけれども、ランニングコストを抑えていくようないろいろな工夫などについての考え方をお伺いしたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、ＬＥＤ照明で高効率のエネルギーを使う、また、空調など、高効率を使っていく設備にすることで、ＺＥＢで環境に優しい設備、また、エネルギーを縮減する設備にしていくということを設計段階でも検討していきたいと考えています。２点目といたしまして、保全費の縮減。","id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"それと、あともう一点ですけれども、４０ページの外観計画というところで、幾つかの方のご意見で、「シンボルとなる」とか、「ランドマークとして」とか、「シンボリックな庁舎」ということで、区民の方々がそのような思いを抱けるデザインということで、区の回答としては、長きにわたり利用される建物として長く愛されるデザイン。","respondent":"大友新庁舎建設担当課長","answer":"品川区らしさを踏まえていくというところも視点に置いておりまして、品川区の歴史を踏まえつつ、周辺と調和したデザインにしていきたいと、現状考えているところです。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"１つお願いしておきたいところとしては、やはり長年にわたり品川区の庁舎という存在になるので、品川区民なのだということが、この庁舎を見ることで気持ちが沸き上がってくるような、品川区民の帰属意識のようなものをしっかりと根づかせていけるような、口で言うのと、現実的にそれを実現するのは相当難しいと思いますけれども、そういうものを１つ考えに入れていただいて。","respondent":"大友新庁舎建設担当課長","answer":"ご意見を踏まえまして、設計段階で精査して、よりよいデザインにしていきたいと考えています。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"今日は、パブリックコメントの実施結果と第１０回のところということで、今、委員長からご発言がありましたけれども、できるだけ設計には行かないようにしつつと思いながらお伺いしたいのですけれども、パブリックコメントの中で意見交換などもやってほしいという話もあったかと思います。答申案のほうではこれが維持されているのですけれども、今後、このままのスケジュールで行くご予定なのか、伺います。","respondent":"山下新庁舎整備課長","answer":"現状、こちらは、基本計画案をご答申いただいた後に策定に至るというところでは、再選挙というところは読み込んでいない中で、この素案説明会を８月に実施しての基本計画素案という段階でございましたので、今後、こちらの部分については。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問・要望","question":"説明会のほうは、またご検討いただければと思いますし、動画の配信だと、質疑応答というところがなかなか難しくなってきますので、説明会という表現はしておりますけれども、やはり設計段階でも区民の皆様のご意見を伺う機会というのは、できるだけ増やしていただきたいなと思います。スケジュールについては、なかなか分からないところもあるかと思いますので、この程度にしておきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"議会棟の通路であったり、議会棟の一部に大きな窓を設けて、椅子を設けて、見晴らしができる場所を設ける、または、その下の執務機能の一部の場所を一般に開放できるようなところを設けて展望できる、また、おっしゃっていただいたように。","id":"exchange-016"},{"speaker":"松本委員","kind":"意見","question":"繰り返しになるので、計画自体については、いろいろ考えはあるのですけれども、結構展望部分については、区民の方からもご意見をいただいておりますので、ぜひ引き続きご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました。策定委員会でも様々質問させていただいたのですけれども、そのときも確認させていただいたことで、もう一度確認をさせていただきたいのです。今回を踏まえて、修正事項についてというペーパーの一番下のＣＭ方式のところに修正が入って、導入も視野に入れるというところから、「活用を企図し」ということで、前回、質問させていただきました。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、国土交通省のマニュアル等でも、業者選定をかなり慎重にやっていかないと、求める成果が出てこないというところもありまして、プロポーザルにて業者をしっかりと見極めて選定していきたいと考えているところです。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も素人ながら、心配なところがあるのですが、そのような時間との戦いになってくるのかなというところで、これは要望も含めてですが、そこについては、慎重かつ速やかにというところで確認させていただき、お願いをさせていただきたいのですけれども、いかがでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、我々といたしましても、他の自治体がどのように決めていったというところをいろいろお聞きしながら手法を選定して、業者選定に当たっていきたいと考えています。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後です。できる限り、最大限、そこのところは配慮して、選定に至っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからの検討委員会の中にも、障害者団体の方々を入れてほしいということもあったと思うのです。これからは、検討委員会というのはつくられないで、設計のほうに入っていくということですか。その中にも入れてほしいという要望があったりしていたと思うのですけれども、どのような形で、どの場面で障害者の方々のご意見を伺っていくのかということを伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、誰にでも優しく、便利で機能性にあふれる庁舎ということでうたっておりますので、設計を始められる早い段階で、まず、意見聴取に臨みまして、一定このような形でというところをお示しし、また、そういった障害のある方だけでなくて、区民の皆様にもお知らせをした中で。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"設計の業者が決まった後で、速やかにということで考えていいのでしょうか。設計の業者を選定するに当たっても、障害者の方に対しての配慮などが行き届くような業者の選定が必要かなと思うのです。もちろん、その辺りもそのようになってくるとは思うのですが、改めて確認をさせていただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"各設計事業者で、障害者の方の意見を聞かないで設計していこうということをおっしゃるところはまずないのかなと考えていますので、先ほど、別の委員からもございましたけれども、ＣＭ方式、また、基本設計の事業者選定に当たりましては、いろいろな点を複合的に考えながら。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"以前にも世田谷区の庁舎建て替えに当たって、世田谷区にお伺いして、委員会で伺ったことがあったのですけれども、改めて伺いたいことが何点かあるのですけれども、申し上げていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１つは、計画の検討に当たり、区民に対しての情報提供と区民参加の位置づけ、その具体的な手法について、伺いたいと思います。それと、３点目には、なぜ中低層にしたのか。高層の建物にしなかった理由について、伺いたいと思います。それから、４つ目が、災害拠点としての本庁舎というものが位置づけられているのですけれども、具体的にどのような機能があるのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"建設費に関して、物価高騰などの関係で、世田谷区もかなりご苦労されたと伺っています。今後、やはりあちらもＤＸを進められていますので、庁舎のスペースに対する考え方。今後、どのようにＤＸ等の関係で職員数を考えて、スペースを確保する、スペースをどの程度にしていこうと思っていたのか、検討されたのかというところをお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、質問もしましたけれども、今、調べると、世田谷区役所もコンストラクション・マネジメントの手法をとっている。事業者も決定したと思いますので、そこについての、いわゆるコンストラクション・マネジメントを入れた成果と課題、また、どれぐらいの費用がかかったのかというところでのコスト、その辺りも教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"丁寧に説明できる仕組みをどのように考えているのか。要は、マイナンバーカードを持っている人全員から利用者登録をしてもらいたいわけです。本当だったら、５０％ぐらい使ってほしいのだけれども、そこまで上がっていないということは、どちらにしてもその辺がうまく伝わっていないのです。ですから、その辺をどのような意図を持って行政が誘導していくかというのは、僕はすごく大事だと思うのです。","respondent":"河西情報戦略担当課長","answer":"こちらを一度使っていただきましたら、そのよさを分かっていただけると思うのですけれども、確かに、そちらのメリットの訴求方法に関しては、我々、不十分なところもあると思いますので、これから研究してまいりたいと思います。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この４ページの「新システム導入と手続拡充の取組」、私も電子の手続きはよく分からないのですが、１２月１日から開始するということで、本人確認は、このマイナンバーのところを見ると、本人確認の手段の１つとして活用する予定ですとあります。マイナンバーを使いたくない方の本人確認は何で行うことができるのかを伺いたい。その仕組みを教えていただきたいと思います。","respondent":"河西情報戦略担当課長","answer":"支払決済の方法については、オンライン決済になります。具体的には、一番分かりやすいのはクレジット決済です。クレジット番号をネットショッピングなどでも入れられていると思いますが、そういったやり方。ＱＲ決済、口座の引き落としといったところを、今、検討しております。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう人が不利益にならない仕組みというのは、ぜひしっかりとやっていただきたいと思います。それと、６ページのところに、「品川区電子申請サービス」が１から４まであります。これは、何かで区別されなければいけない部分があるのでしょうか。その辺りを少し伺いたいと思います。それから、これを使っていくには、使いやすい仕組みもすごく大事になってくると思うのです。その点も教えてください。","respondent":"河西情報戦略担当課長","answer":"サービスですが、今回、お示しした６枚目のスライドを見ていただきますと４つあります。基本的には、１番の「品川区電子申請サービス」に載せていく予定です。こちらの１番のいいところは、先ほどご説明しましたが、汎用的な手続き、事務フローに対応しているところです。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この項目は電子申請ができますという一覧表みたいなものはどこかに案内されるのでしょうか。その点を伺いたいと思います。そういう電子サービスの項目と、品川区が条例で定める、区として紹介したりするときに使う条例の中に定める事業というのは、どのように関わってくるのか、関わりがないのか、その点も教えてください。","respondent":"河西情報戦略担当課長、宮澤情報推進課長","answer":"こちらは、今の総手続き数に対して、オンライン化の手続きの数を記載しております。これから具体的な手続き面に関してもホームページで掲載する方向で検討を進めております。先ほど説明で言ったマイナンバーカードを活用するというのは、申請する際の本人確認のために使うということで、マイナンバーを使っているというわけではございません。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。マイナンバーを使わなくても申請できるということですし、マイナンバーを使わなかったことによって不利益は生じないということだと思います。最後に、高齢者のスマホ教室ですけれども、これは、開催箇所を拡大したということです。高齢者スマホよろず相談、これはどこでやっているのか、どのように拡大したのかを具体的に教えていただきたいと思います。","respondent":"宮澤情報推進課長","answer":"併せて、スマホよろず相談につきましては、その３か所プラス、平塚橋ゆうゆうプラザ、大井三丁目高齢者憩いの場というところでも行っている状況です。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"引き続き、よろしくお願いします。午前中の議論でもあったのですけれども、今回、一般質問でも質問しましたが、マイナンバーカード活用の取組のところをお伺いします。時間がなかったので、あまり一般質問では言えなかったのですけれども、今、交付率がナンバー１からナンバー１０まで出ているのですが、ナンバー２からナンバー１０までは、全部１０万人以下の小さな都市です。そこからまずお伺いします。","respondent":"宮澤情報推進課長","answer":"区の職員のマイナンバーカードの保有に関しては、情報推進課としては把握、調査等はしていないという状況です。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"例えば、私は行政書士ですけれども、行政書士会などは、総務省を通じて、行政書士の方にはマイナンバーカードを取得するようにということでの依頼文書が来ているのです。品川区役所には、自治体に対して、職員にこういうものは来ているのでしょうか。","respondent":"堀越総務部長","answer":"所持状況を見ながら、例えば、共済組合のいろいろなサービスについて、そういったものを活用していくとか、そういうものを検討していくという、まだ途上の段階であると認識しています。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"すみません。後半の部分で、先ほどの質問で、国から自治体に対して、職員の方については、マイナンバーカードを積極的に取得してくださいという取得依頼が来ているのか、来ていないかというのは、今、分かりますか。","respondent":"堀越総務部長","answer":"その調査の中で、実際にそのような文言があったかどうかというのは記憶にないのですけれども、ただ、本人の希望でのアンケート調査の形式でありまして、前提になる位置づけははっきりお答えできないのですが、回答について。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここに書いてある、いわゆる戸籍や住民票についても、一般質問でも申し上げましたが、一律１５０円にしたら、品川区の場合は十数％ですけれども、当然、それなりに安ければみんなコンビニで取るということで、半分ぐらいがもうコンビニで取っている。簡単です。窓口に並んで待って取るより、自分で機械で取ったほうが早いですから、そのようなこともされてきた。ほかにもいろいろなことをやっています。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードの利活用です。委員にご指摘いただきました、職員の出退勤や図書カードをカード自体の空き領域を使って活用しているという自治体の例も認識しているところです。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"マイナンバー制度が始まってから７年ぐらいですか。もう少したっているのですか。そういう中で、９月末で全国的には４９％ぐらいですか。品川区はその上を行っているのですけれども、独自の利活用ということについて、それに全精力を注力するのも少し違うのかなとは思うのですが、やはり品川区として独自の利活用を考えていただきたいなというところです。その辺のお考えをお伺いしたいと思います。","respondent":"久保田企画部長","answer":"今のところは、区としてはコンビニ交付等ができるメリットしか訴えることができませんけれども、今後、独自活用でどういったものができるかということについても研究していきたいと思いますし、また、そういったものがあれば、幅広く取り入れて進めていきたいと考えております。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"都城市の例ばかりで申し訳ないのですが、７年前にこの取り組みを始めたときには、まず、職員の研修から始めたそうです。デジタル研修は、皆様さんざんやっていらっしゃると思うのですけれども、先ほど、一番最初に申し上げたように、職員の方の取得率はどうなのですか、交付率はどうなのですかと申し上げました。ですから、これは絶好の機会というか、必ずインフラにすべきものだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"初めに、「品川区電子申請サービス」を始められるということでお伺いします。これは、マイナンバーカードを持っていない方もいらっしゃるということで、そのような方々については、これまでどおり紙による申請をして、ＩＤ申請をして使っていただくというご説明がありました。このような仕組みにしたことについて、なぜかなというところを少しお伺いしたいと思います。","respondent":"河西情報戦略担当課長","answer":"今のご質問にお答えします。今回、新しく始める新サービスですが、システムの考え方について、ご紹介します。システムの考え方ですが、まず、システムで取り扱う手続きは、マイナンバーが必要なものと、そうでないもの、２種類を扱います。","id":"exchange-038"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。これは、少し細かな話になるのですけれども、品川区から区外に転出された方々の申請されたＩＤというのは、今のお話で言うと、多分マイナンバーがあるから、自動的に削除されるということにはならずに、別のやり方で管理というか、転出された方は削除していくということになるのか。そこのところをご説明いただければと思います。","respondent":"河西情報戦略担当課長","answer":"今のご質問にお答えします。基本的には、先ほどご紹介したとおり、手続きは２種類ございまして、マイナンバーを利用するものと、しないもの。対象者に関しても、基本的には品川区民となっておりますが、マイナンバーの認証をかける際に、住所情報が確認できます。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは、情報システムの担当にお答えを求めるのは少し難しいかもしれないですが、そういうクレジットカードを持たないために、来庁しないオンラインでの行政サービスの外に置かれてしまう方が一定程度いるのだなということに対して、何かしらオンラインでの決済をできるようなことを考える。研究から始まるのかもしれませんが、やはりそのようなことは必要ではないかなと思うのですが、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"事業者にお話を聞きますと、やはりそういう引き合いがありますので、ＱＲコードの会社もいろいろありますが、取扱いを少しずつ増やすという方向は聞いておりますので、そういったところでサービスを提供できればと考えております。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。そこら辺についても、そのように手を打っていただいているということで、大変すばらしいと思います。クレジットカードがないということは、そういうことでしょうか。スマホ等にアプリを入れて、そのスマホのアプリが銀行口座とひもづいて、そこで決済ができますという仕組みなのでしょうか。","respondent":"宮澤情報推進課長","answer":"先ほどのいわゆるＱＲコードの仕組みですけれども、１２月のスタート時からの実装は難しくて、年明け以降になってくるところです。そのお支払いの中身やブランドについては、今、調整しているところですので、詳細については、お答えできない状況になっております。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。いずれにしても、来年になれば、その辺がもう少し明らかになるということです。オンライン申請等で、来庁せずに区民サービスを受けられる。これも、ある意味でのデジタルデバイドになるような話であるので、そういったことの解消に向けてしっかり取り組んでいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"電子申請について、伺います。「ぴったりサービス」や「ＬＩＮＥ申請サービス」など、サービスが様々あっても、「品川区電子申請サービス」で、まず窓口のフロントの部分が一括されるというのが大変いいなと感じておりまして、ご質問をします。１２月１日からぜひとも分かりやすくお願いしたいなと考えています。","respondent":"河西情報戦略担当課長","answer":"今回の新しいサービスの区民への周知ですが、広報紙を利用した周知や各種ＳＮＳを使って周知を行ってまいりますので、そういったところで区民の方にもしっかり情報発信していきたいと考えております。","id":"exchange-043"},{"speaker":"西村委員","kind":"提案","question":"ＳＮＳ、広報紙はそうですけれども、度々、ＬＩＮＥだとセグメント配信ができるということを提案させていただいておりまして、若い方ではなくて、６０、７０代の方でもＬＩＮＥを使っている方が増えてきたなという肌感覚があります。ですので、この「ＬＩＮＥ申請サービス」はシナジーがたくさんあるのではないかなと考えていますが、その辺りのご意見をお聞かせください。","respondent":"河西情報戦略担当課長","answer":"お言葉のとおり、確かにＬＩＮＥの利用者はかなり多いですので、利用されているＳＮＳに、しっかり漏れなく配信していきたいと考えております。","id":"exchange-044"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば、粗大ごみの受付システムをＬＩＮＥ申請でしている自治体がありまして、支払いまでＬＩＮＥＰａｙで完結してしまうということで、コンビニまでチケットを買いに行かなくてもいいと伺っていますので、ぜひとも参考にしていただきたいと考えています。全部で１２か所あったかと思うのですけれども、あと残り４か所は、令和４年度目標の２９か所の中に入っていますでしょうか、お聞かせください。","respondent":"宮澤情報推進課長","answer":"今年度の２９か所については、その３か所は含まれておりません。キャッシュレス決済の目標値というのが、令和５年度は３８か所を目標としておりまして、所管部署と連携しながら検討していきたいと考えております。","id":"exchange-045"},{"speaker":"西村委員","kind":"意見","question":"このオンライン化に関しましては、オアシスルームはキャッシュレスですけれども、申請件数が多くて需要が高い手続きからということが、すごくありがたいなと思っていますので、同じようにオアシスルームも大変ニーズが高いですので、引き続き、実施をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/893508?Template=document&Id=6140#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":38990,"voices":121}},{"id":"r04-20221102-10","meetingId":"r04-cm11","date":"2022年11月2日","dateIso":"2022-11-02","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5484#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1174,"voices":8}},{"id":"r04-20221104-19","meetingId":"r04-cm11","date":"2022年11月4日","dateIso":"2022-11-04","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"３点ほどあります。前回も指摘しましたけれども、脱炭素社会の実現のやはり大きな障害となっている石炭火力発電の廃止、それから原発ゼロ、これをやはり国に働きかけていくことを、区の環境基本計画に盛り込んでおくべきだと、私はこの日常的に実践する人という形で実践主体を問題にするなら、やはり一言でも入れておくべきではないかと思ったのですが、その点、どうお考えになっているか伺いたいと思います。","respondent":"河内環境課長","answer":"したがいまして、区民の方にご提案するこの計画の中につきましては、このような表現の中でしっかりして推進していくというような考えです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"それで、私の要望としては入れていただきたいということは言っておきたいと思います。環境団体からも多々指摘されて、岸田首相が会議に出るたびに環境団体からは化石賞をもらったりしているわけですから、品川区はそういう環境団体と同じように、真剣にカーボンゼロを目指しているのだということを宣言する意味でも、環境基本計画に盛り込んでいただきたいと思います。意見・要望として述べします。","respondent":"河内環境課長","answer":"したがいまして、大事なものをしっかり受け継ぐというところの精神と、見つけることといったものは既にこの中に合わさっているというふうに考えてあります。なお表現の中で、今委員がおっしゃったような形で取り入れたいと考えていますが、現在のところ、検討状況は今の状況です。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう私の要望・意見ということで、受け止めていただければと思います。それから３番目は、基本目標１のところなのですけれども、これが前回の案では「脱炭素社会」を実現するとそのものずばりの表現だったのです。以上のことから、元の案を生かしたものにするほうがいいと私は思ったのですけれども、その点いかがでしょうかということです。","respondent":"河内環境課長","answer":"将来に向けての対応といたしまして、区民の皆様に意識の向上、意識の醸成ではないのですが、そういったものを取り組む社会とともに、それに付加するような暮らしをいろいろ考えていただきたいというところが計画の大事な点だと思っておりまして。","id":"exchange-003"},{"speaker":"おくの委員","kind":"意見","question":"そういう意味で、やはり今回のほうは弱められているなという印象が強いので、私はそういうふうに思っているということで受け止めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"裏面なのですけれども、先ほどもあった８月２４日の案と見比べたときに、まず共通目標のところの施策の中で書き加えられたというか、この「他地域での環境活動の促進」とあるのですけれども、これがどういう意味なのかというところを伺いたいというのと、基本目標４のところで、前回では、「化学物質の適正な管理に努める」という文言があったのですけれども、そこがなくなってしまいました。","respondent":"河内環境課長","answer":"こちらにつきまして、施策の中のものとして、案として挙げておりましたが、取組内容の中できちんと取り上げるというところで、全体でいきますと「すこやかな暮らしを守る」で例示が書いてありますが、こういったものを進めていきたいというところで考えているところです。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"水素のところなのですけれども、基盤整備ということで、８月２４日のときにも伝えたのですけれども、ぜひグリーン水素の考え方ということで受け止めたいと思うのですが、いかがでしょうかというところと、サスティナブルファッションの推進についても、より強い言葉でＣＯ２の削減のためにということだったのですけれども、プラスチックを使って服にするといった。","respondent":"河内環境課長","answer":"そういったところの意識を変えることによりまして、平均でワンシーズンで６着、７着と言われているものをより吟味し、さらにそういった素材がリサイクルできるようなサイクルに落ち着くというところで、プラの削減にもつながるというところで、大変重要な取組と認識しています。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"１点だけ。学生が多く参加されているということは理解しました。ただ、その学生たちが今どういうことを思ってとか、どういったことを知っていってとか、そういうことも分かるような、やはりその方たちが特定されるような表現ではなくて、委員の発言、それに対する答弁とか意見交換の状況が分かるような、やはり議事録というのはぜひ公開していただきたいと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"要望として承りました。そのように努めたいと思います。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"素案に向けた検討状況ということでご説明を伺いました。まだこれは概要の資料ですけれども、やはりこの環境基本計画そのものにそうした地球規模の気候危機を克服しなければならない、また、今手をつけなければ、熱波や干ばつや巨大なハリケーンなど、深刻な状況になると。そういう危機認識をしっかりとまず品川区環境基本計画の前提に据えることが必要だと思うのですけれども、その点伺いたいと思います。","respondent":"河内環境課長","answer":"ご意見ありがとうあります。地球温暖化に向けて大変厳しい状況である点、こういったものを背景、状況といたしまして、巻頭からそういった説明をした上でこういった取組というような流れで、案につきまして作成したいと考えているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、続けて今後のスケジュールについて少し伺いたいのですけれども、１２月上旬と１２月中旬から下旬に、課長級の環境対策庁内会議と部長級の環境対策推進会議とそれぞれ設定されておりますけれども、ぜひ議事録を作成していただきたいという点と、公表をしていただきたいと思うのですけれども、それぞれいかがでしょうか。","respondent":"河内環境課長","answer":"環境基本計画にしっかり位置づけるという点。そちらの考えにつきましては、私どもも同じという点で、しっかり環境基本計画の中に、今回カーボンハーフになぜ至るのかというようなところはしっかりと説明させていただきたいと考えています。","id":"exchange-009"},{"speaker":"中塚委員","kind":"確認","question":"議事録の作成と公表ですけれども、今の説明ですと、この課長級の環境対策庁内会議と部長級の環境対策推進会議は議事録を作成するということと、いろいろな形の公表もありますけれども、例えばホームページに示すということでよいのか、確認させてください。","respondent":"河内環境課長","answer":"そういったところも踏まえ、前向きに検討させていただきたいと考えております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"検討するということで、やはりどういう議論の経過でこの素案ができたのかということの経過をしっかり公表するということが必要だと思います。少なくとも１３地域センターごとに、品川区がその素案について説明をし、１か月間のパブリックコメントがありますので、ご意見・ご要望をこの場でも伺いますし、後ほど郵送でもメールでもという説明会を開催していただきたいと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"パブリックコメントの経過・結果に基づく説明ですが、現状エコルとごしにおきまして、こういった説明会をさせていただきたいという考えで検討を進めているところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"エコルとごしで説明会をということですけれども、その狙いや目的は何かということを伺いたいと思います。改めて、やはり区内全域で開催することが必要だと思うのですけれども、エコルとごしだけではなく、各地域センター管内ごとに説明会を開いていただきたいと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"そういった中で、そういった記載を壁などに張っているものから含めまして、しっかりと発信できればというようなところがありまして、エコルとごしというところで考えているところです。１３地域につきましては、今後の検討事項にしたいと考えています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"この品川区環境基本計画に限らず、パブリックコメントを開催する際にはぜひ説明会をとこの間求めてきました。住民参加は徹底した情報公開の下で保証されると思います。なので、ぜひパブリックコメントをする際には丁寧な説明会を行って進めていただきたいと思うのですけれども、改めていかがでしょうか。","respondent":"河内環境課長","answer":"説明会など、それから今後、予算の中で出てくるかと思いますが、動画など分かりやすくお手元に届きやすいものをいろいろ作りまして、こういったものを取り組んでいただきたい、こういった目標に向かってみんなで頑張ろうというようなところで。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"区が勝手に決めました。区民の皆さん、これ、どうぞではなくて、自分も参加してその計画をつくることによって、今回で言えば品川区環境基本計画の実施に向けて、区民自らが主体者となって取り組むことができる。そういう関係もあると思いますので、様々な行政計画を策定する際には、住民参加・情報公開の徹底を改めて求めたいという要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"今もありました環境学習交流施設、エコルとごしのところで、資料の裏面の共通目標の施策の中の２個目に、８月２４日には「子どもと大人が一緒に行う環境学習」という文言があったのですけれども、それも今回消えてしまったのがとても残念だったなと思って、これはどういう意図でなくなってしまったのかというところを伺いたいのと、やはり子どもと大人が一緒にというのはとてもいいと思っていたので。","respondent":"河内環境課長","answer":"そういった中で、こういった項目づけの中で文言として整理したものです。今、委員がおっしゃった意見につきましては、参考といたしまして、今後の検討事項といたしたいと考えております。ありがとうございました。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"裏面の基本目標２－４、これは前回８月のときも確認をさせていただきまして、「地域循環共生圏（ローカルＳＤＧｓ）の形成推進」、「地産地消の推進」、「サスティナブルファッションの」当時は「啓発」で、今回「推進」ということで、より強い表現に進めていただいたと先ほどの答弁で伺いました。それがエシカルの部分の領域になってくるのかもしれませんけれども、地産地消のとこも入ってくると思うのです。","respondent":"河内環境課長","answer":"今後様々なお声を生かしながら、こういったところを進めてまいりたいと考えているところです。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"この会議そのものに小・中学生の参画をということは求めてきている中で、非常に意識をしていただいて、まずは知っていただく機会を広げていただいたのかなという理解で受け止めましたけれども、なので、やっていること自体を概要として伝えるということも大事ですし、なぜそれをしなくてはいけないのかというその時系列のつながりですね。それとあともう一つ、併せて伺います。","respondent":"河内環境課長","answer":"ウォーカブルの点ですが、環境面ということなので、脱炭素に向けてという点、やはり考えているところではありますが、こういった中身につきまして、まず啓発の中で意識の醸成も含めましてきちんと掘り起こした上で、環境面等を踏まえいろいろなところに計画は絡むと思うのですが。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。それがしながわ健康ポイントですね。そういうのがあったりすると思うのですけれども、そういうのをうまく結びつけて、まさに歩きたくなる、ウォーカブルな取組については、区全体として取り組んでいただきたいと思います。身近なところというところで、これは質問ではないですけれども、歴史学者でアーノルド・トインビーという人がいるのです。要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認します。先ほどこの環境基本計画中間見直しにあたって、パブリックコメントが終わり、その後の説明会をエコルとごしを活用して行っていくという話がありました。この環境基本計画の冊子の中でエコルとごしの紹介があるのかというようなところをどのようにご検討されているのか、お知らせいただきたいと思います。","respondent":"河内環境課長","answer":"そういったところを含めまして、いろいろな方がやはりこの環境基本計画を担っていき、全体で一丸となって達成するというようなところの醸成を当該施設でしっかり担っていきたいというような考えで、現在進めているところです。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"そうすると、この冊子の中には特にエコルとごしの表現というのは入ってこないということでしょうか。","respondent":"河内環境課長","answer":"エコルとごし自体は紹介いたしますが、そういった単にハードだとかで、これをこうやったとかそういったところにとどまらず、こういった機能をぜひ活用しながら、皆様の中でこういったことをやっていただきたいというようなところで、環境登録団体しかり、ボランティアしかり。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"おもて面の表４で業務というのがあって、それ以外の農業、建設業、製造業とあって、これも業務だと思うのですけれども、ここを特出して出しているというのは、何か国のほうでそのような感じになっているのか、区のほうでそういう考えで出しているのかということと、それから廃棄物が出ていますけれども、家庭と業務の中でも廃棄物が出るのですけれども。","respondent":"河内環境課長","answer":"こちらにつきましては、オール東京６２市区町村共同事業というものがございまして、そちらの中で、この該当項目につきまして、こういった数値を取りまとめているです。各区とも共通なものでございまして、それに照らし合わせました数値が、今回このように出ているところです。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"これで見ると、廃棄物の全体の割合としてはＣＯ２の排出量は低いのですけれども、廃棄物のところだけが基準年と比べて増えているということを考えると、この部分での取組というのは、クローズアップしていくのは非常に大事なのかなと思うのですけれども、この理由としてはやはり簡単に言うと、廃棄物が増えているということなのでしょうか。","respondent":"河内環境課長","answer":"改めましてそういった面について啓発をしっかりやっていきながら、ここの数値の低下に向けてというところで、一般廃棄物処理基本計画に合わせまして、連携をとりながら進めてまいりたいという考えです。","id":"exchange-022"},{"speaker":"たけうち委員","kind":"意見","question":"区民の方が見て、単純にやはりここをもし計画で出すとすれば、ここが増えているのだなというところで、自分たちができるのは何なのかなという、多分そういうところでくると思いますので、恐らくこの裏面の計画のところでもそこが強調されてきていると思うのです。食品ロスですとかプラスチックのことですね。そういったところを分かりやすく、ぜひ計画の中で位置づけていただければと思います。","respondent":"河内環境課長","answer":"一方で、こういったものにつきまして、まずはごみの減量化というものも非常にこの中に絡んでまいりますので、委員のおっしゃるとおり、分かりやすい、何を取り組んだらいいのかという点につきまして、取組の中で取り入れながら計画を進めてまいりたいと考えております。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"いろいろ環境基本計画を見直すのは、すごく大変だなと。基本的に私が思うのは、１つは行政が音頭を取るということですが、やはりそこには、購入する側、使用する側の区民に対しての普及啓発。そして事業所。その加工方法。そういうのも全然整ってない中で、今目標は立てられているのですが、これで本当に大丈夫ですかという、逆に疑問すら覚えてしまうのです。そういう点について、ご見解をお聞かせください。","respondent":"河内環境課長","answer":"全文はなかなか皆さん読まないでしょうし、それから業界の方につきましてもやはり立場を考えていろいろ発信いたしませんと、電気自動車の例を挙げていただきましたが、現在例えば日産の某軽自動車の電気自動車など、国と都の補助金を合わせれば１００万円近くの補助金が出て。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"電気自動車は補助金もありますよ。車検も安い。販売されるスーパーでいろいろなもの売っていますけれども、ですから、本当に区からも発信していただきたいのは、やはり国が引っ張っていっているのですから、財源がもうないのだと思うのだけれども、やはりどこかからひねり出して各自治体に配って、そして区民に、皆さんこうやってちゃんと補助金を出しますよと。もしご意見があったらお願いいたします。","respondent":"河内環境課長","answer":"要望としてはよく理解いたしました。そのような形も念頭に踏まえまして、進めてまいりたいと考えております。ご意見ありがとうございました。","id":"exchange-025"},{"speaker":"のだて副委員長","kind":"確認","question":"先ほど反映はもちろんしていきますということでしたけれども、４月１日の環境基本計画運用開始まで何も手順が示されていないので、ここにどうやって反映をさせていくのかというところを伺いたいと思います。それと、先ほどエコルとごしでの説明会のお話がありましたけれども、これはパブリックコメントの期日の前にやるのか、後にやるのか、そこも確認したいと思います。","respondent":"河内環境課長","answer":"説明会の件につきましては、そういったものが決定されたものにつきまして、皆さんがどういうふうにお守りいただいて進めていただきたいかという説明会ですので、その後になるものです。","id":"exchange-026"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"パブリックコメントの意見反映は、変えるべきものは変えるということですけれども、この手順が示されていなかったので、今回環境対策庁内会議などで検討して、反映させていくのかどうかというところを確認させていただきたいのと、エコルとごしでの説明会がパブリックコメント後ということで、やはりこのパブリックコメントに意見を出すためにも、説明会をぜひやっていただきたいと思うのです。","respondent":"河内環境課長","answer":"パブリックコメントの内容につきましての説明会につきましては、これは現状まだやるつもりはございません。結果につきましての周知・啓発に向けて、力を尽くしてまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"パブリックコメント前に説明会をやるつもりはないということですけれども、やはりここは意見をしっかり集めるためにもやるべきだと思いますし、当然その後、啓発のためにやっていくということも必要だと思いますし、そこはやはり充実させていくということが私は必要だと思いますので、ここは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-02","title":"令和４年度区内一斉防災訓練の実施","agenda":"令和４年度区内一斉防災訓練の実施","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"医師会の方から、より有効な医療救護活動を展開するために要望を伺っておりますので、それに関連して質問いたします。それから２点目、学校医療救護所における医療救護活動に従事する医師の受入れ体制が明確になっていないとして、医師の休憩場所の確保や飲料水や食料の提供など、支援体制の確立を要望されていますが、この点いかがでしょうかというのが２点目です。いかがでしょうかというのが３点目です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"おくの委員","kind":"質問・要望","question":"検討中ということで、検討を進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"すみません。伺いたいのですけれども、防災訓練の実施の周知方法と、町会の方だけしか参加できないとかそういうことはないと思うのですけれども、そこの確認と、今、新型コロナウイルスの感染者数が増えてきている中で、この実施時期にもしそういったことがあったら人数制限とかがされてしまうのかとか、そういった部分についても伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"コロナ禍の人数制限につきましては、基本的には区としましては、感染防止用品は貸与しますよという形でお話はさせていただいているところですが、各避難所のほうで人数制限を実施するとか、あるいは分散実施をするとか。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"感染拡大を抑止するため、広がらないようにするための人数制限も必要だと思いますし、あと町会に入っていない方でもやはり防災訓練には参加してほしいですし、特にやはり障害のある方には参加していただきたいと思いつつ、この感染状況も不安だしという、とても曖昧というか何というかというところなのですけれども、ぜひ周知のほうと、感染状況によって。","respondent":"五十嵐災害対策担当課長","answer":"訓練は公助と共助のほうをメインに実施していくわけなのですけれども、もちろん町会・自治会以外にＳＮＳやホームページ等を使って周知はさせていただきたいと思っています。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の質疑にも関わるのですけれども、区内一斉防災訓練の実施ということですけれども、障害がある方の参加の保証について、その視点があるのか、ないのか伺いたいと思います。ぜひ障害がある方の訓練の参加もしっかりと位置づけていただきたいと思うのですか、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"これの狙いというのは、今後、町会・自治会が実施するような地区防災訓練等々に参加していくのに、障害者の方々がストレスなく入っていく、さらに町会のほうもストレスなく受け入れられるような、そのデリケートな部分についていろいろとヒアリングしながら。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、この区内一斉防災訓練についても、この障害がある方の参加を保証していただきたいと思いますし、保証するというかその参加を位置づけていただきたいと思います。それがひいては実際の災害が起きた際の対策にもつながっていくという視点で、障害者７団体など各団体のヒアリングを位置づけていただきたいと思うのですが、その点いかがでしょうか。そこも伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"障害のある方の位置づけにつきましては、先ほどの繰り返しになってしまうのですけれども、参加する方が参加した際にストレスを感じてしまうようだったら、訓練から離れていってしまいますし、受け入れるほうもストレスを感じるようになってしまうと。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、課題の抽出をされているということですけれども、そういう意味でも、障害者７団体のヒアリングをぜひ実施していただきたいのと、実際、どういった方が参加をしているのか、障害がある方の人数とか、そういう実態の把握を位置づけていただきたいと思いますけれども、いかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"障害者の受入れについても、今、福祉部で福祉避難所に避難をされる方と、一般の区民避難所に避難をされる方というのを明確に分けるということもやっておりますので、その辺も具体化したときに、訓練の中にも内容を盛り込みながら。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"福祉避難所に避難される方と、一般の学校に避難される方、今様々整理されているということで、ぜひ進めていただきたいと思います。最後に一言意見だけ。今、様々検討中だということなので、ぜひ参考にしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"すみません。先ほどの質疑で確認したいのですけれども、１０月２１日のヒアリングと防災体験館での体験をされたのは聴覚障害の方たちだけなのか、それとも、ほかの障害種別の方も、ほかの日とかにヒアリングと防災体験館での訓練をされているのか、それとも今検討がされているところなのかというところだけ確認させてください。","respondent":"五十嵐災害対策担当課長","answer":"聴覚障害者団体にだけ、１０月２１日にお伺いなのかということなのですけれども、そのとおりです。聴覚障害者の団体の方々から、東京都と品川区の合同総合防災訓練のヒアリングをする際に、プラスアルファでしながわ防災体験館でご体験をしていただいたというところになります。","id":"exchange-037"},{"speaker":"田中委員","kind":"確認","question":"今後はほかの障害種別の方たちにも防災に関するヒアリングを行って、防災体験館でも体験をしていただくというような、そういう計画はあるのかないのかというところを確認させてください。","respondent":"五十嵐災害対策担当課長","answer":"他の障害者団体でそういった計画があるのかというところで、現在のところはありません。ただ、聴覚障害者団体の訓練がある程度進むようになったら、そちらのほうも進められればなというふうには思っております。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひほかの障害のある方たちにも、ほかの方たちもすごく焦っていますので、いつそういう災害が起きるかも分からないですし、ぜひ早めにヒアリングだったりとか、訓練だったりとか、そういったものに参加できるような体制をぜひ整えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"小芝委員","kind":"確認","question":"は確認をしたいのですけれども、今回の訓練、発災３日後の区の対応を実施されるということなのですが、これは区民避難所での訓練も、同様に発災３日後のことを対象としているのかどうか、まず確認をお願いします。","respondent":"五十嵐災害対策担当課長","answer":"ただ、学校参集職員は、３日後想定の物資の要求等をパソコン等を使って通信しながら対応するというような訓練も、今検討しております。","id":"exchange-040"},{"speaker":"小芝委員","kind":"確認","question":"一応切り離して考えているということで、学校に参集される職員は３日後のことを想定しているということで、確かに発災３日後に避難されることというのはなかなかイメージしづらいものでしたので、それで安心といいますか確認できましたので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"そうすると町会・自治会も、そういう方たちにも声をかけていいのだ、声をかけていく必要があるのだという意識づけになっていくのではないかなと思っていますし、この１２月に開催される中で、もし町会・自治会のほうからそういう方々が参加をされるということで何か必要なことがあるのであれば、ぜひ区にご対応いただきたいと思うのですけれども、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"障害者の方を受け入れるには、私は障害者団体の方々にもいろいろとお勉強していただくことが必要だと思いますし、また、受け入れる町会・自治会の方々にも勉強していただくことがあるのかなと思っておりまして。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問・要望","question":"本当に形骸化していない訓練というのが、品川区はできているといいますか、できているというのは、すみません、上から目線ですけれども、放水訓練は放水訓練、映像を見る訓練は映像を見る訓練、本当に町会の中でしっかりばらけて、それがローテーションで飽きないというか、しっかりそういった訓練の進展というのですか、これが品川区はすごく見えていて、私は非常に感謝しております。","respondent":"五十嵐災害対策担当課長、平原防災課長","answer":"不参加の避難所の対応というか、どうするのかというところの話なのですが、別日で実施したいというところが複数ございました。まだやはりコロナがあるのでというふうなことをおっしゃるところもございました。地域からは、やはり避難所が分かれることによって、役員を２つに分散するといったところの人的な確保等々の問題をいただいているところでございまして、それ以外の各町会との連携という点でまずは工夫していただいているところですが。","id":"exchange-043"},{"speaker":"松澤委員","kind":"提案","question":"そうですよね。やらない町会や、やれない町会の中で、別日というのとコロナというのがあって、やりたくないとかやれないということがないということでよろしいのですか。","respondent":"五十嵐災害対策担当課長","answer":"委員のおっしゃるとおりです。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問・要望","question":"やれない町会がもし仮にあるとしたら、そういうときこそやはり行政の方の支援というか、そういった部分でお声かけしてあげるといいかなと思ったのでこれは余計な心配でした。以上です。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"すみません。ただ、障害者団体の方たちが参加する際に勉強が必要ということがあったのですけれども、勉強と思って、私は訓練に参加するときに勉強していないなと思って、勉強といったのはどういったことを指すのかという、むしろ防災訓練では学ぶ場、知るところなので、勉強は何か必要なのかなというのが私は分からなかったので、そこの部分を教えていただけたらと思います。","respondent":"五十嵐災害対策担当課長","answer":"参加するほうに関しては、今回、ここの訓練ではこういったことをやりますよとあらかじめお知らせしておけば、いろいろなことがイメージできるかなと、次に発展するのではないかなというところの勉強会というか、お知らせというか、そういったものができればと思っていました。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"参加する側にはそういった勉強というか、こういう目的があるよというお知らせがきちんとされるということで、それを理解して参加してくださいねということですよね。分かりました。少し気になったので、伺いました。そういう勉強できる材料が区民の方たち皆に届くということで、理解したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-03","title":"令和４年度東京都・品川区合同総合防災訓練の実施結果","agenda":"令和４年度東京都・品川区合同総合防災訓練の実施結果","exchanges":[{"speaker":"新妻委員","kind":"提案","question":"ご説明ありがとうございました。２点お伺いしたいのですが、林試の森公園の会場のところにトイレトレーラーの展示がありました。少し私もお話を伺わせていただきました。これまで、トイレトレーラーの導入をということで、どうですかという提案をしていますが、そこにトイレトレーラーが展示をされた経緯と、また品川区のお考えをお聞きします。ドローンの活用についてお聞きしたいと思います。","respondent":"平原防災課長","answer":"一方で区の導入といったところにつきましては、どのような形で導入するか。災害時協力協定であるとか、区が所有するとかいろいろな考え方がありますけれども、それぞれに正直まだ課題があるところでございまして、引き続き検討させていただいているところです。","id":"exchange-048"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それで少し気になったのは、西大井広場の外のあれは何だろうな。それから、この表の下から３番目の緊急支援物資のところなのですけれども、この地域内輸送拠点の常時稼働が課題だと書いてあるのですけれども、今この地域内輸送拠点というのがどの辺になっていて、何か所ぐらいあるのかとか、それで物流を協定も含めて検討するとなっていて、その辺、もう少し課題を教えていただきたい。","respondent":"五十嵐災害対策担当課長、平原防災課長","answer":"私からは、会場外の民間ビルの降下訓練のお話と、「真災害」についてお答えします。会場外の民間ビルにつきましては、ニコンの本社ビルになります。そういった中で仮に災害が発生した場合には、直ちに地域内輸送拠点としての開設が難しいという課題もございまして、そういったところから、今回の課題として常時開設、そういったところについてはどのような形で進めていけるだろうか。","id":"exchange-049"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。真災害というのは初めて言葉として聞いたので、今ちょっと衝撃を受けました。今後何か質問で使おうかなと。では地域内輸送拠点というのは、今、品川区は大井競馬場だけなのですね。それと、目黒川会場というところでやったのでしょうけれども、そうすると、東京都から来る物資の受け入れ先が、今後もしかしたらもう少し別の場所でも増やすみたいなことも検討するということなのでしょうか。","respondent":"平原防災課長","answer":"ただ、そういったような問題点もありますので、現状、例えば２４時間稼働できるようなトラックヤードのようなそもそも物流に向いたような施設、こういったところの活用を前提に、検討を進めさせていただいているところです。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、ほかの障害の方たちの参加状況がもし把握できていれば、それを伺いたいということと、その参加がもしあった場合には、そこから見えた課題等があったらお知らせいただきたいということがまず１点です。小山台小学校にそのバスが止まっているのを見て、これほど大型なのだとちょっとびっくりしたのですけれども、３ルートあった中で、バスの利用状況について伺いたい。","respondent":"五十嵐災害対策担当課長","answer":"各臨時バス停のところで待機寮の寮生が対応させていただきましたので、何かありましたら、その待機寮生から介護タクシーの要請という形で、本庁舎に詰めていただいた介護タクシーが現地に向かうということで考えていたところなのですけれども、結果として。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問","question":"バスの利用状況と介護タクシーの状況は分かりました。障害団体の方ではなくて、聴覚障害の個人の方でもいいのですけれども、個人として聴覚障害以外の障害がある方が、参加されたものの把握がもしできていれば、そこの状況をお知らせいただきたかったのですけれども、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"個人としての参加も私の知るところではなかったので、今後、そういったことがあれば、またお知らせしていきたいと思います。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"多分参加されている方もいると思うので、ぜひこれから結果をまとめるといったときには、そういった参加された方からどのような声が聞かれたかとか、そういったことも今度お知らせいただければと思います。要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"当日は私も朝から医療救護訓練を見させていただきました。この訓練開始に合わせて、被災者役の方々が次々と助けを求める姿を見て、この発災時の混乱状況というのは本当にカオスだなと思って想像することができました。今回、こうしたことで行った教訓というのを洗い出して、生かしていっていただきたいと思うのですけれども、この点、１点お伺いしたいと思います。","respondent":"平原防災課長","answer":"医療救護のところの今回の訓練を受けた今後の教訓といったところですけれども、副委員長ご指摘のとおり、まず超急性期における医療活動というものは、なかなか制約が多い中で大変な状況だということもありますが。","id":"exchange-054"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そうすると、その現地連絡調整所の方がすべてを把握してというか、すべてを把握するのはなかなか難しいと思うのですけれども、どういったときにどう対応するのかというのを頭にしっかり入れてやっていかないと、その現場で滞ってしまうなというふうに思いましたので、そこはぜひスムーズにいくようにしていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170605?Template=document&Id=6626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":44463,"voices":138}},{"id":"r04-20221108-4","meetingId":"r04-c-settlement","date":"2022年11月8日","dateIso":"2022-11-08","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和３年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"おはようあります。今日からの決算特別委員会、７日間しっかりと審議していきたいと思いますので、どうぞよろしくお願いいたします。質問は、６０ページの特別区交付金、特別区財政調整交付金を含め、決算全般についてと、９０ページの国庫支出金、衛生費負担金に関連した内容でお聞きしたいと思います。それから執行率なのですが、今回、約９１.６％と、前年の９４.７％に比べて低下しています。","respondent":"黒田財政課長、坂野保健予防課長","answer":"経常収支比率が２３区の平均より悪いのではないかというご指摘ですが、経常収支比率は、おおむね８割を下回っていれば良好と言われておりまして、これが１００％に近づきますと財政が硬直化して。それでも内容自体はあまり大きく変わっておりませんので、積極的疫学調査、あるいはそれに伴う療養の調整、特に介護関係などがある方はそういった調整が結構複雑になってまいりますので。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その点に関しまして、それから、こども家庭庁でいくと妊産婦ということも出てきますので、保健師の数というのはやはり重要な問題だと思うのですが、その辺、何か課題があるのかという点を１点お聞きしたいと思います。それから児童相談所の開設も考えた場合に、やはり財政調整交付金から出る部分が大きいと思うのですが、どのぐらい見込んでいけるのか、歳入という点で確認をさせてください。","respondent":"若生健康課長、黒田財政課長","answer":"今後、介護の部門あるいは子ども家庭支援センター、それから児童相談所といったところへの保健師の配置が求められてくるということで、今現在、庁内に、健康課に統括保健師ということで１名置いておりまして、人材の育成等、統括的に。いわゆる特別交付金の、これからの、特に協議項目としての重要な項目のご指摘だと思いますけれども、高校生等の医療費助成につきましては、令和５年度の４月から、２３区が足並みをそろえて。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財政調整の問題は大変難しく、私もまだ分からないところがいっぱいある。基準財政需要額の算出のための項目設定も、品川区にとっていい方向にやれば歳入が増えてくるとは聞いているのですけれども、その辺がなかなか調整できないので、議会側として十分には分からないところなので、専門の中で、品川区にとって有効な形を取って、調整も進めていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"３点お伺いいたします。６５ページ、シルバー人材センター、９３ページ、個人番号カード経費、１２５ページ、感染症対策事業に関連いたしまして、それぞれお伺いしてまいります。私たち公明党として求めていることは、この大きな波が起きたときにどういう対応をしていくのかということ、区民の皆様が困らないためにどういう対応をしていくのかということを求めてまいりました。","respondent":"坂野保健予防課長","answer":"前回、議会でご質問いただきまして、コールセンターの強化ということで、なかなか増員は、かなり難しい部分もあって、やはりＩＴの力を借りて機能強化をしていこうということでございまして、増員と並びまして、コールセンターに、自動応答装置、ＩＶＲと言いますが。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都もかなり抱えてくださっているので、品川区の保健所の負担は少なくなっていることと思いますが、いざ感染爆発が起きた場合に備えて、しっかり体制を整えていただき、区民が不安に思わない体制を求めたいと思いますので、どうぞよろしくお願いいたします。続きまして、シルバー人材センターについてお伺いいたします。３４４万円、計上されております。この内訳をお知らせいただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"何の内訳か聞こえませんでした。申し訳ございません。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"ではすみません。内訳は結構です。求めるものと、また、そこまではできないというシルバー人材センターとのマッチングがあるのですけれども、ここに対してのマッチング状況ということを少しお伺いさせていただきたいと思います。ホームページには、令和４年１０月１日現在の新たな金額が出ておりますので、そのことも踏まえて、ぜひパンフレットに反映していただきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"大変失礼いたしました。先ほど６５ページのシルバー人材センターの内訳ですが、品川第一地域センタービルの管理費負担金ということで、こちらはシルバー人材センターが事務所として借り受けておりまして、そこの部分の光熱水費等を払っているという部分の金額です。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"求めることが、やはり、なかなかマッチングが難しいところもあると思うのですけれども、多くの人材をシルバー人材センターに募集していただき、受けていただける方法を、ぜひまた品川区からもお伝えいただきたいと思いますので、よろしくお願いいたします。例えば都営住宅、区営住宅、高齢者の多いところでの出張申請サポートを進めていただきたいと思いますが、いかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"マイナンバーカードの件で、出張申請サポートですけれども、イトーヨーカドー、青色申告会など、方々でやっております。全部で１,０４２件ほど申請があったです。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"９８ページ、感染症予防費、１６７ページ、議会費、１１７ページ、区内私立保育園経費、関連して区立園についても伺います。時間があれば１３２ページ、埋蔵文化財調査費、広町御料車庫について伺います。初めに、コロナウイルス感染症対策について伺います。現在、第８波が始まっていると警戒する声が聞こえてきます。","respondent":"坂野保健予防課長","answer":"こういったコロナの後遺症は小児には限らないものではあるのですが、東京都でも、コロナウイルス後遺症の研修をやっておりまして、直近、１１月２０日に予定されているのですが、そういったものにも職員を積極的に参加させて、スキルアップを図ってまいりたいと考えております。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて議会費について、委員会中継について伺います。区議会事務局に調査を依頼し、２３区と市部の議会のインターネット映像配信状況について確認しました。この２つの調査結果を基に質問をします。品川区議会でもぜひ進めていただきたいと考えますが、現在進められない課題がどこにあるのか伺います。品川区でも、デジタルサイネージの活用も含めて進めるべきと考えますが、見解を伺います。","respondent":"坂野保健予防課長、工藤区議会事務局長","answer":"小児の後遺症の件です。教育委員会からご相談等があれば、保健所でも相談に乗らせていただいて、考えていきたいと考えております。実施の可否につきましては、やはりこれまで、議会改革の各会議体において、ご議論され、検討され、決定してきた経緯があります。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"後遺症の部分です。品川区情報公開・個人情報保護条例の目的に掲げられている区政の透明性を確保し、区民と区政との信頼関係の強化につながるように、品川区議会として情報公開手数料を無料にすることを求めますが、見解を伺います。しかし、今、過去の議員一人ひとりの活動が注目されているため、現在保管されている資料は一定期間、５年を経過しても保存しておくべきだと考えますが、見解を伺います。","respondent":"工藤区議会事務局長","answer":"これは議会の規定の中でも、区の条例と同一での取扱いというところで運用しています。それから、最後の保存期間の件につきましては、現状は５年というところで位置づけしておりますので、そのように運営をさせていただいているところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"次の質問に続きます。置き去り事案について伺います。私立園では、１歳児をエレベーター内に置き去りにしてしまって全く気づかず、同じビルにいた職員の方が「この子はそうではないですか」と声をかけてきた事例。区内保育園の保育の質を維持・向上させるために、園の名前などは要らないです、事故報告と再発防止に向けた対策についても、市民に分かるように公表すべきと考えますが、見解を伺います。","respondent":"工藤区議会事務局長、中元保育支援課長","answer":"保存期限の件です。こちらは、やはり議会改革等の各会議体の中でまずはご議論され、結論を出されるべきだと考えています。議会の中で合意形成が図られるということであれば、事務局としましてもその手続を進めてまいるです。置き去りの事故報告の件ですが、こちらは、公立保育園、私立保育園と、それぞれの課に報告をいただいておりまして、また、その中で、今後の対策につきましても、公・私立保育園地域連携協議会で。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"事故報告の公開、再発防止策の公開についても伺ったので、再度伺いたいと思います。区として区内保育園の安全を向上するためには、やはり区として独自の保育士配置基準を１歳以外にも設け、保育者の目と手を増やし、子どものための保育、そして命を守る保育が実行されるようにすべきと考えますが、見解を伺います。","respondent":"中元保育支援課長","answer":"事故報告の様式につきましては、今後確認させていただきまして、どのような形が適切なのかというところを引き続き研究してまいりたいと思います。配置基準におきましては、現在のところ、適正に配置されているところと考えておりますが、今後の課題として受け止めします。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそこの部分も公開を求めたいのですが、もう一度伺いたいと思います。次に、財務情報について伺います。２０２０年１０月の決算特別委員会のときに、事業者側の財務情報の記入不備・不足を指摘し、改善を求めました。ほかに、人件費割合の計算が合わない。収支報告の空欄が多い事業者。区としてのチェック体制と、記載不備に対して事業者にどのような改善を呼びかけているのか改めて伺います。","respondent":"中元保育支援課長","answer":"不備なところがございましたら、これは最終的には東京都が責任を持ってチェックするものですので、東京都から不備事項の修正等について指示があり、それについて対応しています。今後につきましても、鋭意、精査して、点検してまいりたいです。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、１４ページ、特別区財政調整交付金、９７ページ、児童相談所移管推進事業、代替職員雇用経費、１１２ページ、人権啓発活動費補助金、１２４ページ、地域自殺対策強化交付金についてお伺いいたします。１点目に、児童相談所移管推進事業についてお伺いいたします。そこでお伺いいたします。そして２点目に、特別区財政調整交付金についてお伺いいたします。そこでお伺いいたします。","respondent":"長谷川児童相談所移管担当課長、黒田財政課長、崎村人事課長、加島人権啓発課長","answer":"区としましては、子ども家庭支援センターと連携し、児童虐待の未然防止に努めるとともに、社会全体へのさらなる意識啓発に努めるべく。区長会で、総務省に清掃移管時の割合の変更などの経緯の法的な見解を求めておりまして、そういったところから、特別区の児童相談所設置は。もし品川区役所で、職場内で自殺者が出たときの対応というご質問ですけれども、これは特にマニュアル等を定めているわけではございませんが、ただ。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"時間がなければ衛生費のところでお伺いできればと思います。一言で構いません。こうした映像作品は様々な活用の仕方があると思いますが、映画「ほどけそうな、息」を、安田真奈監督のＮＨＫドラマ「やさしい花」などとあわせて、品川区で、児童相談所準備に関わる部署に異動するタイミングで、ぜひ活用していただきたいということを要望いたします。","respondent":"坂野保健予防課長、長谷川児童相談所移管担当課長","answer":"先ほど人事課長からもお話があったのですが、保健センターでどういう相談をしているかということは、一般的なお悩みの相談以外に、品川区のユニークな取組といたしましては自死遺族の会をやっておりまして。ニュース等で負の側面が取り上げられることが多い児童相談所……。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、９２ページ、衛生費負担金、新型コロナウイルスワクチン接種負担金から、乳幼児の新型コロナワクチンについてお尋ねいたします。１１月からいよいよ、６か月から４歳の乳幼児コロナワクチンの接種が始まります。最後に、現在接種の続いている５歳から１１歳の小児用コロナワクチンの接種率、接種数およびその評価について、参考にするために一緒にご説明をお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"年齢によって、もしくはお子様の体形によって接種の部位が異なること、また接種後の副反応が出た場合、的確な対応をしなければならないことなどを考慮したことによるものです。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"確認","question":"４歳以下の１４人のうち６人は、基礎疾患がない、もともと健康な子どもでした。乳幼児コロナワクチンは、ファイザー社が生後６か月から４歳の子どもを対象に臨床試験を行った結果、３回接種後には、年長児や大人の臨床検査の結果と同じレベルまで抗体が上昇することが確認されました。心配な乳幼児のコロナワクチンの副反応を、現在、区はどのように理解しているでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"倦怠感、下痢、それから３８度以上の発熱が主に見られるということが書かれておりまして、また生後６か月から１歳につきましても、不機嫌になったり、食欲不振になったり、やはり３８度以上の発熱の症状が見られたようですが、重い副反応は認められなかったという報告がされて。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"確認","question":"本ワクチンの３回目接種から１か月後、免疫原性が事前に規定された基準を達成したこと、オミクロン株等に対する中和抗体価の上昇が確認されたこと等から、一定の有効性が期待されるとされています。区としても、小さな子どもをコロナから守るために、もう少し積極的なコロナウイルスワクチンの啓発に取り組むべきだと思われますが、区の考えと現在の取組についてご説明をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"関係所管とも連携しながら、こうしたものが保護者の方の目につくよう、行き渡るよう、そういった方法を今後検討していきたいと考えています。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"提案","question":"中立的な立場の講演会の開催などもいかがでしょうか。これは要望といたします。もう今現在でも保育園とか小学校とか増えてきているので、先週も小学校で学級閉鎖がありましたけど、小さなお子さんをコロナ感染症と、あるいは起こるかもしれないインフルエンザの感染症から守るために、ぜひこの冬は、区の関係者の方もより一層のご努力をお願いしたいと思いまして、私の質問を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"９８ページの新型コロナウイルスワクチン接種体制確保事業費補助金、５２ページの特別区民税をお伺いします。目黒区とか大田区とか世田谷区とか、城南５区と言われているところはほとんど減少しているのですけれども、品川区は増えているのですけれども、この辺の何か情報、ほかの区ではこんなことが原因で減ったのだとか、品川区はこういうことで大丈夫だったのだとか、その辺がありましたら教えてください。","respondent":"坂野保健予防課長、提坂税務課長","answer":"９月２６日以降の発生届のシステム変更ですが、９月２６日以降は、先ほどもお話があったところなのですが、４要件を満たす方だけ発生届が上がってきて、そこには、発生届ということで患者の住所が書いているということがあります。品川区においては幸い、増収になったのですけれども、まずは我々税務課の職員一人ひとりのモチベーションを上げて一生懸命取り組んでいるということで、具体的には、従来から行っているところですけれども。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問・要望","question":"コロナのほうは、保健師は本当に引き続きいろいろな形で決して業務が楽になるということはないとは思うのですけれども、保健所全体でいろいろな業務が少し削減されてきて、これから第８波に向けての対策、対応、いろいろあると思いますけれども、しっかりそこに充てていただきたいと思うのですけれども、そうすると、品川区の数は。","respondent":"提坂税務課長、渡部委員長","answer":"それに伴って納税義務者数も３,９００人増加しているのですが、その中で年齢別で分析しますと、５０歳から６５歳の所得が高い方が増えたのではないかということで。第二委員会室の品川区保健所および健康課の関係理事者の方々もご退席ください。ありがとうございました。進めします。次は石田ちひろ委員ですが、本日欠席のため、次に進みます。質疑を続けます。次に、松永委員。","id":"exchange-022"},{"speaker":"松永委員","kind":"確認","question":"私からは、５４ページの特別区たばこ税、１１２ページの喫煙環境整備事業補助金、１４４ページのふるさと納税寄附金について伺いたいと思います。そこで質問ですが、区のホームページを確認させていただいたところ、「ふるさと納税により品川区の財源が失われています」と、切実な思いが掲載されており、返礼品の種類も１６種類と増えていると思います。","respondent":"提坂税務課長","answer":"昨年度の品目としてベスト３ですけれども、１番目が、フライトシミュレーターの操縦体験３０分コース、２番目が、しながわ観光大使シナモロール３体セットぬいぐるみ、３番目が、先ほど申し上げた『シナモロールのわくわくしながわさんぽ』の絵本です。","id":"exchange-023"},{"speaker":"松永委員","kind":"確認","question":"そういった形で頑張っていただければと思うのですが、確認です。品川区では返礼品以外にも、応援したい事業へふるさと納税を希望する方へとあり、子ども食堂への寄附と、ブラインドサッカー応援プロジェクトの２つのみでしたが、ほかにはありますでしょうか。","respondent":"提坂税務課長","answer":"現在はその２品目だけかと把握しています。","id":"exchange-024"},{"speaker":"松永委員","kind":"意見","question":"他の自治体では、福祉施設の建設費に充ててほしいとか、各種団体の応援に充ててほしいという取組をされているところもあります。そして、受け取った側から写真やメッセージを添付するなどを行えば、また一層深まるのではないか、品川区に寄附したいというような思いをされる方が増えるのではないかと思うのですが、区の考えをお聞かせください。","respondent":"提坂税務課長","answer":"これに対して、区内在住の方、それから区外在住の方から、どの程度の賛同を得ることができるか、寄附をいただけるか、それから費用対効果など個別の事例についても、各担当する主管課で調査・分析する必要があると考えてございまして、今後の研究課題と捉えておりますけれども。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"次に移ります。５４ページの特別区たばこ税の収入が、予算当初に比べて約２億５,０００万円ほど差が出てきております。そうした中、品川区では喫煙所の整備や廃止を進めておりますが、この状況を考えますと、廃止や撤去ではなく、整備を進めたほうがいいと考えますが、税収入も含めて、今後の喫煙所のあり方について区の見解をお願いします。","respondent":"森田生活安全担当課長","answer":"現在、９か所のうち１か所を一時閉鎖という形にはしておりますが、廃止という形では進めてはおりません。現状のところでは、大崎駅東口のコンテナ喫煙所設置であるとか、そういったものは、現在の状況の中で進めさせていただいているところです。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"こうした中で、先ほどもありましたが、大崎駅はコンテナ式のスペースをつくっているということですが、ほかのエリア、例えば大井町でも２か所あるのですが、そちらについてもコンテナ式にしてはどうかと思います。それはなぜかというと、すぐ横が歩道になっておりまして、特に陸橋の下ですけれども、ベビーカーを押している方やお子さんなどがすごく通られるのです。例えば武蔵小山もそうです。お願いします。","respondent":"森田生活安全担当課長","answer":"空き店舗についての、喫煙所等の活用についてです。現状、空き店舗を利用して品川区で喫煙所にしようという取組については、現在は検討しておりません。ですが、現在、民間喫煙所の補助要綱を策定しています。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"５２ページ、特別区民税、１３７ページ、衆議院議員選挙執行費をお伺いします。税金のほうから伺いますけれども、国民の三大義務とは何でしょうか。お答えください。","respondent":"提坂税務課長","answer":"国民の三大義務は、納税の義務、教育を受けさせる義務、あと勤労の義務です。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"大切なことだと思って質問しますが、区民税の徴収率、それとも収納率、これは、まずどちらが正しいのでしょうか。答弁も含めて、徴収率か収納率かも含めて、どのぐらいなのか教えていただけますか。","respondent":"提坂税務課長","answer":"直接税金を集める、徴収する部門からは、徴収率という言い方をしていることが多いようです。それで、徴収率につきまして、令和３年度におきましては、特別区民税については過去最高の９９.１２％を記録いたしました。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"たしか、順位的に言うと２３区でずっと２位だったのですけれども、そういう意味では、順位で競うわけではないですけれども、もっと限りなく１００％に近くしていただきたいと思うのです。だって納税の義務ですから、税金は払っていただくことが義務ですから、そういう思いも含めて、課長、いかがでしょうか。","respondent":"提坂税務課長","answer":"９９.１２％という数字は限りなく１００％に近い数字ではありますけれども、残念ながら２３区の中ではまだ２位ということで、１位が江戸川区です。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう意味を持って、課長、ぜひまた１位に復活していただきたいと思うのが１点と、もう一点は今言った照会システム。これはすごいですよね。だって、区民税は、前年の所得があって、それにかかるわけですから、前年の所得をキープしていてくれれば払えるわけですよね。それを使ってしまったりして払えませんというのはルール違反だと思うので、その辺についてはいかがでしょうか。","respondent":"提坂税務課長","answer":"その１位を目指すために、預貯金照会システムというものを導入しまして、従来は回答まで一、二か月を要していたものが、一日、二日で回答が返ってくるということを踏まえて、差押え件数についても、昨年度、約２,６００件実施しているのですけれども。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"選挙についてお伺いします。でも、区議会議員および区長は、その印刷代は出ませんよね。国は国、都は都、区は区という意味において議会があるわけですけれども、私はそういう区別というのはなしにしていただいて、区議会議員の選挙、区長の選挙も、法定はがきの印刷代は公費で出るべきものだと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ところが、ご質問いただいた、はがきの印刷代につきましては、その根拠規定がないというところで、根拠がないということで、区の条例での公費負担の定めの中に入っていないです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"つくればいいじゃないですか。民主主義の根幹なのですから。これはおかしいんじゃないですかと。そうしたら、今回の区議会議員補欠選挙・区長選挙においては１.１倍になったじゃないですか。それで二十何万円、お給料をお支払いしているわけですから、こういうふうに議会で話が出ましたというのを、回数を増やしてでも議論していただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のとおり、もしその必要性もしくは実施の可否について検討することになれば、選挙管理委員会にかけて、議題として正式に検討したいと考えております。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"我が会派の須貝委員が、時給１０万円とよく言うじゃないですか。渋谷区、日額２万５,０００円です。だから、そういう意味において、せっかく今、選挙管理委員会があるわけですから、選挙管理委員会はきちんと選ばれているわけですから、こういうことも含めて、やはり通常のときでも回数を増やして、どんどん議論をしていっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"先ほど申し上げましたように、法的に可能であれば検討はいたします。委員会の回数につきましては、委員長の判断、それから選挙時の必要がある場合においては回数を増やすことが可能ですので、その辺もあわせて委員会で話し合いたいと思います。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"私からは歳入において、５４ページ、特別区たばこ税、６８ページの公園運動施設使用料について質問します。子どもたちの安全と健康を願って、受動喫煙のない品川区を目指していきたいので、たばこ税を使って喫煙所をしっかり確保してほしいと考えています。現在、区で管理している喫煙所は９か所、うち１か所が閉鎖ということですが、今後の増設の予定、喫煙所の設置の計画を伺います。","respondent":"森田生活安全担当課長","answer":"品川区におきましては、現在９つの喫煙所があります。今後の計画にございましては、現在、大崎駅西口に喫煙所はありますが、そちらにつきましてはコンテナ化のリニューアルを検討しています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"その後、露天型の喫煙所は閉鎖されて、コンテナ型の喫煙所が設置されたということですが、開設して半年と少したちまして、周辺の吸い殻のポイ捨てや路上喫煙などの環境は改善されていますでしょうか。その状況と、また、ほかにご意見が寄せられているものがございましたら伺わせてください。","respondent":"森田生活安全担当課長","answer":"大崎駅東口コンテナ型指定喫煙所につきましては、本年の４月２０日に開所しております。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"公園運動施設使用料について質問します。息子がサッカー少年で、小学校のサッカーチームに入っておりまして、イベントや試合などで度々、公園運動施設を利用しています。このしながわ中央公園の多目的広場は、学校をはじめ、様々な団体が利用していると思いますが、年間でいうと何日ぐらいの利用があるか教えていただきたいと思います。あわせて、この施設の利用方法を伺います。","respondent":"辻スポーツ推進課長","answer":"公園運動施設についてのお尋ねかと思います。しながわ中央公園の多目的広場ですが、土日についてはほぼ満杯、数字については今ちょっと持ち合わせはないのですが、平日も、昼間は学校がお使いになられているときもありまして、ほぼ８割から９割は埋まっているという状況です。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"ほかの運動施設では、インターネットや電話での利用申込みができるということなので、郵送ですと時間もかかってしまいますし、利便性を考えたシステムを導入して、デジタルで完結できるように、時代に合わせて改善したほうがいいと考えますが、往復はがきとオンラインの申込み、併用でできるように選択肢を増やしていくのはいかがでしょうか。","respondent":"辻スポーツ推進課長","answer":"例えば教室等では、往復はがきを使ってのお申込みというのはさせていただいているのですけれども、グラウンドを取るだけの場合には今のところはやっていないところです。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"登録していれば、オンライン上で申込みができるということで、かしこまりました。ありがとうございました。いつもたくさんの少年少女、大人まで汗を流して楽しんでおられますが、ほかの公園運動施設では一般開放を行っているか、状況を伺います。","respondent":"辻スポーツ推進課長","answer":"例えば鮫洲運動公園というところがございまして、子ども向けのところなのですが、そちらやはり朝、自由に使っていいというふうに開放しております。","id":"exchange-039"},{"speaker":"せらく委員","kind":"意見","question":"品川区は小さい公園が多くて、ボール遊びもできない公園もありますので、子どもたちの体力向上のためにも、利用がない場合の公園運動施設は積極的に開放してくだされば、子育て世代の皆様の満足度がさらに上がるのではないかと思いますので、ぜひご検討いただけることを願います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、１１３ページの生活安全活動費から、まもるっちのことを伺います。１４４ページのふるさと納税寄附金、時間があれば１１３ページのオリンピック・パラリンピック開催周知事業についてお伺いします。最初にふるさと納税からお伺いします。決算・予算のところで何度も、ふるさと納税についてお話をさせていただきました。","respondent":"提坂税務課長","answer":"流出額の対応はなかなか難しいところがあって、これから研究してまいります。","id":"exchange-041"},{"speaker":"芹澤委員","kind":"質問・要望","question":"流出のところに関連して、今日、冒頭、和氣副区長からもお話がありましたが、物価高騰のところが今、品川区の多くの方のお悩みになっているかと思います。例えば、令和２年度に、特別区全国連携プロジェクトのときですか、福井県坂井市と連携して、ふるさと納税をしていただいて、ひとり親家庭への米の宅配というものをやったかと思います。ご見解をお聞かせください。","respondent":"提坂税務課長","answer":"友好都市や災害拠点都市など、様々お付き合いのある自治体もありますけれども、そちらで品川区に関連する取組の企画があれば、最終的にはそれぞれの自治体が主体的に企画・実施していただくものですけれども、積極的に情報提供をしていって。","id":"exchange-042"},{"speaker":"芹澤委員","kind":"提案","question":"以前もふるさと納税について１つ、疑問というか提案を投げさせていただいたのは、やはり今、税務課長もお話しいただいたとおり、ふるさと納税はシティプロモーションの観点でというようなお話があり、流出に対してもこれから他の自治体との連携というところで、ふるさと納税は税だからといって税務課が主として対応するのは、なかなか難しいのではないかというのはいまだに思っていまして、２３区の中でも。","respondent":"森田生活安全担当課長","answer":"現在、委員がおっしゃられました協力者につきましては、令和３年度で１,９１４人となっております。この方々に対する通報につきましては、現在のところ、実績はございません。","id":"exchange-043"},{"speaker":"芹澤委員","kind":"質問・要望","question":"まもるっちですから、何か児童が身の危険を感じた際に防犯ブザーを鳴らして、その情報が地域の方々に連絡・連携されると。それは本当にいいことなのだと思いますが、今の時代を考えると、やはりメールで連絡というのがどうなのかと思う次第で、なかなかメールをリアルタイムで見る方がいらっしゃらないのではないかと思っています。そういったところに関して、まずご見解をお聞かせください。","respondent":"森田生活安全担当課長","answer":"１年に１回は訓練を行いまして、メールアドレスに、訓練ですということで発報しまして、それで現場に集まっていただく訓練も実施しています。","id":"exchange-044"},{"speaker":"芹澤委員","kind":"意見","question":"地図を添付してということでありますが、今、私はスマートフォンを使っていますけれども、基本的に画像も送れる機種がほとんどなのではないかと思います。まもるっちについてなのですが、一部の公営住宅、区民住宅や区営住宅で、電波が届かないというようなご連絡もいただいていまして、家の中も含めてですが、児童の安全確保というのを、まず区はどこまで保障していくべきだとお考えか、お聞かせください。","respondent":"森田生活安全担当課長","answer":"そういった意味では、そういった時間帯における児童の安全につきましては、万全を期していくように実施していきたいと考えています。","id":"exchange-045"},{"speaker":"芹澤委員","kind":"提案","question":"区営住宅等に関しては、いろいろ交渉は必要なのだと思いますが、まもるっちは当然、全てＫＤＤＩの電波だと思いますので、アンテナの基地局を設置するというのも１つの解決策になろうかと思っています。最後、１１３ページ、オリンピック・パラリンピックに関して、レガシーとしてボッチャの大会をというのを以前からご提案させていただいていました。","respondent":"辻スポーツ推進課長","answer":"先日の土曜日も、地域スポーツクラブのボッチャの大会がございまして、２０チームが集まって熱戦を繰り広げました。１０歳ぐらいの小学生から８０歳を超える方までが混ざり合ってやる、非常にすばらしいスポーツだと考えています。","id":"exchange-046"},{"speaker":"芹澤委員","kind":"提案","question":"私はボッチャを区の公式スポーツにもしたほうがいいのではないかというご提案も以前したことがありますが、やはりボッチャというのは、体力もそこまで求められずに、子どもたちや高齢者や障害者が混ざり合ってできるスポーツだということでお願いしているところでありますが、なかなか大会でも、障害者の当事者の方が実際にボッチャをやっていなかったりというのは、残念ながら見られていて。","respondent":"辻スポーツ推進課長","answer":"ボッチャ大会、障害者の当事者の方にも出ていただくというのは、こちらからの投げかけや問いかけの形が必要かなと考えています。広報の仕方も、いろいろな形で工夫しながら、地域のいろいろな方が参加して混ざり合えるような大会を、これから研究していきたいと考えています。","id":"exchange-047"},{"speaker":"おくの委員","kind":"質問","question":"昨年、荏原第一地域センターと荏原第一区民集会所が武蔵小山駅前に移転しましたけれども、移転前には集会所の使用料を払いさえすれば、それ以上の負担がなく、放送装置やマイクなどの設備を使えていたのに、移転してからは、それらの設備の使用料を別に取られるようになったと、利用者の方から伺いました。なぜ設備の使用料を有料にしたのでしょうか。伺います。","respondent":"川島地域活動課長","answer":"新しくきれいな施設で使っていただくですので、有料化についてもご理解をいただきたいと考えています。","id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、建物の改築でなくても、古くなれば、新しい設備が導入されることはもちろんあるのですけれども、そのような設備だけの更新によっても有料化していくというのが区の方針なのでしょうか。その点、伺います。","respondent":"川島地域活動課長","answer":"区民集会所の設備の使用料につきましては、区民集会所を改築したり新しくなったときには、料金をいただくような形で順次行ってきたところですので、区の方針というふうな考え方で言っても差し支えないと思います。","id":"exchange-049"},{"speaker":"おくの委員","kind":"質問","question":"今の説明ですと、設備が新しくなったからというよりは、区民集会所自体を改築したり、区民集会所自体を新しくしたときに、それをきっかけに、区民集会所自体の使用料ではなくて、設備の使用料を有料化するという理解でいいのでしょうか。もう一度、念のため伺っておきます。","respondent":"川島地域活動課長","answer":"当然、建物等が新しく更新された際は設備も新しくなるということで、今ご質問のとおりのご理解でよろしいかと思います。","id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"念押しなのですけれども、設備が新しくなるということなのですけれども、建物は古いままで設備だけを新しくする場合もありますよね。そういう場合はどうなるのですか。念のため、もう一度お伺いしますけれども、そういう場合も値上げする、有料化するということなのでしょうか。","respondent":"川島地域活動課長","answer":"現状では、建物が新しく建て替わった際、そのタイミングで設備使用料について有料にしていくというような形でやってきております。","id":"exchange-051"},{"speaker":"おくの委員","kind":"質問","question":"それからもう一点、お伺いしておきたいのですけれども、今は設備のことをお伺いしましたが、集会所の使用料の決め方のことも同時に伺っておきたいと思います。施設によって上限等はあるのですけれども、最小限ということで、３割というようなところを目安にして考えていると、当時の行財政改革担当課長が答弁されているのですが、こういう考え方は今も同様だと考えてよろしいのでしょうか。伺います。","respondent":"川島地域活動課長","answer":"その当時のお話のとおりの形で料金の設定がされていると認識しております。","id":"exchange-052"},{"speaker":"おくの委員","kind":"質問","question":"第一区民集会所の使用料は、午前中は２,６００円ですし、夜は５,２００円です。ですから、午前中はそれまでは２,６００円で借りられていたものが、現在は新しくなって、８２０円をそれにプラスして払わないといけないので、３,４２０円払わないといけない。その点、伺っておきます。","respondent":"川島地域活動課長","answer":"部屋の使用料につきましては、ほぼ増減がなく、新しい建物になっても同じような体系の料金をいただくというように設定しているところですけれども、繰り返しお話ししておりますが、改築したということで、設備使用料につきましては新たに徴収するような形に変更させていただいて。","id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"値上げしたということなのですが、そうしますと、最初に戻りますけれども、なぜ改築したことをきっかけに使用料を値上げされたのでしょうか。それは結局、新しくなったからとおっしゃるのですけれども、新しくなったらなぜ値上げするのでしょうか。この点、伺っておきます。","respondent":"川島地域活動課長","answer":"こちらは今、免除や減額で使っていただいている方について、設備使用料についても半額になったり免除になるというときに適用されますので、そういった部分を含めて有料の設定をさせていただいているということになります。","id":"exchange-054"},{"speaker":"おくの委員","kind":"質問","question":"結局、値上げされたということに対して、なぜかということに対して、お答えがないと思います。区民集会所は、区民の皆さんが、学習活動や文化活動、それからボランティアなどの拠点として、非常に便利に使っていらっしゃいます。このような値上げは撤回していただいて、元のとおりに戻していただくことを要求して、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"くにば委員","kind":"質問","question":"本日は、８２ページ、廃棄物処理手数料、粗大系、また５４ページ、特別区たばこ税、および１２５ページ、受動喫煙防止対策費です。粗大ごみのリユース事業を、株式会社ジモティーと提携し、９月末からスタートしたばかりです。それで、まずはお伺いします。まだスタートしたばかりですけれども、ジモティーとスタートしたリユース事業、これまでの利用実績や例えば来場者数、その辺りをお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"引き取った件数が１５９人です。それから、チョイスした品目が３１９点となっています。一部有料で販売もしておりまして、１か月の売上げが４万７,０００円という形になってあります。","id":"exchange-056"},{"speaker":"くにば委員","kind":"意見","question":"こちらは週１回、日曜日だけ、八潮にある品川区の資源化センターに、わざわざ直接取りに行かなければいけないということで、若干不便かなと思っていたのですけれども、ある程度の利用実績がある。例えば、１回当たり何品までという制限をしたり、あとは月間で何品目という設定をしたり、そういった転売防止策、どのような転売防止策を取っておられるのでしょう。お聞かせください。","respondent":"品川品川区清掃事務所長","answer":"ですので、一応、引取りをするときに本人確認というような形を取らせていただいて、それでまた今後、状況を見て、複数回、それから数量も多く引き取る方、そういう方につきましては少し注意を促すとか、そのような対応は想定しているところなのですが、まだ現在。","id":"exchange-057"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう一点伺います。現在、取扱いの品目が、テーブル、棚、カラーボックスなどの家具、あとは電子レンジ、扇風機、空気清浄機などの家電、ゴルフ用品などのスポーツ用品、あとはベビーカーやチャイルドシートなどの子ども用品の４種目に限られているのですけれども、なぜ、この４種目に限られているのか、また、今後どういった品目に広げていく予定とか可能性があるかというのをお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"品目につきましては、基本的にはまず粗大ごみで出されているものというところが対象になりますので、区が扱う粗大ごみの範疇の部分について、これからもやっていきたいと考えています。","id":"exchange-058"},{"speaker":"くにば委員","kind":"質問","question":"「多分それは持っていかれたのだと思います」という形で、私が住んでいるマンションは団地なのですが、そこでも使えるものがまだまだ捨ててあったりして、本来であれば区が入手できた資源を、その方が、何ですか、盗品というのですか、本来は区が収集するものであったものを、資源抜き取りといった形で、明らかに違法な行為をされていると思いますので、きちんとそこに関して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"つる委員","kind":"確認","question":"午前中の質疑なども含めて、区民税についての状況などは確認できたところがありまして、先ほど、たけうち委員の質疑のときに、区民税に関して、人口の１０％に当たる方が、これは所得だと思うのですが、７００万円以上ということ、ただ区民税の４割を占めているということで、約２００億円ぐらいの区民税がその方たち、人口の１０％で４万人ぐらいでしょうか。","respondent":"黒田財政課長","answer":"財政調整交付金も一般財源では大きなところですが、税収の中では、固定資産税でありますとか、特に法人住民税の影響が大きいというところがありますので、いわゆる２３区の域内で、企業活動が活発に行われるというところも税収増につながるのではないかと考えています。","id":"exchange-060"},{"speaker":"つる委員","kind":"確認","question":"人口が増える要因というのは行政のサービスだけではないというのは、当然、質疑の中でも確認しているところなのですが、品川区の人口は１０年間で約５万人、出入りも当然、変遷はあるのですけれども、５万人が増えているというところ。それは要因ですね。ファミリー世帯はそんなに多くなくて、転入が、これは少し前の数字ですけれども、３.何％とか、そういうのがあったりする。それを教えてください。","respondent":"佐藤計画担当課長","answer":"年齢層的には、２０代の若い単身の方の転入がもともと多かったので、その部分で増えてきたというところが現状です。","id":"exchange-061"},{"speaker":"つる委員","kind":"提案","question":"ただ、それを世帯でクロスで見られるのかどうかというのは、私も事前には確認できなかったのですが、表現はなかなか難しいのですけれど、自治体が歳入を増やす、そのメインが住民税などとなってきたときに、当然、人口が増える。もしくはこれまでの、この約１０年間でもいいですが、どういう部分を特に評価しているのか教えてください。","respondent":"佐藤企画調整課長","answer":"最近ですが、中間所得層も含めた支援につきましては、区では所得制限を設けずに実施している事業も様々あります。","id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"区民住宅のところについて、この歳入の時間の中で確認しようと思ったのですが、残り時間も僅かなので、改めて歳出のところでやりたいと思いますが、この間確認させていただいて、今、一応全体で４３戸ということで、これは、完全な空き室だけの維持管理で１戸１か月当たり４万円というのが１つ数字であるのですが、平均すると今８種類の使用料があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"西村委員","kind":"質問","question":"順不同ですみません。１０８ページ、民生費負担金から在宅子育て支援、家事用品の購入支援について伺ってまいります。は児童手当について伺います。しかし、２０２２年１０月の児童手当支給分から、制度改正により支給されない世帯が出てきます。所得制限については様々議論がありますが、まずは児童手当の所得制限で受給対象外となった人数、また、分かりましたら全体の何％に値するのか伺います。","respondent":"飛田子育て応援課長","answer":"子育て施策等は、様々な方向からの充実が必要だということは十分理解しております。今後も国や都の動向を注視してまいりたいと考えております。","id":"exchange-064"},{"speaker":"西村委員","kind":"提案","question":"１つご提案をさせていただきたいと思うのですが、所得制限で児童手当の特例給付の対象外となったご家庭への支援について、例えばですが、次世代の社会を担う児童の健全な育成を支援する一環として、独自に手当を支給している区もあります。財源や将来への負担に配慮するなど様々課題があるかとは思いますが、このような独自の施策を品川区でも新設できないでしょうか。伺います。","respondent":"飛田子育て応援課長","answer":"今、他区でも例えば千代田区で行っている事業となりますが、とても先駆的なことかと思います。区にとっては財源確保などの課題もありますので、現段階での導入は非常に困難であり、今後も研究したいと考えております。","id":"exchange-065"},{"speaker":"西村委員","kind":"質問・要望","question":"財源の問題は分かっておりますが、ぜひともご検討いただきたいと思います。区としては各担当課ごとにご判断をしていただいていると思うのですけれども、産み育てやすい品川区をつくるという観点からもご検討をお願いしたいと考えています。本制度導入に当たりまして、これまで所得制限に対して東京都とどのように協議して、区としてどのようなご所見をお持ちか伺います。","respondent":"飛田子育て応援課長","answer":"品川区では今までも入院費の助成を、高校生等に対してもしておりました。そういう意味でも、これからも高校生等の医療費に対しては無償で準備を進めていきたいと考えております。","id":"exchange-066"},{"speaker":"西村委員","kind":"提案","question":"超過する部分の財源については、都との４年目以降の財源等の協議が整うまでの間、各区が自主財源で負担し実施すると整理されたと伺いました。本制度改正は、令和５年からの導入を予定しておりますが、将来的には所得制限超過に対する財政措置を東京都に求めていくのか、その辺りはいかがでしょうか。ご所見を伺います。","respondent":"飛田子育て応援課長","answer":"こちらに関しても、特別区長会では継続的にまた審議を重ねていくということで言われております。そこのところも動向を見ながら、区としては見届けていきたいと考えております。","id":"exchange-067"},{"speaker":"西村委員","kind":"質問","question":"少し先の話になりますので、質問しまして申し訳ございませんでしたが、今後、２０２６年度以降の制度設計については都と自治体がどのように負担するか、新区長の下、他区の動向も踏まえて、引き続きお願いしたいと考えています。１歳・２歳というところで、お子さん１人につき２万円が支給されておりますけれども、この経緯と意義についてお伺いいたします。","respondent":"染谷子ども家庭支援センター長","answer":"子育てサポート商品券の事業の実施におきましては、コロナ禍におきまして物価高騰等の影響を受けている子育て世帯のご家庭に対しまして、実際にお子さんの衣類や食料品など、比較的に若い世代の方たちにかかってくる、生計費にかける割合が高いというところがございましたので。","id":"exchange-068"},{"speaker":"西村委員","kind":"質問","question":"委員会でも様々議論がされてきた議事録を拝見しておりますけれども、対象年齢に関しましてどのようなお考えがあったのかお伺いいたします。","respondent":"染谷子ども家庭支援センター長","answer":"実際に、物価高騰の影響という部分につきましては、１歳・２歳という年齢層のご家庭に限らず、全てのご家庭に関して該当する部分であるかと思いますけれども、まず１点は、家事用品購入支援の１歳・２歳、都の事業について、そこの年齢層を横引きさせていただいたというのが１つ。","id":"exchange-069"},{"speaker":"西村委員","kind":"質問","question":"実際に利用されている方たちの声が届いていたらお聞かせいただけますか。どれぐらいの方が利用されているか、実数まで分からなくてもいいですが、教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"こちらの事業ですが、８月から実施いたしまして、対象の児童につきましては１万３００名程度なのですけれども、現時点において、およそ８,０００名の児童の家庭から申請をいただいているところです。","id":"exchange-070"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、身体障害者手帳を所持している方の、失われた身体機能や損傷のある機能を補うための用具、補装具の購入や修理にかかる費用が支給されておりますけれども、これが特別児童扶養手当と同じように、同様の所得制限がかかっているという、区民の方からのお声もありまして、繰り返しになりますが、この所得制限の考え方というのが大変難しいなと、私自身もいろいろ勉強して思うのですけれども、やはり今。","respondent":"松山障害者支援課長","answer":"区民税が４６万円以上ある方について、かかるものです。それは国の制度となっておりますので、なかなか区の中だけでということが難しいというところになっておりますが、補装具以外の部分に対しましても、手当、いろいろな制度を利用して、経済的な支援を行ってまいります。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、８９ページと１１１ページの区内私立保育園経費に関わって、豊かな保育の実現を求めて質問します。私立保育園には公定価格が算定され、保育園に寄附されていますけれども、その中で保育士など職員の人件費は約８割を想定して国が出しています。この公定価格について、８割を人件費として想定していることについて、区は認識しているのでしょうか。伺います。","respondent":"中元保育支援課長","answer":"その点については、認識しております。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"一方で、人件費率が８割以上の園は、賃金が約３８万円で、約１０万円高い。経験年数は８.９年、約３.５年長い。株式会社立の保育園では９４％が、人件費率が５割台より低い状況になっています。こうした状況を問題だと思わないのか、伺います。人件費率は保育士の処遇に直結し、保育士が保育を行うのですから、保育の質に直接関わる重要なものだと思いますけれども、いかがでしょうか。","respondent":"中元保育支援課長","answer":"各事業者、各園によって、職員の方の年齢構成や職種、雇用形態は様々です。そちらが民間ならではのメリットだと思ってあります。そのようなものが反映された数字ですので、一旦、軽々に人件費率だけをもって職員の配置を判断することはできないという認識です。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"様々な状況があるからということでしたけれども、３割台の園というのは、先ほど紹介しました、公定価格としては８割を人件費と想定しているということで、それは区も認識しているということでしたけれども、その中で３割台の園などもあるわけです。そうしたところがやはり問題だとは思わないのか、伺います。","respondent":"中元保育支援課長","answer":"国の通知でも、きちんとした保育が確保されていれば、国からの公定価格、その中で上手に使って運営してくださいという通知が出てありますので、その中できちんと保育の質を確保されているものと認識しています。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"上手に使ってと言いますけれども、上手に使って人件費が削減されてしまっては困るわけです。保育士を含め、職員の処遇改善、待遇改善をしていくということが、社会的にもこの間、求められ、少しずつ上がってきてはいますけれども、やはりそれがまだまだ足りないと思います。改めて、人件費率が低い園について改善を求めていくことが必要ではないかと思いますが、いかがでしょう。","respondent":"中元保育支援課長","answer":"処遇改善につきましては、様々、補助金等も出して支援しています。実際に本当に低いようなところには、様々な指導・検査、東京都の検査等でもメスが入っているところだと認識しています。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこをしっかり改善していくことが必要だと思います。それは都にもぜひ求めていただきたいと思いますし、区でも指導・検査を行っております。一般質問でもお聞きしましたけれども、人件費については、各園の報告書を確認して、適正に指導しているとの答弁でしたけれども、３割台の園が１１園もあるわけです。区として、これをチェックして、人件費率３割台の園を認めているということなのか、伺います。","respondent":"中元保育支援課長","answer":"人件費だけの問題ではなく、総合的に考えて、こちらから保育園の運営状況については、実態とはまた違うような保護者の方からのご意見も寄せられているところです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"これによりますと、２０２０年度には１２社・３０園が、約７億円も本部経費や新規園の開設費用に流用しています。１企業では最大１億１,０００万円が流用されています。本来、保育園で使われるべきものとして国や区から出されているものであるのに、本部や新規園の開設のために１年でこれだけ流用されているということは問題だと思いますが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"これに沿いまして、各園から私どもに、そのような取崩しの協議書が参りまして、それを東京都に提出し、東京都できちんと判断され審査されているということで認識しています。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"国がある程度認めているというご答弁でしたけれども、これはやはり、ある程度、本部としてもうけがあるわけではありませんから、本部経費に回すことは必要かもしれませんが、１０％超は取り過ぎだと言われているわけです。そういった園が１５園もあるということですから、やはりこれは問題だと思うのですが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"そちらにつきましては、私どもとしては判断する立場にないと思ってあります。東京都できちんとその辺の取崩しのところについて協議書を認めたものですので、それは総合的に考えた上で、園の恒常的な運営に資するものだということで判断されたという認識です。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"都が審査する機関かもしれませんが、これは区にある保育園ですから、ぜひ区としても認識を持っていただきたいと思います。新規園の開設に使用されているのは、ほとんどが他自治体の保育園に使用されているわけで、本来、品川区の保育園に使われるものが別の自治体に流れているということですので、この点は問題だと考えないのか、伺います。","respondent":"中元保育支援課長","answer":"そこのところにつきまして、私どもは知り得るところではございませんので、そちらの会社の判断、また東京都の指導監査の範囲の中で行われていると認識しています。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"知り得る立場にないということですが、区を通して書類がやり取りされているわけですから、区も知り得る立場にはあると思います。実際、現場ではこの配置を増やして保育をしています。やはり、こうした充実した配置が必要だと思いますので、区として、やはり国に引上げを求める意見を言っていただきたいと思いますけれども、いかがでしょうか。在籍数で公定価格が出ていることについて、区の認識を伺います。","respondent":"中元保育支援課長","answer":"１歳児について１人多く配置していただくことで出す補助金等もあります。０歳児園に看護師を配置していただくことで出すということで、区として相当数の加算の運営費も助成していますので、このような支援を続けていきたいという認識です。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"区が加算していただいているのはいいのですけれども、区の１歳児に加算している園の数、今、０歳児の看護師の加算もおっしゃいましたので、その数も伺いたいと思いますが、やはり配置基準を国にぜひ求めていただきたい、求めるべきだと思いますけれども、いかがでしょうか。","respondent":"中元保育支援課長","answer":"すみません。人数のところはちょっと、手持ちですぐに数字が出ませんが、申し訳ありません。そちらは持ち合わせておりません。国への支援というところを求めるというところは今後の課題としたいと思います。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"課題とするということですので、ぜひ配置基準の引き上げを含め、在籍数で出ている問題を含め、ぜひ国に求めていただいて、保育士の待遇を改善して、保育の質を上げていくということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは、１０４ページ・１０５ページの学校施設整備費についてお伺いします。当初予算では３億６,０００万円余となっていましたが、収入済額は７億２,０００万円余となっています。２倍程度になっているのですが、この理由をまずお聞かせいただきたいと思います。","respondent":"森学校施設担当課長","answer":"予算についてのご質問です。収入済額が倍増程度していますけれども、こちらは当初予算で見込んでいた部分よりも多く補助金がいただけることになりましたので、収入増となっています。","id":"exchange-083"},{"speaker":"せお委員","kind":"質問・要望","question":"それ以降は、この４項目を具体的には掘り下げてはいない状況です。そして、品川区の長寿命化計画は、維持管理やコストの縮減の面での長寿命化というのが主な整備内容だと思っているのですけれども、渋谷区のように、長寿命化を、教育効果などを含めた様々な面から広く捉えた計画とするのが、現在の公教育には求められていると私は考えていますが、そちらに関して見解をお聞かせください。","respondent":"森学校施設担当課長","answer":"３点ご質問をいただきました。区立学校の財政等の環境の変化ですけれども、財政収入が増減したりした場合、基本的には、１年で１校ずつ改築していく予定で考えているのですけれども、それができるかどうかというのはあるかもしれません。","id":"exchange-084"},{"speaker":"せお委員","kind":"質問・要望","question":"現在、ハード面で工夫しているところがあれば、改めて教えていただきたいと思いますけれども、あと、ちょっと１点感じたのが、子どもたちの声というのは聞いているのかなと思って、「こんな学校がいい」とか、そういったところの子どもたちのアンケートとか、そういった声は今まで聞いているのか、そちらもお聞かせください。","respondent":"森学校施設担当課長","answer":"今のところどのようなことをされているかということで、多目的ホールであったり、交流できるような場所、ベンチを設置したり、広い空間、多目的な部分を用意して、様々、学年であったり、障害があってもなくても交流ができるように、改築校では検討しております。","id":"exchange-085"},{"speaker":"小芝委員","kind":"質問","question":"私からは、１５４ページ、競馬組合配分金に関連しまして、大井競馬場を含みます、勝島・立会川まちづくりプランについてお聞きします。昨今、コロナ禍にもかかわらず、大井競馬場の純利益は年々増加しています。純利益が増えておりますので、品川区に分配される額も当然増えていると思いますが、最近の推移、品川区に分配されている金額の推移について教えてください。","respondent":"古巻総務課長","answer":"競馬組合からの分配金の推移ですけれども、令和３年度につきましては、決算書に記載のあるとおりですけれども、例えば……、すみません。","id":"exchange-086"},{"speaker":"小芝委員","kind":"質問","question":"後ほど教えてください。その後、昭和６１年に、大井競馬場で初めてのナイター競馬が開催され、品川区の中でも１つのランドマークとも言える施設となってきました。立会川・勝島まちづくりプランの範囲は、西に旧東海道と立会川の商店街を抱え、そして東には６９棟の団地から成る八潮地域を抱えております、それぞれの地域の特色があるわけですが、特にこの勝島地域の特色について教えてください。","respondent":"鈴木都市計画課長","answer":"地域資源としましては、勝島運河、近くに京浜運河と、非常に水辺、水資源が豊かで充実しているというところと、それとあわせて、地域の方々が積極的に取り組んでいる花海道のまちづくり等々が、非常に地域としての魅力の一つです。","id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"具体的に、勝島地区に住む区民の年代、例えば６５歳以上の方の年代だとか、現役世代、それ以下、例えば４０歳ぐらいまでの年代について、分かれば教えてください。割合です。","respondent":"鈴木都市計画課長","answer":"令和４年現在の状況ですが、０歳から９歳が２０.２％という構成です。５人に１人が０歳から９歳以下というところで、２０歳から３９歳までの子育て世代の方々が３１.２％というところ、６０歳以上の方々が約８％という、非常に若い世帯で構成されている地域です。","id":"exchange-088"},{"speaker":"小芝委員","kind":"質問","question":"先ほど話しましたミュージカル劇場が新しい文化の中心となるかどうかはまだ分かりません。立会川・勝島まちづくりプランの中では、第３駐車場の開発計画をどのように捉えておられるのか。まちづくりを進める中で、事業者、これは競馬会社だけではなく、この周辺の事業者とも密に連携を取っていくべきと考えますが、区のお考えを教えてください。","respondent":"鈴木都市計画課長、古巻総務課長","answer":"区としましては、まちづくりビジョンの中で、地域のにぎわいというところも、１つ、非常に強く打ち出しています。先ほどの分配金の件ですけれども、令和に入りましてから、様々な分配金の交付金の内訳がありますけれども、合計で令和元年度で４億７,２００万円余、令和２年度で５億円余、令和３年度で６億円余ということで、年々増えている状況です。","id":"exchange-089"},{"speaker":"小芝委員","kind":"質問・要望","question":"大井競馬場駅から観客の方がこの劇場に流れてくる動線を考える上で、なるべくでしたら勝島エリアに住む区民の方がストレスに感じないようなまちづくりというのも考えていただきたいと思いますが、区の見解について教えてください。今後のまちづくりプランのスケジュールについてもあわせて教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"区としましては、先ほどご紹介いただいたまちづくりビジョン、特に勝島運河上に人道橋の整備、あるいは花海道の修景整備、新浜川公園の再整備というところで、ビジョンに基づく計画をこれから着々と進めていく予定です。","id":"exchange-090"},{"speaker":"小芝委員","kind":"質問・要望","question":"事業者との連携を深めつつ、区民ニーズに沿ったまちづくりを進めていっていただきたいと思います。アンケートも、たしかホームページで見ました、平成２９年のアンケートが載っていたと思いますが、これも改めて、新たな区民ニーズの掘り起こしをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"議会広報費ですけれども、令和２年度は４,７２６万円余、令和３年度が４,６５３万円余からですが、以前にも一度お聞きしたことがあったかと思いますが、年間６回発行し、区内全域に２,７４６万円余の費用をかけて配布していただいていますが、区内で何件配り、それから配布は何日間を目途に期間を縛ってやっているのかどうか、これが分かればお聞きしたいと思います。","respondent":"工藤区議会事務局長","answer":"区議会だよりの配布につきましての件です。区内全戸に配布しておりまして、令和３年度は約２３万５,０００世帯にお配りしているものです。配布の期間は、発行日から３日間かけまして配布しているものです。","id":"exchange-092"},{"speaker":"木村委員","kind":"質問・要望","question":"この２,７４６万円余の中には、発行費と配布費用が含まれていると思いますけれども、それでよろしいのかどうか。そして、含まれているのであれば、その内訳はどのようになっているのかをお聞かせいただきたいと思います。","respondent":"工藤区議会事務局長","answer":"経費の件です。ご指摘のとおりでございまして、まず発行に要する経費が、主に冊子の印刷経費でございまして約１,３４７万円、それから配布に要する委託経費が約１,３９９万円となっています。","id":"exchange-093"},{"speaker":"木村委員","kind":"質問","question":"問題は、区民の皆さんにこれを読んでいただくには、まず手に取って開いていただくことが第一の目標でありますけれども、手に取って読んでいただくことで、制作に携わった方々の苦労というものが報われると私は思いますけれども、その点について、行政から見ていかが思われているでしょうか。お聞かせください。","respondent":"工藤区議会事務局長","answer":"区議会だよりにつきましては、制作につきましては、以前は職員が作成しておりましたが、議員主導で、議会改革の情報発信分科会で検討され、現在の広報会議に引き継がれまして、平成３０年から、手に取っていただくためにサイズをＡ４判に変更することや。","id":"exchange-094"},{"speaker":"木村委員","kind":"質問・要望","question":"品川区の現状の姿を知っていただくためには、区に興味を持っていただくことというのは大変大事だと私は思っています。民間の方々の、また声というもの、意見、アイデア的なものも取り入れてみても面白いとは思いますけれども、もしその点が分かれば、何か回答があればお聞かせいただきたいと思います。区民の心を引きつけるために、どのようなところに一番注意をされているのか、そこもお聞かせください。","respondent":"工藤区議会事務局長","answer":"作成に当たりましては、議会改革の中で、区議会だよりの編集方針というものを策定しておりまして、基本コンセプトを、読みやすい、親しみやすい、分かりやすいの３点といたしまして、文書やレイアウトに注意しながら作成して、お届けしています。","id":"exchange-095"},{"speaker":"木村委員","kind":"質問","question":"購読率というものが分かるシステムというのは、何かあるのでしょうか。実際、購読率が分かっていないのではと私は思っているのですけれども、実際のところ、もし購読率が正しく分かっているのであれば、いかにしてこの調査を行っているのか、調査方法もまたお聞かせください。","respondent":"工藤区議会事務局長","answer":"調査につきましては研究は必要ですが、例えば区の世論調査の中で、それらを調査項目として追加するなども考えられますので、そのようなところも含めての検討になると考えております。","id":"exchange-096"},{"speaker":"木村委員","kind":"質問","question":"購読率をもっと上げるためにも、我々区議会が、個人的にでも構いませんけれども、どのようなことをお手伝いできるとお思いでしょうか。","respondent":"工藤区議会事務局長","answer":"やはり今、議会改革を進めている中で、議会報告会や、様々な地域団体との意見交換会、あるいは小学生の議会傍聴や職場体験の受入れ等も、積極的に今現在、区議会で行っていると感じておりまして、やはりこれらの取組が、区議会への関心につながり。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、決算書の８９ページ、生活困窮者自立支援事業についてと、成果報告書の６１ページから、歳入全般、特に特別区税、地方消費税交付金、財政調整交付金について、それから基金積立金について伺いたいと思います。生活困窮者自立支援事業について伺いたいのですが、緊急小口資金と総合支援資金が９月末で打切りとなりました。","respondent":"櫻木生活福祉課長","answer":"区全体として重層的支援を進めておりますので、生活困窮者相談も、その中の１つの窓口として、連携して対応していきたいと考えております。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"コロナがまだ終息するどころか、今も拡大し続けているという状況で、第８波が起こる可能性も非常に高いと言われています。返済猶予とか、そういうきめ細やかな対応が必要なのではないかと思うのですけれども、そういうことも含めて、区からも国にぜひとも求めていただきたいと私は思うのですけれども、いかがでしょうか。この制度の延長も求めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"免除申請もしくは猶予または拡大というお話、または自立支援給付金の延長について国に求めるですが、こちらは厚生労働省および社会福祉協議会等できちんと適切な判断をするということと考えていますので、それを注視してまいりたいと考えています。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"リーフレットもいろいろなところに置いていただくということにもなりましたけれども、さらに私は広報などでも、暮らし・しごと応援センターの周知を、もう困ったときには１人で悩まずにご相談くださいというのを、ぜひしていただきたいと思うのですけれども、いかがでしょうかということが１点です。そういうこととか、それから、いろいろなところにつなげていく。","respondent":"提坂税務課長、櫻木生活福祉課長","answer":"ただ、何回もお手紙をお送りしたにもかかわらず、あと今、コロナ禍で、なかなか実態調査などができない状態ではありますけれども、何の反応もない方については、やむを得ず最終手段ということで。関係機関にパンフレットを置いていただいたり、定期的に広報しながわにも掲載しています。今後も関係部署と相談して、目に止まりやすいような周知方法を工夫するなど、努めてまいりたいと考えています。","id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。それから基金なのですけれども、最後にちょっと、決算状況一覧表では、９１４億３,７００万円余ということになっているのですけれども、決算書の５２８ページ・５２９ページの数字と違うのですけれども、これは決算状況一覧表の９１４億円余ということが、令和３年度の決算の基金残高ということで捉えていいのか、その点を伺いたいと思います。","respondent":"黒田財政課長","answer":"決算状況一覧表に記載しております令和３年度末現在高の基金残高の合計額は、様々な基金の残高を合計したものですので、令和３年度末の基金の残高は、決算状況一覧表にある９１４億円余というのが、品川区の基金の保有している残高です。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こちらは時間がなくなってしまったのですけれども、この基金残高というのは昨年度よりも９２億７,３００万円余増えているのです。歳入の分野でも、特別区税が９億円増えています。地方消費税交付金が１０億３,０００万円増えています。そして、セーフティーネットをもっと厚くするというところにも、ぜひご検討いただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"松澤委員","kind":"質問","question":"私からは、決算書１００ページの社会資本整備総合交付金より住宅・建築物耐震化支援事業、１億２,１５３万７,０００円と、コンクリートブロック塀等安全化支援事業、６３９万９,０００円について、同じく１０２ページになります防災・安全交付金より密集住宅市街地整備促進事業、５,１３５万２,０００円について、まとめて質問いたします。","respondent":"長尾建築課長","answer":"令和３年度の実績としましては、国費が充当されている主なものとしては、ブロック塀等の除却工事助成が４０件、軽量フェンスの設置は５件というような内容となっております。","id":"exchange-103"},{"speaker":"松澤委員","kind":"確認","question":"例えば１９８１年、ここで初めて新耐震基準というものが設けられました。さらに、２０００年にも基準の強化というのがあるのです。今までの例だと旧耐震基準というのが主になっていますので、１９８１年から２０００年の１９年間、これは新耐震基準ですけれども、要は基準の改正があったということは、耐震化のまた最後の確認といったものもしなければいけないのではないかと私は考えております。","respondent":"長尾建築課長","answer":"こういった都の調査結果や、あと、まだ国や都の助成に対しての動向も注視して、より効果的な耐震化支援というものを行っていきたいと考えております。","id":"exchange-104"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうですね。東京都でもそういったお話が出てきたというのは初めてお聞きしました。だんだん進展しているものだと感じています。耐震診断といったものの抜本的な見直しであったり工事助成の増額といったものを引き続き要望させていただいて、次の質問に移ります。次に、密集住宅市街地整備促進事業についてお聞きいたします。","respondent":"大石木密整備推進課長","answer":"区といたしましては現在、３例目として、東中延一丁目で事業を進めてあります。引き続き、密集住宅市街地の改善に向け、各種事業を展開していくとともに、委員ご紹介の整備事例も参考にしながら研究を進めてまいりたいと思います。","id":"exchange-105"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、質問順で、９３ページ、個人番号カード経費、４３ページ、災害復旧特別会計、１２７ページ、共通商品券普及促進事業について伺っていきます。充当事業で「個人番号カード経費ほか２事業」とあるのですけれども、これについて何なのか教えていただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"こちらなのですが、法改正によりまして、令和３年９月から、国がＪ－ＬＩＳに対して直接補助するような形になりました。そのため、以降、この補助金は出ていない状況になっております。","id":"exchange-106"},{"speaker":"あくつ委員","kind":"質問・要望","question":"法改正で２分の１になりましたということで、確認させていただきました。関連して、区の職員のカード交付について確認させていただきたいと思います。マイナンバーカードの交付については、２０１６年の１月から始まりましたので、もうすぐ７年になろうとしています。あったのであればどのような内容であるのか教えてください。","respondent":"崎村人事課長","answer":"令和２年度、令和３年度についても、申請取得状況の調査とあわせて、取得の推進について通知があったところです。今年度も５月と７月に、同じような内容で取得の推進について通知があったところです。","id":"exchange-107"},{"speaker":"あくつ委員","kind":"確認","question":"それは確認しておきたいと思います。もう一つ、幾つか勧奨の中に、技術的助言ということの中の通知の中には、職員に対して、被扶養者もあわせて令和２年３月までのマイナンバーカード取得について勧奨するようお願いしますと書いてあるのですが、これは職員に関して、いわゆる人事課が勧奨してくださいと書いてあるのですけれども、それは行ったのか、またそれは何回程度行われたのか、確認させてください。","respondent":"崎村人事課長","answer":"取得の推進について、被扶養者を含めてというところのご質問ですけれども、令和元年から、先ほどお話しさせていただきました国からの通知があるたびに、通知に関しての取得状況の調査の中で、被扶養者も含めて報告していただくようにしておりますので。","id":"exchange-108"},{"speaker":"あくつ委員","kind":"質問","question":"今ご答弁の中にあったとおり、人事担当課においては、職員等の申請取得状況の把握をお願いしますとあります。国の通知のとおり、人事担当課において、区職員の申請と取得状況を把握されていらっしゃるのか。されているのであれば、調査の手法、その頻度について教えてください。","respondent":"崎村人事課長","answer":"令和４年度につきましては、５月末現在のほか、６月末現在、８月末現在と、結構期限を細かく設定して調査を実施しておりまして、今回も１０月末現在で調査を実施しています。","id":"exchange-109"},{"speaker":"あくつ委員","kind":"確認","question":"もう一つ、いわゆる、何というのですか、マイナンバーカードのやはり１つの問題点として、できたものを取りに行くというのが非常に手間がかかるというところがあって、本人確認等があるというところで、それを取りに行く場合、例えば公務員の方が所属長に申入れをした場合、それは認められるのか、認められないのか、その辺りについてご見解を教えてください。","respondent":"崎村人事課長","answer":"調査結果の公表というお話ですけれども、こちらは総務省において調査を実施しているのですけれども、これまで各自治体ごとの実績というのを公表しておりません。したがいまして、区として職員についての取得率を公表することは現在考えておりません。","id":"exchange-110"},{"speaker":"あくつ委員","kind":"提案","question":"非常に難しい問題で、このことが明らかになったときに、結構、反対の声というか、強制なのかということで、公務員の団体の方からも、結構、問題の声が上がったということは報道で確認しましたけれども、先日の一般質問で交付への決意を伺った際に、地域振興部長からは、区としても申請サポート等を積極的に実施し、交付の拡大に取り組んでいくと、業務としてのこういうご答弁をいただきました。","respondent":"平原防災課長","answer":"一方で、ご指摘のとおり、訓練の高齢化、あるいは決まったメンバーのみの参加といったところの課題も見受けられるところでございまして、そういったところに対応して、また別立てでということで、しながわ防災体験館の充実。","id":"exchange-111"},{"speaker":"あくつ委員","kind":"提案","question":"私たちの命は私たちで守る。大地震は必ずやってきます。今、地震が起きたら、どう行動しようかと。こういう機会の中で、もう少し、一歩踏み込んだ、自助・共助の意識の高揚・醸成というのは、そういうことで求めていきたいと考えているのですけれども、防災区民憲章についてどのようにお考えか、前に長期的な検討をしていただくというご答弁をいただいていたので、その辺り、もう一度ご答弁をお願いします。","respondent":"平原防災課長","answer":"防災区民憲章についてのお尋ねですけれども、令和元年の第３回定例会での、長期的に検討というところの答弁と重なるところもありますけれども、区では、まずは平成２６年に制定させていただきました品川区災害対策基本条例にうたいます、自助・共助の重要性につきまして。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"１６２ページ、特別区債と、３８６ページ、公債費についてお尋ねします。特別区債のほうなのですが、令和３年度は学校施設整備費で１５億４,４００万円の教育区債を発行いたしました。逆に言うと、１１億８,６００万円は起債しなかったということなのですが、なぜ予算現額の起債が行われなかったのでしょうか。","respondent":"黒田財政課長","answer":"令和３年度の特別区債の中で、学校用地費として取得しておりますが、予算で計上した金額よりも、実際に購入した額が、国の契約した額に落差がありますと、その部分は金額として差がありますので、そういった関係で金額に差があるものです。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、１１億円も予算があったということなのでしょうか。学校用地取得費１校６億円云々とありますけれども、そこのところをお願いします。","respondent":"森学校施設担当課長","answer":"今のご質問ですけれども、学校用地取得につきましては、落差の関係で、７.４億円ぐらい減です。続いて学校改築のほうで、国庫補助金が想定より多かったというところで、４.５億円ほど減なので、約１１億円ということになってあります。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"用地取得費のほうが落差で７.４億円、先ほどもやり取りがありましたが、教育費補助金の中の、恐らく国庫補助金の約４億円が入ってきたので、その分起債しなくてよかったという理解で、分かりました。工事などが進まないので、その分の費用というか、かからなくなってしまったというようなことではないという理解でよろしいでしょうか。","respondent":"森学校施設担当課長","answer":"そのとおりです。工事については、そういうことはしておりません。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"工事は円滑に進んでいるということが確認できました。それから、平成１２年から令和２年度の起債利子が１億３,７２０万円強の決算額です。この起債と償還金について、いろいろお話を伺ったり、これまで来ているのですが、なかなか整理できていないので、区として起債するときに、予算が議決されました。その後、どのような手続が行われて、起債が進められていくのか、教えていただきたいと思います。","respondent":"黒田財政課長","answer":"予算編成の中で、先ほど申し上げたとおり、用地購入費でありますとか施設整備費について、そのうちの幾らが起債対象になるかというところも協議しながら、予算額を決めてまいりまして、予算が編成されるです。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、実際に手続して借りることになるというところなのですが、何といいますか、それぞれの事業によって資金の割当てはいろいろあると思うのですが、具体的な、いわゆる引受け先というのですか、それから借入れの金額等は、どこのセクションで、どこに借りるというのですか、どこに引き受けてもらうかというのを、どのようにして決めて、それで具体的に申請というか起債していくことになるのでしょうか。","respondent":"黒田財政課長","answer":"その中で様々、銀行から借りるものもあれば、政府債というのですか、財政投融資から借りるというようなものもありますので、そういったものにつきましても、起債メニューの中で東京都と協議して決まっていくというような状況です。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話があった政府系だと、例えば財政融資債でお借りするとか、あと、今、民間銀行から等もありますが、そういうものを東京都などと協議しながら、借入れ先や借入金額を決めていくということが分かりました。そうすると、令和３年度の学校施設整備費の起債ですけれども、金額が大きいので１本ではないのかもしれませんけれども、どのような引受け先になるのでしょうか。もし分かればお願いします。","respondent":"黒田財政課長","answer":"令和３年度の起債につきましては、借入れ先は、国の財政融資資金から借入れをしているものです。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"細かい話で、すみません。ありがとうございました。先日の報道では、ワクチン接種費用を全部国費で負担していることについて、特例的な措置は廃止すべきだという議論があったという報道もありましたが、国庫支出金について、例えばその年度で国庫支出金を受けて、しかし余ったという場合は、どのような形で返還するのでしょうか。それは、決算書の中でどのように記載されるのでしょうか。","respondent":"黒田財政課長","answer":"決算書の中では、国庫支出金の衛生費負担金の、９２ページにありますけれども、新型コロナウイルスワクチン接種負担金を見ていただきますと、９３ページ、右側のところに、収入超過額という形で１４億８,４００万円余と記載がありますので。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和３年度の決算から令和４年度につながって、先日の補正予算のところに出てきまして、その説明が非常に複雑だったので、今、お話を伺いました。ここも、予算というか、決算の方法など、起債を含めたいろいろな国庫支出金などについてはお尋ねしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"令和３年度主要施策の成果報告書の財政全般について、１２９ページ、（仮称）旗の台六丁目公園、１３１ページ、密集住宅市街地整備促進事業について、お伺いします。成果について、区の歳入が特別区民税の対前年度プラス約６.６億円、プラス６３億円の増加となったと。一般財源では８.５％の増となって、３年ぶりに前年度プラスとなっているところです。よろしくお願いします。","respondent":"黒田財政課長","answer":"は決算の全般ですけれども、今、委員からご指摘がありましたとおり、執行率については、やや低い部分もございましたが、令和３年度は補正予算を第９号まで編成いたしまして、いわゆる新型コロナウイルスの対応でありますとか、それに伴う経済対策というところで。","id":"exchange-121"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そんな中、来年度、本年度期末には中小零細企業の方たちは本当に今大変な思いをしております。あえて来年度に向けて、この支援対策をいま一度、しっかりとやっていただいているのは分かるのですけれども、やっていただきたいという思いで私は発言させてもらっているのですけれども、それについて、来年度に向けての意気込みというか、教えていただきたいと思います。ぜひよろしくお願いします。","respondent":"黒田財政課長","answer":"令和４年度、今年度に入りまして、補正予算で物価高騰対策ということで、いわゆる中小企業の資金の融資あっせんの物価高騰対策版というのも実施したりという中で、時期を捉えて施策を打っておりますので、今お話がありましたように、これから当初予算の編成をしていく中で。","id":"exchange-122"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。続きまして、１２９ページ、（仮称）旗の台六丁目公園についてお伺いします。これはまず確認なのですけれども、都市計画交付金で、当初予算ですと１億４,６８０万円、決算では１億７,２００万円余となっているのですけれども、もし分かればその詳細を教えていただきたいと思います。","respondent":"黒田財政課長","answer":"（仮称）旗の台六丁目公園に対する都市計画交付金ですが、都市計画交付金につきましては、東京都が固定資産税と都市計画税を合わせて徴収し、特別区がある区域内でも徴収しておりまして、事業に応じて都が交付するというような仕組みになっておりますが。","id":"exchange-123"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"理解できました。どうもありがとうあります。この公園の事業なのですけれども、都市計画公園に基づいて防災広場の整備推進をやって、今現在も公園が整備されております。今の進捗状況をお知らせいただきたいと思います。","respondent":"高梨公園課長","answer":"工事は１２月上旬竣工予定で、現在順調に進んでおりまして、今年度内、１２月中旬頃の開園を目指して、現在も実施しています。","id":"exchange-124"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私も先日、整備の現場を見てきました。そのときに、複数の若い家族の方が「公園ができるのだ」と、すごく楽しみにしている姿を私は見ました。今、課長がおっしゃられたように、１２月上旬ということで、告知・啓発、すごく静かな場所なので、どの程度、周知をするのかというのは私は分からないのだけど、今、（仮称）旗の台六丁目公園となっているじゃないですか。もう公園の呼称というのはついたのですか。","respondent":"高梨公園課長","answer":"失礼いたしました。仮称で旗の台六丁目公園ということで事業を進めてまいりましたが、先般、町会を中心とした地元の方の意見を取り入れまして、この公園は、旗の台六丁目のハタロク公園として、名称は区で決定したものです。","id":"exchange-125"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ハタロク公園ということで、私も周知しておきます。ぜひ、楽しみにしていますので、ありがとうございました。続きまして１３１ページ、密集住宅市街地整備促進事業に関連しまして、二葉三丁目２４番街区事業用地は、防災広場が今、検討されているかと思うのですけれども、それについて詳細を教えていただきたいと思います。","respondent":"大石木密整備推進課長","answer":"二葉三丁目に整備を予定しております防災広場については、現在、地域の皆様とワークショップ形式で検討を行っているところです。今年度中に基本計画を取りまとめまして、来年度、基本計画を基に、令和５年度に設計を行い、令和６年度に工事の予定をしております。","id":"exchange-126"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私もこの防災広場検討会第１回目の資料を見ながら、今、質疑させていただいているのですけれども、これはいろいろ事例があります。その中で、お子さんの健康遊具とか、子どもの遊具が記載されているのですけれども、これは検討会の中で子どもの遊具についてというのがあったのかということと、今後検討していくのかということだけお聞きしたいと思います。","respondent":"大石木密整備推進課長","answer":"実際に１回目の検討会の中では、検討会の委員の皆様から、やはり少し面積が狭いということがありまして、あまり要望がないのではないかという意見だったり、実際に置かなくて、走り回っている子どもを見たほうがいいという意見がございまして。","id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これをぜひ防災広場の中に、健康器具もそうですけれども、遊具を備えていただきたい。これは要望です。ぜひよろしくお願いします。それと、防災広場について、また所管がまたがると思うのですけれども、公園課との連携という部分で、どういうふうに連携されているのかというのも、いま一度私も理解しておきたいので、お知らせをお願いしたいと思います。","respondent":"高梨公園課長","answer":"計画の段階でも、ワークショップ等、木密整備推進課で行う際には、公園課から整備部隊・維持部隊の人間を派遣して、一緒になって検討していくという形で連携を取って進めているところです。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"二葉も木密地域は本当に密集しているところなので、防災広場と、もう本当に理解しているのですけれども、公園の整備の中に、ぜひ遊具を取り入れていただきたいというのを、改めて要望させていただきたいと思います。最後に何かあったら、よろしくお願いします。","respondent":"大石木密整備推進課長","answer":"今回につきましては、今いただいた意見を、今月予定しております２回目の検討会で意見としてフィードバックして、検討会の皆様で議論をしていただければと考えているところです。","id":"exchange-129"},{"speaker":"松本委員","kind":"質問","question":"私は、５２ページ、特別区民税、１６２ページ、特別区債、７８ページ、区民住宅使用料について伺います。中でも、ずっと議論もありましたけれども、令和３年度特別区民税というのは、令和２年の所得に基づいて決定されると。人口が、４,０００人ぐらいですか、増えたということがあったかと思いますし、あとは収納率はもう本当に、税務課の皆様に頑張っていただいたというところかと思います。お願いします。","respondent":"提坂税務課長","answer":"それで、その年齢層の方がやはり高額所得の方が多いかと推測できるところなのですけれども、実際に課税標準額７００万円を超える方が、人数的には納税義務者全体の約１割にすぎないのですけれども、税額としては全体の約４割を占めているという現実があります。","id":"exchange-130"},{"speaker":"松本委員","kind":"確認","question":"１人当たりの収入額が上昇してきているというふうな話になってきていると思います。先ほど年齢層のお話もありましたけれども、もう一個、一応確認しておきたいのですけれども、税制改正で、何がしか税収面で影響があったのか、お考えを伺います。","respondent":"提坂税務課長","answer":"ここ数年、度重なる税制改正が行われているところですけれども、主なところでは、税収増につながったと思われる部分ですけれども、合計所得２,４００万円以上の基礎控除額が一律３３万円だった部分が低減されたと。","id":"exchange-131"},{"speaker":"松本委員","kind":"質問・要望","question":"間違いだったら指摘していただきたいのですけれども、今の税制改正は、たしか令和３年度の税収からの反映だったかと思うのですけれども、それで間違いなかったでしょうか。","respondent":"提坂税務課長","answer":"間違いないかと思います。","id":"exchange-132"},{"speaker":"松本委員","kind":"質問","question":"令和２年度と令和３年度を比較すると、そこは納得感があるのですけれども、先ほど申し上げたように、平成３０年度からかなり上がってきているという状況です。そうすると、そこに入る人たちというのは、基本的には品川区も今、物価、地価が上がっていますから、そういう方たちのことを考えると、比較的、高額な所得の方たちが入ってきたのかなと思うのですけれども、そこの部分はいかがでしょうか。","respondent":"提坂税務課長","answer":"７００万円超の所得の方が増えているということで、先ほどの税制改正で、住宅ローンの借入金控除の特例延長というのもありますので、その辺の制度をうまく活用してタワーマンションに入居する方が増えていて、それが結果的に税収増にもつながっていると考えています。","id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"そのように考えたときに、これは都市計画あるいは都市開発との関係で、そういった視点が区としてあるのかというところも１つ重要かと思います。こういった考え方、より多くの収入を得ている方が流入してくることによって、それが区の全体のプラスになっていくというお考えを持って、計画あるいは開発を行われているのか伺います。","respondent":"鈴木都市計画課長","answer":"ただ、区が基本的な再開発やまちづくりを進める上で、今、マスタープランの検討もしておりますが、そうした視点がしっかりうたわれているかというと、今現在、計画上はうたわれていないというところがありますが、側面的には当然、そうした視点もあろうかと思います。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"特別区債についてなのですけれども、エコルとごしがグッドデザイン賞を獲得するなど、品川区は環境のまちという認識も少しずつ広がってほしいというところがあります。これは東京都との協議は必要かと思いますが、品川区としても、これは環境のまちというところを訴えていく中でも、こうしたＳＤＧｓ債、グリーンボンド、サステナビリティボンドを発行するというお考えはあるのか伺います。","respondent":"黒田財政課長","answer":"いわゆるＥＳＧ債は、先ほど申し上げた地方債の仕組みでいいますと、いわゆる民間資金を活用した市場公募債ということになろうかと思いますが、引受け先が民間の金融機関になりますと、どうしても利率が高いというところもありますので、発行目的と資金調達の側面から考えて。","id":"exchange-135"},{"speaker":"松本委員","kind":"意見","question":"時間がない中でありがとうございました。品川区としても、環境に取り組んでいくのだという姿勢が大事だと思いますので、ぜひ引き続きご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"私は、１００ページ、防災・安全交付金についてお聞きしたいと思います。その中で、震災後、家屋が全壊したり火災で焼失した場合、災害弔慰金をはじめ、被災者生活再建支援金、災害援護資金など、被災者に対するお見舞いや支援制度がありますが、概算でいいのですが、どのくらいの支援金が出るのですか。教えてください。そして、これらの支援金で生活再建は可能と思われますか。見解をお聞かせください。","respondent":"平原防災課長","answer":"例えば学用品をなくした場合は学用品の現品支給、あるいはお亡くなりになった場合には最大５００万円までの弔慰金といったものもありますので、一概にそれで何かが足りるといったところについては言いづらいところですが。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"一番マックスで、やはり５００万円から、３００万円、１００万円、それぞれあります。でも、これらの額では、どうなのでしょう。そこに住まわれている方が本当に生活再建ができるのでしょうか。その辺についてご見解をもう一回お聞きします。２,０００万円も３,０００万円も出る話ではなくて、やはり私は金額的には、かなり絞られる、少ない金額かと思っているのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"それ以外のところで、例えば仮設住宅でありますとか様々な支援策と取り合わせまして、震災後の生活再建を進めていくものと考えております。","id":"exchange-138"},{"speaker":"須貝委員","kind":"意見","question":"４８時間後に延焼して自分の自宅が燃えました。だけど、それだけでは、やはり品川区を見て仮に５０％としたら、木造家屋が多い、密集市街地が多い。そうしたら、非常に私は心配しているのですが、やはりもっと積極的に、住宅再建、それから家財道具の購入などを考えて、民間の地震保険に加入するように普及啓発をしっかり前向きにやるべきだと私は思うのですが、ご見解をお聞かせください。","respondent":"平原防災課長","answer":"そういったところもございまして、地震保険は公的な位置づけがあるということで、私どもも現在ではまだ、しながわ防災ハンドブックに紹介させていただいているというような形でやらせていただいておりますけれども、様々な場を捉えまして、今後。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問・要望","question":"地震でないと使えませんとは書いてありますけど、今言ったとおり、４８時間前にどこかが燃えて、自分のところは４８時間後に延焼した。全焼したのです。私はその辺を考えていただきたいと思います。年額５,０００円で、再検討の給付金は最大で６００万円です。そして、兵庫県の教訓と経験からつくり上げた、このような共済制度を、私はぜひ品川区でも創設するべきだと思いますが、ご見解をお聞かせください。","respondent":"平原防災課長","answer":"そういった中で、復旧の段階から復興に至るところ、いよいよ当面の生活再建から元に戻っていく段階としての生活再建、そういったところの渡し方、そういったときに必要な金額、どういったものがあるかというところも、先ほどの地震保険なども相まりまして。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ、これだけの木造密集地域もあります。一人でも多くの区民を助けるというのは、やはり自治体の使命だと私は思います。仮に品川区で共済制度をつくれなくても、やはり民間の、少なくとも地震保険に入って、皆さん、再建してくださいということを積極的に進めていただきたいと私は思います。区では、一人ひとりを助ける、再建させるということはできないですよね。ぜひ共済制度も含めてご検討ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"大倉委員","kind":"質問・要望","question":"５２ページ、特別区民税、６４ページ、集会所使用料から荏原第一地域センター、時間があれば１３７ページの衆議院議員選挙執行費から選挙について伺えればと思います。その中で、こうした火曜延長窓口や日曜開庁を行うに至った経緯を改めて教えていただきたいのと、令和３年７月２６日からこちらが開かれて、今やられているところであります。","respondent":"提坂税務課長、川島地域活動課長","answer":"そういう方については、真摯に相談の窓口を開いて、状況をお聞きして、分割納付とか徴収猶予とかと、最終的に生活困窮ということであれば執行停止とか、そういうこともありますので。多分、庁舎のほうとも、接続というのですか、行き来の部分などというのも少しあるのかなというところもありましたので、荏原地区に、今までにないような新しいサービスが何かできないかということで、様々検討しまして、火曜延長窓口。","id":"exchange-142"},{"speaker":"大倉委員","kind":"質問・要望","question":"これについては、いろいろな課題があって、その課題解決をしてきているのだろうと思っておりまして、また今後、こういった新しいところにというところで今回入っているということも分かったのですが、今後こうしたさらなる区民の利便性の向上というところでは、ほかの地域センターでも考えられるようなことも、広さとか、今でいう人員とかというところも課題ではあるのかと思うのですが。","respondent":"川島地域活動課長、遠藤商業・ものづくり課長","answer":"その都度、どこの施設がどうなのかというのもなかなか予測がつきませんが、新しくするときには、どのようなものができるかというのは、しっかりサービス向上に資するものを検討していきたいと考えています。今までの、コロナの対策ということで大変だった部分が、現状ではやはり原材料高、それから価格低下がなかなかしづらいという部分と、あと以前の融資があった部分で、その支払いが始まっているというようなところに加えまして。","id":"exchange-143"},{"speaker":"大倉委員","kind":"質問・要望","question":"荏原第一地域センターは、ありがとうあります。不定期でということで、なるべく土曜日も区民の方が利用できるように工夫してやっていただいているのだと思いますので、引き続きよろしくお願いいたします。事業承継がかなりネガティブになっているところだと思いますので、今後、ウィズコロナを見据えた施策・対策というのを考えていただきたいのですが、ご検討をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分で、借換融資とか新たな融資制度などを設けて、中小企業の支援に努めているところです。今後、国でも様々な支援策が出ているところですので、その辺を周知しまして、引き続き区としてどのような支援ができるか考えていきたいと考えています。","id":"exchange-144"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここに関わって、区立伊藤幼稚園廃園について、存続を求めて質問したいと思います。これまでも依命通達について、マイナスシーリングという予算削減が、区民生活に必要な福祉や教育などの事業削減につながることはあってはならないと、繰り返し求めてきました。そこで、区立幼稚園のあり方について、企画部としてはどのような意見を述べてきたのか、そして出席した課長は誰か、ご説明いただきたいと思います。","respondent":"佐藤計画担当課長","answer":"会議の場での発言ということですけれども、ホームページ等にも出ておりますけれども、幼稚園、閉園になる対象のところの実現性ということで、今、通っていらっしゃるお子さんの受皿の部分ですとか、今後の区立幼稚園のあり方ですとか。","id":"exchange-145"},{"speaker":"中塚委員","kind":"質問・要望","question":"計画担当課長が閉園を求めたと、客観的な意見を述べたということでよいのか、改めて伺いたいと思います。企画部が教育委員会に直接意見を言うときは、決まって適正配置・適正規模という名の統廃合です。今回もまた企画部は、区立幼稚園の統廃合を、３者の会議の場で計画担当課長が主張してきたということでよいのか伺いたいと思います。","respondent":"佐藤計画担当課長","answer":"企画部の管理職ということで出席しておりましたので、今回のこの件に限らず、限られた財源に対して適正に事業を行うという視点からご意見を述べさせていただいたです。","id":"exchange-146"},{"speaker":"中塚委員","kind":"質問・要望","question":"限られた財源の中で適正にという視点から意見を述べたということは、閉園を求めたということでよいのですか。","respondent":"佐藤計画担当課長","answer":"区立幼稚園今後のあり方検討委員会という会議で示されました資料について、そういった点について今後どうしていくかという会議でございましたので、所管課だけでやるよりは、企画部も含めた言わば客観的な目を通してよりよい事業について考えていくという場でございましたので。","id":"exchange-147"},{"speaker":"中塚委員","kind":"質問・要望","question":"企画部として閉園を保育課や教育委員会に求めていないというのであれば、企画部は何を求めたのか伺いたいと思います。きちんと説明をいただきたいと思います。そして、この会議の場になぜ企画部が参加したのか、企画部の出席を求めた人は誰なのか、自分で参加したのか、それとも誰かに指示されて出席したのか、そこをご説明いただきたいと思います。","respondent":"佐藤計画担当課長、立木保育課長","answer":"答弁が繰り返しになってしまうかもしれませんけれども、私としては客観的な立場から、今後どうしていくかということに対して、企画部の管理職として意見を申し上げたところです。これは理由としましては、先ほど計画担当課長からお話がありましたとおり、区の全体の調整という形で企画部がありますので、そうしたところの意見をしっかり取り入れて検討していくためということで、参加していただいた次第です。","id":"exchange-148"},{"speaker":"中塚委員","kind":"質問・要望","question":"課長が言う、企画部としての客観的な立場として意見を述べていると言っている意味が、結局は、区の行政改革の路線で閉園を求めていくということにつながってくると私は思います。子どもの施設への投資は未来への投資です。社会が回っていきません。そして、子どもの施設にまで財政効率を求めるのはやめるべきだと、こうした行政改革路線は転換すべきだと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"今回の伊藤幼稚園の件につきましては、閉園ということが１つ出ておりますが、それ以前に、区の今後の区立幼稚園のあり方ということで検討を進めてまいりました。これから、ゼロ歳から就学前までの一貫した保育教育ということで、幼保一体施設のほうを充実させていく。","id":"exchange-149"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の答弁は、この間の経過を述べているだけなのです。私が伺っているのは、区民税や財調交付金も増えている。さらには新たに基金まで積み増すほどの余裕がある。これがこの決算で明らかになりました。この下で、なぜ子どもの施設にまで財政効率を求めるのかと伺いました。入るお金も増えている。なぜ子どもの施設にまで財政効率を求めるのか。この姿勢は改めるべきだと思いますけれども、いかがでしょうか。","respondent":"佐藤計画担当課長","answer":"冒頭申し上げたとおり、区のこの事業に限らずですけれども、限られた財源に対して効率的な事業を行うということで進めておりますので、本件会議に出席した際も、今通っているお子さんについての経費についてはお答えいただいておりますし。","id":"exchange-150"},{"speaker":"中塚委員","kind":"質問・要望","question":"限られた財源という言い方で、子どもにまで例外を認めない。こうした効率優先の運営は誤りだと思います。子どもへの投資は未来への投資です。目先の利益ばかりを追うのではなく、次の世代をつくっていく未来への投資なのです。効率化の名前で、伊藤幼稚園を含めて、子どもの施設にまで廃園を求めていく。抜本的な転換を強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"塚本委員","kind":"質問","question":"お聞きしたいのは、先ほどから出ている、１０％の区民の方、納税義務者が７００万円以上の年収をお持ちで、税額全体の４割を占めているという状況なわけですけれども、こういった納税者の分布というのですか、偏りというのか、こういった状況というのが、いわゆるコロナ禍を通じて貧富の格差みたいなものの拡大ということにつながっているようなことというのは。","respondent":"提坂税務課長","answer":"所得の分布の偏りというのですか、それについては、コロナ禍で始まったということではなくて、コロナ禍前からこの傾向は見えてきたのかなと考えます。","id":"exchange-152"},{"speaker":"塚本委員","kind":"質問・要望","question":"水とか教育とか雇用とか、こういったことを社会としてきっちり支えていくといった考え方から、それを発展させてベーシックサービスという考え方が今出てきているということなのですけれども、このベーシックサービスについての区の認識、また評価というのをお聞きしたいのですが、それとあわせてベーシックサービスというものが、いわゆる品川区の今やっている事業の中でふさわしいというのですか。","respondent":"佐藤企画調整課長","answer":"今後もそういった社会状況を見ながら、区として質素倹約で財政基盤はしっかりしておりますので、そういったものを使いながら進めていきたいと考えております。","id":"exchange-153"},{"speaker":"塚本委員","kind":"意見","question":"こういった点も含めて、今後の品川区の１つの社会保障、品川区ができる社会保障という部分での施策として、このベーシックサービスの考え方について、改めてご答弁をお願いしたいと思います。","respondent":"佐藤企画調整課長","answer":"委員から様々なご提案をいただきました。区では今現在、重層的支援体制整備というところで、福祉部が中心となりまして、相談体制の充実について検討しているところです。","id":"exchange-154"},{"speaker":"塚本委員","kind":"意見","question":"これは今後もいろいろと先の長い話であるかと思いますので、よろしくお願いしたいと思います。最後に、あまりお時間がないので１つだけ、使用料及び手数料で、今、キャッシュレス決済で使用しているアプリというのが幾つかあるかと思います。決済キャリアですね。今後どういう考え方で、こういった決済アプリを広げていくというふうに考えているのか、一言お願いいたします。","respondent":"宮澤情報推進課長","answer":"現在、窓口で手数料や使用料のキャッシュレス決済というのを行っております。キャッシュレスのブランドにつきましては、ＱＲコードであったりクレジットであったり電子マネーということで、様々なブランドを用意して区民の利便性を向上させているです。","id":"exchange-155"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、歳入全般についてご質問します。新型コロナウイルスが区内に蔓延してから間もなく３年がたとうとしています。品川区の見通しでは、令和２６年でしょうか、そこまでは人口が増え続けて、そこをピークに人口減少としていますけれども、午後の質疑の中でもありましたが、現在、コロナ禍で転出が増えているというご答弁もありました。区内企業の転入出についてもあわせてお知らせください。","respondent":"佐藤計画担当課長","answer":"夜間人口を１００とした割合でいきますと、１３７.８という数字になっております。","id":"exchange-156"},{"speaker":"湯澤委員","kind":"質問・要望","question":"区内全体についての人口をお知らせいただきたかったのですけれども、そちらはいかがでしょうか。いいです。分かりました。やはり、人口の減少や、事業所についても減少していくことは、区政運営について大きな影響を与えると考えています。現在、区が魅力発信として行っている取組と、取組に対して何か感触があればお知らせいただきたいと思います。","respondent":"篠田文化観光課長","answer":"今、国内外に対してですので、観光的な視点で申し上げますと、私どもも、インバウンドが落ち込んでいる中でも毎年、インターネット等を通じまして、基本的にはアジアを中心としてですけれども、様々な形で情報発信をして。","id":"exchange-157"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それで、品川区に訪れたい、そして住みたいと思ってくれる人が増えればいいなと考えています。税外収入の確保として、クラウドファンディングやネーミングライツ等の活用について検討しているという区の方針が、毎年、依命通達でうたわれていると思うのですけれども、現在はどのような検討をされているのか、これまでの実績とともに教えていただければと思います。","respondent":"黒田財政課長","answer":"いわゆる税外収入の確保というところで、毎度、依命通達でも、税外収入の確保についてということは依命通達の中であるわけですが、クラウドファンティングにつきましては、子どもの食の支援というところでクラウドファンディングも行っておりますし、令和３年度につきましては。","id":"exchange-158"},{"speaker":"湯澤委員","kind":"提案","question":"ふるさと納税につきましては、先ほど芹澤委員から流出の軽減の提案をさせていただきましたし、またクラウドファンディング、ネーミングライツのさらなる活用を検討していただきたいと要望いたします。ネーミングライツに関しては、区のホームページなどでも募ってはいかがかと思いますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"ネーミングライツは、様々活用している自治体があることは承知しておりますけれども、継続的に税外収入として確保できる安定的な税収となるという観点も１つでございまして、また一方で、小さなところでも、こつこつと申しましょうか、確保していくというところも重要ですので。","id":"exchange-159"},{"speaker":"湯澤委員","kind":"質問・要望","question":"こつこつというお話がありましたけれども、我が会派からも、これまでも要望させていただいておりましたが、ぜひ今だからこそ、こつこつと、そういったところも取り組んでいただきたいと考えています。特に区民プールなどはどうなのでしょうか。できればこれは上げてほしくないと思うのですけれども、区民使用料などは上げてほしくないと考えていますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"いわゆる使用料につきましては、要はそれにかかる経費について一定程度ご負担いただくというところで算出していますが、今、一時的な物価高騰に対して、すぐに使用料を上げるというところで検討を進めているものではございません。","id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816325?Template=document&Id=1516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":118432,"voices":371}},{"id":"r04-20221109-4","meetingId":"r04-c-settlement","date":"2022年11月9日","dateIso":"2022-11-09","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件抜き出しています。","topics":[{"id":"topic-01","title":"◯渡部委員長 ただいまより、決算特別委員会を開きます。 それでは、令和３年度品川区一般会計歳入歳出決算","agenda":"◯渡部委員長 ただいまより、決算特別委員会を開きます。 それでは、令和３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"今日も１日よろしくお願いいたします。私からは、決算書１６９ページ、全庁共通プロジェクト推進経費、１７０ページの施設整備費より、区有施設に関することについて質問いたします。今年の５月にオープンしました環境学習施設「エコルとごし」、エコにつながる活動が広く伝わり、品川区の中心に位置する戸越の地から交流の輪が広がってほしいとの思いを込めたすばらしい施設となっております。","respondent":"小林施設整備課長","answer":"感想等ですが、この施設のデザイン、様々ご検討いただくのは設計者や展示者ですが、区としましても、この施設の本格的な検討を始めました平成３０年の段階ですが、施設のコンセプトを取りまとめてきたところです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"そうですね、戸越公園との融合というのですか、私も戸越公園で遊んで育った人間として、初めに施設ができるといったとき、見学会などでもいろいろありましたけれども、実際に建ってみると、やっぱり地域からも、非常に戸越の森とマッチしている本当にすばらしい施設だということは、本当に大変多くの声をいただいております。このグッドデザイン賞のホームページを見ました。","respondent":"小林施設整備課長","answer":"現在、例えばですが、計画を進めております北品川高齢者多世代交流支援施設ですが、設計の初期の段階から、地域の特性に合わせまして、外観におきましては、例えば、旧東海道の街並みを意識した設計を検討するなど。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"先ほどＺＥＢのお話をさせていただきましたが、このエコルとごし、都内公共施設でＮｅａｒｌｙ ＺＥＢを取得した施設です。第３回定例会におきましても、会派の鈴木真澄議員がお伺いしました。その後、ほかの施設のＺＥＢの取得状況および今後の展望について、もう少し詳しくお聞かせください。","respondent":"小林施設整備課長","answer":"やはりＺＥＢやＺＥＨがエネルギーを無理なく無駄なく使用することにつながります。こういった観点から、今後の脱炭素社会の実現に向けて大きく貢献する１つの取組かというふうに認識していますので、今後も機会を捉えて認証取得を進めてまいりたいというふうに考えてあります。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"すみません、１つ聞き忘れてしまいました。エコルとごしはエネルギー効率がいいというお話を聞きましたので、エコルとごしのエネルギー使用に対する実績を教えてください。","respondent":"小林施設整備課長","answer":"これにつきましては、毎月、我々設計を行いました所管課であったり、あるいは施設を運営している所管課、それから運営者、設計者等が定期的にエネルギーの使用に関わる会議を開催しまして、エネルギーの使用量を把握・共有した上で。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"エコルとごしのような様々な工夫をもちまして、デザイン、設計を今後の魅力ある区有施設につなげていただきたいと願いまして、次の質問に移ります。次に、全庁共通プロジェクト推進経費について質問いたします。このプロジェクトは、管轄する部署が決まっていない区有地の方向性を計画するものと推測しますが、品川区では、現在、区民からの贈与というものも含めて幾つあるのか教えてください。","respondent":"佐藤企画調整課長","answer":"今後、方向性を検討する区有地等に関するご質問です。旧荏原第四中学校跡地など、また、寄贈物件ですと、平塚二丁目寄贈物件や、豊町一丁目にあります福祉施設の整備のご要望を受けている寄贈物件などと認識しております。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"今お話がありました荏原第五地区、私が住み育ちました荏原第五地区は、豊町一丁目の贈与地、また、旧荏原四中の跡地活用が長く課題となっております。これの現在の活用状況と期限について教えてください。","respondent":"佐藤企画調整課長","answer":"旧荏原第四中学校跡地は、暫定保育園などとして令和５年度まで活用します。屋内運動場やグラウンドを地域利用として貸し出しておりまして、野球やサッカー、バレーボール等でご利用いただいております。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"豊町一丁目に関しては、区で保有した日もまだ浅く、前も質問させていただきましたけれども、計画というのですか、なかなかこれからのことだと考えています。しつこいお話になってしまいますけれども、その贈与していただいた方は、福祉施設として利用してほしいという思いがあって贈与されたというのは、私も、実際にその方とお話をして間に入っていたので、強く覚えています。教えてください。","respondent":"佐藤企画調整課長","answer":"現在の公園管理機能による利用は、あくまで暫定ということでございまして、今後、近隣公共施設や公園の再整備などの機会を捉えまして、ご寄附の趣旨に沿う施設の整備に向け検討を進めてまいります。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ地域の方を集めた意見交換会を、どうしても初めは町会長が主になると思いますけれども、そういった部分に偏らずと言ったらちょっと失礼かもしれませんが、やっぱり幅広く地域の声を聞いていただきたいと思います。その中で特に聞いていただきたいのが子どもの声です。このような地域の声を大切にして、活用計画を幅広く検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"新妻委員","kind":"提案","question":"４点伺ってまいります。コールセンターの拡充についても要望いたします。併せて見解を伺います。１０月１１日から申請を受付け、１１月１日現在で１７７組が申請されていると伺いました。令和元年第４回定例会で議員より提案され、令和３年度に区の単費で予算化し、３か月で区独自のシステムを構築し、令和３年７月からおくやみコーナー開始と、短期間でスタートしたと伺いました。見解を伺います。","respondent":"吉野戸籍住民課長、加島人権啓発課長、鈴木選挙管理委員会事務局長","answer":"３０分、１時間という形になっておりますので、こちらも整備を検討してまいりたいと考えています。こういったことを定期的に実施しながら充実を図ってまいりたいと考えております。その場合には、会社で派遣される人材を集めまして、事前の説明会、研修のようなものをやっているのですが、どうしてもやはり。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"マイナンバーカード、期間が迫ってまいりましたが、また品川区の行政書士会の方々にもお世話になることと思いますが、よく連携をとっていただきながら、ぜひ進めていただきたいと思います。選挙管理委員会のご答弁に関しましても、やはりそういうふうに感じていらっしゃる方がいらっしゃるのが事実ですので、引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"１８１ページの男女共同参画推進事業について、私も品川区独自のパートナーシップ制度の導入を求めて伺いたいと思います。区として導入できない理由は何なのか、なぜ現時点ではとなるのか、そこをご説明いただきたいと思います。この立場と変わったのか、同じなのかどうなのか、そこを伺いたいと思います。","respondent":"加島人権啓発課長","answer":"２点ほどご質問をいただきました。まとめてご答弁申し上げます。パートナーシップ制度の導入につきましてですが、予算特別委員会で速やかに実施する方向で検討と答弁したことは承知しておりますが、できるところからやっていけるように努力していくともご答弁申し上げました。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"当事者の不安を解消するというのはおっしゃるとおりだと思いますが、なぜ品川区として導入できないのかというところがよく分かりません。品川区独自のパートナーシップ制度は直ちに必要だと思いますが、伺いたいと思います。ぜひ区として導入する際には、カップルと併せて、親子の関係も、家族というファミリーシップ宣誓制度を進めていただきたいと思いますが、それぞれいかがでしょうか。","respondent":"加島人権啓発課長","answer":"運用の開始は本格的にはこれからですけれども、区としては、これらの制度のよいところを集結されたと思われます都の制度を活用してまいりたいと考えているところです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ品川区独自のパートナーシップ制度の早期実現を求めたいと思います。具体的に、区の職員の結婚休暇について、改めて伺いたいと思います。東京都の動向も踏まえて、同性カップルについても直ちに結婚休暇を認めていただきたいと思いますが、いかがでしょうか。","respondent":"崎村人事課長","answer":"こちらの結婚休暇については、ほかにも、例えば、男性職員が利用する出産支援休暇ですとか、育児参加休暇など、様々休暇の関係ですとか、給付金の関係等がありますので、現在、検討を進めているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"職員について、同性カップルのときにも、直ちに区の制度として、カップルから申請がある前に、制度として同じく結婚休暇や、様々な休暇についても認める仕組みをつくる必要があると、同性カップルの当事者に対して心からお祝いをしていただきたいと思いますが、改めて伺いたいと思います。","respondent":"崎村人事課長、加島人権啓発課長","answer":"ただ、この結婚休暇等を取得するに当たって、当然、条例規則等の改正等も必要になってまいりますので、そういった規則改正については、先ほど人権啓発課長からお話がありましたけれども、区全体として、まず活用状況を検討した上で。不動産や医療などの面において、当事者にとってまだまだ支障となる状況があるというのは耳にしておりますので、都制度の開始を機に、区としてもしっかりと民間企業に働きかけてまいりたい、そのように考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"あらゆる制度が異性婚が前提で、同性カップルが排除されている状況は、やはり総務部全体が中心となって、品川区の様々な事業について、全ての結婚やカップルを祝福できるように、誰も制度から排除されないように、区政全体の総点検が必要だと思いますが、いかがでしょうか。そのためにも、区自身の姿勢を示すために、区独自のパートナーシップ制度の導入、改めて求めますが、それぞれいかがでしょうか。","respondent":"加島人権啓発課長","answer":"パートナーシップ制度の本質については、こちらも繰り返しになりますが、当事者が暮らしやすい環境づくり、住みやすい区であること、そこにつなげていくことがこの制度の本質だと考えておりますので、今、区ができることを前向きに捉え、進めてまいりたいと考えております。","id":"exchange-015"},{"speaker":"木村委員","kind":"質問","question":"私からは、しながわテレビ・プッシュ普及促進経費から質問いたします。令和２年度１２８万円余、令和３年度が１５１万円ですけれども、テレビを通じて区民に本区の何を知らせるための番組なのか、そして、その効果はどのような形で出ているのでしょうか。お聞かせください。","respondent":"佐藤企画調整課長","answer":"それ以外にも、電車の運行情報でございましたり、自治体が発信する生活情報もお知らせしております。主に、津波、目黒川の氾濫等想定地域に関しましては補助率も上げておりますので、そういった方々のところに防災性の高い情報をお届けするという趣旨です。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"全てが品川区だけの番組ではなくて、民放のような番組は流していないのでしょうか。何か見たような記憶があるのですけれども。私は、民放のような大きな反応はないけれども、それを繰り返し放送することによって、少しでも品川区を知ってもらう、また、品川区を理解していただくためには大変必要なことだと思っています。区民の反応はいかがなものなのか、お聞かせください。","respondent":"大澤広報広聴課長","answer":"ほかの地方の放送も面白いということで、区民の方から感想をいただいたことがあります。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"広報広聴経費の中の１７３ページのイメージアップ運動経費３２６万円余からですけれども、このイメージアップ運動とは、どこにターゲットを向けての活動なのか。拡大できる方向を探すなど、成果の分析などを行っていく必要性を思い、よりよい成果を求めますけれども、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"イメージアップ運動につきましては、平成３年度から粛々と進めております。あまりここで大きく何かを転換するとか、広げるとかという予定はございませんが、引き続き全庁で取り組んでまいりたいと考えています。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひまた頑張っていただきたいと思います。次に、職員報発行１３５万円余と記載されていますけれども、令和２年度は１１０万円余でしたから２５万円ほど増えております。これはどのような内容で職員に向けて発信する事業なのでしょうか。お聞かせください。","respondent":"大澤広報広聴課長","answer":"「品川区職員報ふれあい」ですが、これは、職員全員が区の様々な取組状況について把握できるように、情報を提供して、また職場紹介など職員同士のコミュニケーションを図るきっかけとして、年１０回発行しているものです。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"大変すばらしい活動だと思っていますけれども、職員が一堂になって１つのことに対して全力で向かうことは大変なことだと思いますので、どうぞ頑張っていただきたいと思います。令和２年度は７万８００円、令和３年度が６万２,０００円ですけれども、どのようなところに活用された費用なのかお聞かせください。そこのところをお聞かせください。","respondent":"大澤広報広聴課長","answer":"品川音頭の経費ですが、本来であれば、品川音頭を歌っていただいている岩本公水さんに、区民まつりに出演していただいて歌っていただくということでずっと続けていたのですが、コロナ禍で区民まつりも中止や縮小になりまして、岩本さんも出演できないということで。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問・要望","question":"頑張っていただきたいと思います。その品川をアピールするためには、言い方は悪いですけれども、目から入るものを攻めるほうが記憶に残りやすいと私も思っていますが、この点はいかがでしょうか。それとも、これからいけるかもというようなアイデアがあれば、またそれも教えてください。","respondent":"大澤広報広聴課長","answer":"品川音頭ですが、民放のラジオで流れたりですとか、映画に使われたりということもあるのですが、区としましても、今後、活用方法は検討していきたいと考えています。","id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"もうほとんど時間がありませんけれども、次に、地域スポーツ支援の中の高齢者スポーツの普及、障害者スポーツの充実からですけれども、予算が本当に少ないのです。なぜなのかお聞かせください。高齢者こそ体を動かすことが大変大事だと思いますけれども、そこもお聞かせください。","respondent":"辻スポーツ推進課長","answer":"高齢者スポーツの支援ですが、スポーツ推進委員会の委員にお願いして区と一緒にやっております。高齢者のスポーツのことは、他部とも一緒に連携しながら進めていきたいと思っているところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"１９３ページの歩行喫煙防止推進経費ですけれども、自動販売機を設置したときには、空き缶を入れるごみ箱を設置しなさいということが条例に書いてありますが、この辺は改めて伺いますけれども、現状はどうなっているでしょうか。独立しているのだから。８％とか９％とか、３か月目だと少し安いけれども、この延滞の利率も、ちょっと考えていくべきだと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"大澤広報広聴課長、崎村人事課長、森田生活安全担当課長、吉野戸籍住民課長、鈴木選挙管理委員会事務局長、提坂税務課長","answer":"「わ！しながわ」は、６年あまりの発信によりまして、地域の活動等でも活用していただき、区民の方にも一定浸透していると認識しています。この給料の７割水準というのは、一応当分の間の措置となっておりまして、国の法改正の附則でもありましたけれども。これにつきましては、状況を見ました上で、関係機関に要請をしています。個々のものにつきましても、状況を確認した上で個々に対応しています。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、人事課長、役職定年制が入ってくるということですけれども、たしか役職定年が入ると、２段階下がるというか、そうすると、部長職が係長になってしまうのですかという具体的な質問と、あと、給料が７割ということですけれども、なぜ同一労働同一賃金と伺ったかというと、ほとんど変わらないですよね、今。再任用になって。「わ！ここだけはやっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"崎村人事課長、大澤広報広聴課長、森田生活安全担当課長","answer":"そういった定年年齢の段階的な引上げに合わせて、国においても検討がなされるですので。「わ！しながわ」の変更の場合は、新区長の下で、いつどのように取り組んでいくのが適当であるか検討してまいりたいと考えております。条例につきましても、条例があるからこそ、業界団体や設置者に当たっては言えるところですので。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"分かりました。単刀直入に伺います。広報広聴課長、「わ！しながわ」、課長は好きですか。やっぱりこの「わ！しながわ」というものを担当の課長としてどう思われますか。その辺の答弁をいただきたいと思います。","respondent":"大澤広報広聴課長","answer":"個人的な好き嫌いの答弁は控えしますけれども、大変分かりやすくて、区民の方にも親しみやすい、よいキャッチフレーズだというふうに考えております。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"私からは、１７５ページの情報公開等経費で、文字としてはないのですけれども、情報公開と関連しますので、文書管理についても伺います。それから、１７９ページの人権啓発費、啓発講座などについて伺います。品川区が東京都の調査機関を参考にして調査ということであれば、後援申請とか補助金関係や委託関係について、東京都と同様に調査すべきではないかと考えますが、見解を伺います。","respondent":"古巻総務課長","answer":"特段、公文書の保存期間ということでの基準を設けての期間の設定ではございませんでしたけれども、区の調査として、東京都が３年間というのは直接聞いたわけではございませんけれども、報道等から得た情報に基づいて期間の設定をいたしましたので。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"一般質問に対するご答弁では、東京都の調査期間を参考にしたということだったので、参考にするというのであれば、東京都と同じように、文書によっては３年遡る、物によっては５年遡って調査するということで、そのようにすべきではないでしょうかということで、今、質問をしました。ちょっとこの間の一般質問のご答弁と矛盾するのではないかと思いますので、改めて伺います。","respondent":"古巻総務課長","answer":"調査期間の考え方ですけれども、東京都を参考にということに関しましては、東京都が文書の保存期間に基づいて調査期間を設定したという情報はこちらにはなかったので、そういった形で、全体的な調査期間ということで区として設定をしたものですので。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"これ、私、前もこういう質問をしたと思うのですけれども、そのように考えていただきたいと思います。この法律にのっとれば、品川区も文書の管理について条例をつくって、もう少しきちんとした管理をして、現在もしくは将来の区民に説明責任が生じたときに、それが活用できるようにすべきではないかと思いますけれども、再度ご見解を伺います。","respondent":"古巻総務課長","answer":"文書の管理に関しましては、総務課を中心に文書事務の取扱いでありますとか、様々な規程を通じて適正に行われているというふうに認識しておりますが、そこで今、委員からご紹介のあった部分、公文書の性格、公文書の法律的な位置づけを含めて、運用も含めてですけれども。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"今も適切に管理されていると思いますけれども、それがどう管理されているかは、区民から読み取れない状況だということです。ですので、ぜひ公文書の管理をする条例の制定なども強く求めたいと思います。今はもう東京都も、手数料は無料にしています。コピー代とか実費についてはやむを得ないかと思うのですけれども、改めて情報公開手数料を無料にすることを求めますが、見解を伺います。","respondent":"大澤広報広聴課長","answer":"閲覧等の手数料も含めまして、条例の改正案につきまして、情報公開等審議会でご審議いただいているところです。新たな条例につきましては、第４回定例会で上程する予定ですので、ご審議いただければと存じます。","id":"exchange-029"},{"speaker":"吉田委員","kind":"提案","question":"個人情報保護法の改定がもう間もなく提案されるということは、生活者ネットワークとしても理解をしてしっかり議論をしていきたいと思いますが、その中で情報公開手数料に関しては、ぜひ、一市民としての調査権を確保するためにも無料にしていただきたいというふうに改めて主張します。次に、人権啓発費の中の啓発講座についてです。「みんなのひろば」が開催されて、実践された評価をまず伺いたいと思います。","respondent":"加島人権啓発課長","answer":"２点のご質問をいただきました。「みんなのひろば」を実施した中での区としての評価ですけれども、「みんなのひろば」につきましては、令和２年度より開始いたしまして、これまで５回開催し、計２８人の方にご参加いただきました。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。それで、男女共同参画センターに関係するので伺うのですけれども、仮移転経費がここに計上されております。男女共同参画センターとしては、耐震化されていないところに仮移転するということについて、ご答弁は難しいかもしれませんけれども、どういうふうにお考えなのでしょうか。仮移転なので、今のところ耐震化できていなくてもやむを得ないということなのでしょうか。","respondent":"加島人権啓発課長","answer":"仮移転先についてのご質問をいただきました。旧荏原第一地域センターにつきましては、きゅりあん改修工事中の男女共同参画センターの仮の執務室として、令和４年１２月まで当該建物での執務を行う予定です。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"本来であれば、区がどうしてこういうふうな対応をしたかということを伺いたいのですけれども、今日はそれだと款を越えるかもしれませんので、ぜひその辺について、課長として、どういうふうに、ご相談にいらっしゃる方はご自身が困難な状況にあってそこにいらっしゃるわけで、そういう方たちへのこういう問題について、どのように共有して、いざというときの対応を考えておられるのか、改めて伺います。","respondent":"加島人権啓発課長","answer":"利用者への耐震化の件についての周知というところですけれども、大変難しい問題だと考えております。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。基本は、品川区全体として、きゅりあん建て替えに対して、こういう耐震化できていないところを仮移転先に選んだということ自体が、ちょっとどうなのかなというふうに思います。これからもいろいろ改修工事とかがあるし、その度に仮移転とかが必要になってくると思います。ぜひ今後はこういうことがないように主張して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問","question":"私からは、２１３ページ、選挙管理委員会運営費、２１６ページ、監査委員費、１６９ページ、企画調整費、１９１ページ、区民保養所経費、間に合えば、１７５ページ、ＩＣＴ推進管理費まで伺いたいと思います。選挙管理委員会運営費について伺います。仮に正当化できるとすれば、どういう観点から正当化できるのか伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、ご質問の地方自治法の趣旨に基づいてというところでお答えをいたしますと、委員に就任した後ですが、基本的には、立候補の制限なり選挙運動の制限、また守秘義務といった公務員としての義務が課されて、制限も発生するということで。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"難しい質問にお答えいただきまして、ありがとうあります。基本的には、議会の責任ということになってこようかと思います。それを理解しつつ、次に、事務事業概要によると、選挙管理委員会は、月２回の定例会が行われていると記載されております。１回当たりの会議時間はどの程度なのか、お伺いいたします。","respondent":"鈴木選挙管理委員会事務局長","answer":"月２回の定例の委員会につきましては、基本的には１時間から１時間半程度です。内容としまして、選挙人名簿の登録であったり、また、選挙前には、臨時会で様々な選挙に関する決定をしていただいているものです。","id":"exchange-035"},{"speaker":"松本委員","kind":"確認","question":"ほかの自治体、議事録を確認すると、月１回というところがかなり多いのです。月１回で、その中でも、１回当たりの時間が３０分というような選挙管理委員会が結構多いです。そういうものもないと、今みたいな、「いや、ほかの自治体では月１回しかやっていないのに、なぜ品川区は月２回なのだ」というような不信感も生まれてくるのではないかと思いますが、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"そういう意味では、今ご指摘のあったように、今は区のホームページに議事録を掲載はしていないのですが、区民の方に選挙管理委員会の活動をしっかりと知っていただくという観点からも、区のホームページでの公開を検討したいというふうに考えます。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問","question":"報酬の関係も、委員長については２８万５,０００円ということで月額で出ている。ご答弁ありがとうございました。続きまして、これも似た関係になってくるのですけれども、監査委員についてもお伺いしたいと思います。この改正を受けまして、大阪府は、直ちに議選監査委員は廃止しました。法改正を受けて、当区において議選監査委員を廃止する、あるいは、１名に減らすといった議論は行われたのか伺います。","respondent":"高山監査委員事務局長","answer":"私どもは監査委員事務局という立場ですので、本件につきましては、議員選出の監査委員を選任するというふうに品川区の条例上はなっておりますので、私どもの立場から、この是非でありますとか。","id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"この監査委員は、私が言うまでもありませんけれども、極めて専門性が高い、しっかりと見ていかないといけない仕事なのだと思います。監査委員就任に当たって、監査の研修は行われているのでしょうか。議選監査委員の実働は、大体何日ぐらいというふうに考えればよろしいでしょうか。","respondent":"高山監査委員事務局長","answer":"選任に当たりましては、議員選出の方々は、もともと区政に精通されているということで、一定程度の素養をお持ちの方々が選任されているものではありますが、私どもとしましては、就任に当たりまして、いわゆる年間の監査の計画でありますとか、監査に関する守秘義務の関係のお話。","id":"exchange-038"},{"speaker":"松本委員","kind":"確認","question":"４０日ということを理解いたしました。当区では、行政監査が、少なくともホームページで確認する限り行われていないように拝見しますが、定期監査とは別に、区の事務の執行が適切に行われているのか、テーマを決めて深掘りすべきと思います。これは事務局にお伺いするのがどこまでいけるかは分かりませんけれども、お答えいただければ幸いです。よろしくお願いします。","respondent":"高山監査委員事務局長","answer":"そういった中で年間の監査事務量を監査委員協議会の場でご調整いただきまして、ここ数年においては実施しておりませんが、しかるべきテーマを設定して、今後も続けていくことが、区にとっても大変有効だというふうに考えておりますので。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"監査委員報酬、監査制度自体についてもさらに伺いたいのですけれども、これも選挙管理委員会と同様です。次に、企画調整費について伺います。こちらは地方自治法第２３３条５項に提出しなければならないと定められてあります。今後は、この総合実施計画の指標を主要施策の成果報告書に取り込んでいく、そのようなことが行われる予定があるのかお伺いいたします。","respondent":"黒田財政課長","answer":"成果報告書としての性格もありますので、そういった記載内容については今後も検討してまいりたいというふうに考えてあります。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問・要望","question":"やはり目標が設定されるということは、我々としても、区民としても、しっかりと見ていけるということがあると思いますので、ぜひご検討をお願いしたいと思います。ここもやはり載せていただきたいというところがあるのと、あと、事業収支も内訳の記載がやはりなかなか少なくて総括的な記載になっています。ここも工夫の余地があると思いますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"区では、令和３年度に指定管理者制度活用に係る基本方針を改定いたしまして、選定結果等の公表拡大、また、総括シートについても、利用者数等の運営実績と事業収支の欄が一緒だったのですけれども、それを分割して、より多くの情報を書けるように一応見直したところで。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"続きまして、区民保養所経費について伺います。現在、品川区は２つの保養所を保有しています。平成２４年４月から民間貸付方式に移行し、事業者に無償で貸し付けています。修繕とか、いろいろあると思うのですけれども、ただ、これだけの費用をかけて、区が現在においても保養所を運営する、その理由について、どういうものがあるのか伺います。","respondent":"川島地域活動課長","answer":"区民保養所につきましては、区民の健康増進、それから保養を目的とするという事業で実施しているところで、今、多くの区民に愛用していただいているという状況があります。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問・要望","question":"現代社会において、多様なニーズが出てきているという中で、果たして、これだけ費用をかけて区が保養所を経営していく必要があるのか、私としては、これはもう整理していただきたい、廃止していただいて、それよりもニーズが高い事業、例えば、先ほどの早川町などの助成というようなものを行っていただいて、より予算を効率的に運用していただきたいと思いますが、いかがでしょうか。","respondent":"川島地域活動課長","answer":"他区の状況を見てみましても、自前の施設を手放すような流れもありますし、保養事業の見直しをしている区が３区ほどあるというふうには聞いてあります。そうした状況も適切に判断しながら、今後の方針は決めていきたいと考えています。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"「あつまれ！通知をいたしました。えばら」で、１０代後半から２０代の若者の参加を特に増やしていただきたいと要望いたしますが、今後の展望をお聞かせください。全体が７０％で、そのうち管理職は５８％、全体もそうですけれども、特に管理職の休暇取得率を上げていただきたいと要望いたしますが、区のお考えをお聞かせください。こちらも昨日の続きですが、３点目に、財政管理費についてお伺いいたします。","respondent":"篠田文化観光課長、崎村人事課長、黒田財政課長","answer":"どうしても行政が関わるイベントですと、小さいお子さんから高齢者の方まで。昨日、取得率についてご報告いたしましたけれども、管理職については特に低いという状況もありますし、今年の人事委員会の勧告の中でも。児童相談所設置に係る財調協議ですけれども、今回の財調協議は、単に事業に対する費用ということではなくて、都区の役割分担の中で。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"４点目に、監査委員費についてお伺いいたします。地方自治法の改正により、内部統制制度が創設され、令和２年４月からは都道府県と政令指定都市で内部統制制度の整備運用が義務化されました。今後も確実に進展していくであろう人口減少社会においても、行政サービスを安定的、持続的、効率的かつ効果的に提供していくためには、その要請に対応した地方行政体制を確立することが求められています。","respondent":"高山監査委員事務局長","answer":"今後の監査に与える影響ですが、内部統制制度が導入・実施されている自治体におきましては、首長における内部統制評価報告書の作成と、監査委員における審査が十分に行われているといったことを前提といたしまして、より効率的。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"今後もこちらの体制について、他の自治体の先行事例などを参考に、調査研究をお願いしたいというふうに思っておりますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"江野下委員","kind":"質問","question":"私からは、２０３ページ、区民スポーツ大会についてお伺いいたします。私も一ランナーとして、開催をとてもうれしく、楽しみにしております。準備委員会、観光資源、コースの設定、参加料の現状など、お聞きしたいと思います。","respondent":"辻スポーツ推進課長","answer":"委員から、今、お話しいただきましたとおり、従来もロードレースという形で区民スポーツ大会の一競技として実施しておりましたが、もっと多くの方が気軽に参加できる、そして、東京２０２０大会のレガシーの継承として。","id":"exchange-047"},{"speaker":"江野下委員","kind":"質問・要望","question":"私は１０月に東京レガシーハーフマラソン２０２２にも参加してきましたが、参加費が２万７００円、参加料、参加記念Ｔシャツ、事前検査費用、参加費等返金保険料、事務手数料、消費税込みということで、大変高額で、ランナー仲間からは、参加費が高くて参加を見送ったとの声も多く聞いております。区民の方が参加しやすい参加料を検討していただきたいと思います。今、参加料は決まっておりますでしょうか。","respondent":"辻スポーツ推進課長","answer":"委員ご指摘のとおり、このところ、コロナの関係もありまして、参加料はどの大会も上がっておりますが、やはりあまり高いと参加する方も躊躇する部分があると思いますので、参加しやすい料金と、安全性を担保した内容にするということも含めまして。","id":"exchange-048"},{"speaker":"江野下委員","kind":"提案","question":"協賛企業もまだまだこれからだとは思いますが、参加料以上にお得感のある参加賞を検討していただきたいです。提案ですが、ほとんどの大会は、参加賞として、Ｔシャツ、タオル、メダル、飲料水やスポーツドリンクなどが多いですが、例えば、Ｔシャツやメダルがシナモロールのデザインであったり、何かシティプロモーションとつながったオリジナル性のある参加賞を期待しております。こちらはいかがでしょうか。","respondent":"辻スポーツ推進課長","answer":"こちらの大会は、やっぱり品川の魅力を区民にも区外の人にも知っていただきたいという思いが強くあります。ですので、今、委員からご提案があったようなものを取り入れながら、地域ぐるみで、オール品川で盛り上げられる大会にしたいと考えています。","id":"exchange-049"},{"speaker":"江野下委員","kind":"質問","question":"オール品川、いいですよね。コロナ禍でデジタル化が進んで、インターネットによる申込みが多くなり、大会までの健康チェック、当日の受付と、全てスマートフォンだけでできるようにもなり、大変便利にはなりました。しかし、申込みと健康チェックでアプリが別であったり、利用する側としては、とても分かりにくい大会もあると聞いております。この辺はどのようにお考えか教えてください。","respondent":"辻スポーツ推進課長","answer":"利便性がすごく上がった反面、煩雑になっている部分も逆にあるというふうに聞いております。大会が令和６年度ということで、まだ若干時間がありますので、アプリを統一するですとか、参加者がとにかく参加しやすいといいますか、そういった大会になるように工夫してまいります。","id":"exchange-050"},{"speaker":"江野下委員","kind":"意見","question":"スマホやパソコンをお持ちでない方もいらっしゃると思いますので、誰もが参加しやすい申込み方法も必要だと思います。先ほどの距離の設定でお話がありましたが、最近はファミリーランも人気があって、小さなお子様と一緒に楽しめる大会であることは、とてもよいことだと思いますが、年齢の設定などもお聞かせいただければと思います。","respondent":"辻スポーツ推進課長","answer":"ただ、委員のご指摘のとおり、家族で楽しく走るですとか、そういったことも大切かなと考えていますので、メイン種目以外にも家族で楽しめるですとか、小さな子が参加できるような種目も検討しております。","id":"exchange-051"},{"speaker":"江野下委員","kind":"提案","question":"提案ですが、幼児の方も参加できるように、フルマラソンは４２.１９５ｋｍですが、数字だけは同じにして、４２.１９５ｍとかはいかがでしょうか。先ほど、レガシーの継承にもありましたが、障害者の参加はどうなっておりますでしょうか。お隣の目黒区の目黒シティランでは、全ての種目に障害のある方も参加できるようです。こちらをお聞かせ願えますでしょうか。","respondent":"辻スポーツ推進課長","answer":"障害のある方ということで、車椅子レースになってしまいますと、速さがあまりにも違うので、ちょっと一緒は厳しいかなと思いますが、その他の方に関しては、配慮をした上での参加ももちろん検討をしています。","id":"exchange-052"},{"speaker":"江野下委員","kind":"質問","question":"事前に大会へ向け機運を盛り上げるためにも、ランニング教室ですとか、かけっこ教室などの開催、オンライン教室、動画配信も含めて、そちらはお考えでしょうか。","respondent":"辻スポーツ推進課長","answer":"今年度、来年３月にロードレースを行いますので、そのときにパラレルイベントで何かやってみようかということで、ただいま検討中です。","id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"１８５ページ、公有財産管理費に関わって、第一日野小学校跡地利用について質問いたします。第一日野小学校が２０１０年に今の場所に移転しました。ところが、ＴＯＣの都合により、建替計画が延期となったにも関わらず、２０１０年から２年間、暫定駐車場として貸し出しました。伺っておきます。結局、第一日野小学校という学校の跡地を一体何年間、株式会社テーオーシーに貸し付けたのでしょうか。伺います。","respondent":"佐藤企画調整課長","answer":"旧第一日野小学校跡地の貸付期間に関わるご質問です。平成２２年９月６日から、駐車場として２年間、その後、１０年間、令和４年９月まで貸し付けたです。","id":"exchange-054"},{"speaker":"おくの委員","kind":"質問・要望","question":"これまでに２回解体があって、２回目の建設が今やられているわけですけれども、そして、これだけの負担を押しつけられながら、地元住民の要望は何も実現されていません。暫定施設建設のたびに振動と騒音に悩まされた。区民の財産である公共用地、これは区民要望を生かした使い方をすべきだったと、公共用地の使い方について、こういう反省をすべきではないかと思いますが、いかがでしょうか。伺います。","respondent":"佐藤企画調整課長","answer":"区といたしましては、地元の地域経済の活性化ということで用地を貸し付けまして、地元の方々に、当時、丁寧な説明をしてきたところです。委員ご紹介のとおり、契約といたしましては、事業用定期借地権という手法を使わせていただきました。","id":"exchange-055"},{"speaker":"おくの委員","kind":"質問・要望","question":"ただ、こういう跡地を区民要望がたくさんありながら、特養ホームをつくってほしい、あるいは公園をつくってほしい、あるいは障害者施設をつくってほしいということが、アンケートや、それから直接のお声を伺う中で、前々からたくさん出てきていたにも関わらず、ＴＯＣが建て替えのために貸してほしいということを言っただけで、その区民要望は横にどけて、ＴＯＣに差し出し、そして、脇目もふらず。","respondent":"佐藤企画調整課長","answer":"当跡地に関する利用の目的ですが、五反田ＴＯＣビル建て替え事業中等における五反田地区の地域経済の活性化、まちのにぎわいに資することというところで、議会のほうにもご報告させていただき、地元のほうにも説明会等を行ってきたところです。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"今のご説明だと、さも周辺にも非常に経済的効果があったように聞こえるのですけれども、客観的データがあるわけではないと思います。客観的なデータをお示しになって言われたわけではありません。そこら辺が検証されているわけではないのではないでしょうか。だから、必ずしも１２年間の貸付で成果があったというふうには言えないのではないかと私は思うのですけれども、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"成果につきましては、先ほどご答弁したとおり、特別に調査をしたわけではないですけれども、当時の答弁の内容として、そういったご紹介をさせていただいているというところで、今、私のほうではお話しさせていただいたところです。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問・要望","question":"住民要望には特養ホームがあります。ぜひこれをつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"つる委員","kind":"提案","question":"お願いします。１７３ページ、広報番組等経費、１７７ページ、非核平和都市品川宣言事業、１８５ページ、会計事務費、１９３ページ、市町村交流事業、１７４ページ、情報化推進費、２０１ページ、プラネタリウム、五反田宇宙ミュージアムについて伺いたいと思います。サン＝テグジュペリという作家がいて、『星の王子さま』の中で、「心で見なければ物事はよく見えないってことさ。","respondent":"古巻総務課長","answer":"モニュメントに関しましては、まだちょっと具体的な検討が進んでいる状況ではないのですが、ご答弁させさせていただいたことに何か変更があったりとか、そういうことではありませんので、引き続きですけれども、検討させていただきたいというふうに考えております。","id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ、平和というのはやはり、この事業は取り組み続けていくことがとても大事ということで過去にも確認させていただきましたけれども、引き続きその内容の充実、そして拡充をお願いしたいなというふうに思います。公園に関しては、土木費のところでまた改めて伺っていければいいかなと思っています。改めて、平和に関する取組は引き続き求めていきたいと思いますので、よろしくお願いいたします。","respondent":"中山会計管理者","answer":"「よくわかる！品川区財務諸表」概要版についてのご質問です。説明責任の充実というところでは、なかなか分かりにくい区の財務諸表を、概要版という形で区民の皆様にお示しできたところがまずは第一歩かなというふうに思っております。","id":"exchange-060"},{"speaker":"つる委員","kind":"提案","question":"ここについては、こういった財務４表、諸表ができて、今までとこれからというところで、区民の側にも品川区の状況をしっかりとご理解いただいて、議会側としても、例えば提案、また改善等を求めて、区民の方にもお声をいただくということに資するものになっていかなければいけないわけですし、そういう力もつけていく必要があるかと思います。","respondent":"宮澤情報推進課長","answer":"デジタル庁が運用しておりますマイ制度ナビ、手続等の支援制度を検索できたりするものということで制度の運用が始まっております。その中で市区町村の手続に関してのアップロードはこれからということになっておりますので、現在のところはまだ手続の登録はされていないです。","id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"これは自治体によっていろいろな取組の差があるかと思います。品川区は、２３区の中でチャンネル登録数は３番目ぐらいの登録者数ですか、今は８,１２０人ぐらいだと思うのですが、このチャンネル登録数と、それから、自治体によっては、しながわネットＴＶに、ＹｏｕＴｕｂｅですけれども、広告を取り入れていくというところもあるのですが、この辺のところが何かあれば、コメントをいただければと思います。","respondent":"大澤広報広聴課長","answer":"ＹｏｕＴｕｂｅの広告に関しましては、区が選んで広告を出すことができないので、今のところ、考えてはおりません。","id":"exchange-062"},{"speaker":"西村委員","kind":"質問","question":"１９７ページ、観光サービス充実事業、外国人観光客誘致事業、２００ページ、スポーツ推進費、時間が余れば、１７３ページのシティプロモーション推進経費について伺ってまいります。オリ・パラのレガシーとして残っております大井ホッケー競技場来場者の観光について伺ってまいります。土日に定期運行してほしいというような子育て世帯の方の声も届いております。","respondent":"辻スポーツ推進課長、篠田文化観光課長","answer":"今、委員のほうからお話のありましたマスターズワールドカップ、６０歳以上の世界中のホッケープレーヤーが７００人前後集まりましてホッケーを楽しんだです。委員のお話にもあったとおり、土日に定期運行してほしいというような話も私どもも承っているところですので、今後、そういったところを考えながら展開に生かしていきたいというふうに考えているところです。","id":"exchange-063"},{"speaker":"西村委員","kind":"意見","question":"アイルしながわで雅楽の打球楽をやりますという情報はクルーズのチラシに載っていたのですけれども、５００円で１日中乗り放題で船に乗れますよという案内だけだったのは、もったいなかったなというふうに思っております。それぞれに取組をしていただいていたのは分かっているのですけれども、実際に今回、スポーツ推進課と文化観光課がどのように連携をしておられたのかお聞かせください。","respondent":"辻スポーツ推進課長","answer":"そういったことで、最初はそのように連携をスポーツ推進課と文化観光課とでしていたのですけれども、実際はちょっと違ったところもございましたので、今回のことも受けながら、どういう形で、どういうふうに連携して区を盛り上げていけばいいのかということは。","id":"exchange-064"},{"speaker":"西村委員","kind":"質問","question":"本当にそうだなというふうに思うのですけれども、それぞれの催しが盛況でしたので、つながっているのか、つながっていないのか、ちょっと分からない感じが正直ありました。このような大きな大会があったときには、なおさらそれぞれの予算の事業をどこかの部分でつなげることができればと思ったのですが、もう一度お考えを伺います。","respondent":"篠田文化観光課長","answer":"いずれにしましても、これからコロナが落ち着いてきて、実際に日本に来られる外国人の方が増えてくるということが当然見込まれますので、この間、特にインバウンドに対する対応が非常に手薄な状況が続いてきてしまったということがあるものですから、改めて。","id":"exchange-065"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは、１９３ページの歩行喫煙防止推進経費について、２１３ページの選挙関連の啓発費について伺いたいと思います。そこで、マナーアップを図るためには、この過料された場所を把握されなければならないと考えておりますが、こうした過料されたエリアはご存じでしょうか。お知らせください。巡回指導員の方から、何かご意見がありましたら、参考までに教えていただきたいのですが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"平成１５年に施行されました歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例につきましては、５つの指定地区を設けておりまして、これにつきましては、ホームページやチラシなどで示しています。そういった場所での取締りにつきましては、順次やっているところです。","id":"exchange-066"},{"speaker":"松永委員","kind":"質問・要望","question":"なぜ聞いたかというと、やはりそうしたポイ捨てをする場所が、大体この人はここに捨てるのだなと、そういったところが分かるのではないかと。要するに、過料したところが分かれば、そういったところを巡回したら、また別のところに移動するという人もいるかもしれませんが、ぜひともそういった指導をしていただきたいと、過料された場所を知っていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"今現在、喫煙のマナーアップにつきましては、シルバー人材センターと契約をしておりまして、オレンジ色のジャンパーとたすきをかけながら回っていただいているとともに、私どもの生活安全サポート隊のほうで、広報もしながら回っているところです。","id":"exchange-067"},{"speaker":"松永委員","kind":"提案","question":"そこで提案ですが、鉄道会社と連携をして、マナーアップ向上のために、改札口を出てすぐのところにポスター等を張っていただけないかと考えますが、いかがでしょうか。駅周辺にお住まいの方は、どこに喫煙所があるのか分かると思うのですが、初めて来られる方については、どこに喫煙所があるのか分からないといった声も伺っております。ご意見をお聞かせください。","respondent":"森田生活安全担当課長","answer":"あちらの表示につきましては、私どもから駅と相談して設置をしてもらったというところがあります。現在のところ、表示につきましては、路面標示、または横断幕、または排水口にポイ捨てをする人がいますので、そういったところにも張ったりしています。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問・要望","question":"マナーアップ向上のためにも、商店街の活性化も含めて、ぜひご検討いただきたいと思います。２１３ページの選挙関連の啓発事業について伺います。それぞれ確認いたしましたが、区民にとって関心がある選挙では投票率が高いのではないか、関心がない選挙については低い水準となっているというふうに私は思います。品川区として、なぜこのように投票率に差があるのか、お考えをお聞かせください。","respondent":"鈴木選挙管理委員会事務局長","answer":"都知事が、国政と区政の選挙の中間ぐらいの数字が基本的なところで、特に区長選挙につきましては、前任の区長が４期にわたって長くやっていたということで、ある意味、安定を区民の方も感じていただいて。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問","question":"私は、こうした有権者の皆さんへの啓発ではないかというふうに改めて思います。ホームページやポスター、宣伝カー、街頭活動などありますが、先ほどもお伝えさせていただいた、やっぱり一番はポスターではないかというふうに思っております。こうした若年層の方が多いと考えていますが、最後に、若年層とは、大体何歳までの人たちを表しているのか、そうした現状を教えていただければと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"区の選挙管理委員会としましては、１８歳、１９歳、それから２０代前半、この世代の方たち向けに、個別の若年層向けの啓発を通常のケースとは別に行っているところです。","id":"exchange-070"},{"speaker":"松永委員","kind":"提案","question":"最後に提案です。人が多く集まるところ、いわゆる駅構内や電車内のモニター、エレベーターに設置されているモニターやポスターを張れるスペースがあれば張るなどして、本気で周知をしていただければと考えていますので、ぜひご検討のほど、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１６９ページから始まる総務費の各課に記載されている会計年度任用職員の待遇改善について、また、ページの記載はありませんが、統一教会の問題について伺います。会計年度任用職員についてです。今年４月の会計年度任用職員が１,３６２人、そのうち女性が１,１２９人となっていますが、その後の変更があるか、まず伺います。正規職員の人数も伺います。","respondent":"崎村人事課長","answer":"今、会計年度任用職員の人数を委員からご紹介いただきましたけれども、その後の変更という部分につきましては、４月以降、例えば選挙管理委員会の選挙の事務で短期で雇用したりですとか、体調不良により退職したということもありますので、差引きは当然ながら変動はあります。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"約１万４,０００人の方から回答がありまして、その中間報告をしています。６つ目が、任期がありますので、そこで雇用を継続されるかどうか不安を感じているということです。これらに照らして、区の状況を伺いたいと思います。年収２００万円未満の方の人数を伺います。そして、正規の職員の方と同等の仕事をしている方が何人いらっしゃるのか、分かれば教えていただきたいと思います。","respondent":"崎村人事課長","answer":"今、数字のお求めがありましたけれども、特に人事課のほうで、例えば年収２００万円以下の会計年度任用職員の方、５年以上働いている方という数字の統計をとっているわけではございませんので、今すぐお答えすることはできません。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"数字をとっていないということでしたけれども、もし分かれば、感覚を持っていらっしゃればお聞きしたいと思います。それで、具体的な数字は持っていないということですが、そうしたら、正規職員と会計年度任用職員の手当や給与、休暇も含めて、違いを伺いたいと思います。","respondent":"崎村人事課長","answer":"最初に、感覚で答えていただけないかというお話ですけれども、こういった場ですので、私の感覚でどのぐらいということをお答えするのは適当ではないというふうに考えております。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"休暇のところでも、無給と有給の部分があるということですので、そこの改善を求めたいと思いますが、いかがでしょうか。長く働いていても昇給されないということで、なかなかモチベーションのほうにも反映してくることだと思いますので、他区の自治体では上がっていくような制度もありますから、品川区としても、ぜひ昇給制度をつくっていただきたいというふうに思いますが、いかがでしょうか。","respondent":"崎村人事課長","answer":"他自治体においては、今、委員からご紹介がありましたように、昇給といいますか、経験加算をしているところもありますけれども、そういったところの中でも、経験加算を例えば１回限りにしているところですとか、また。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、期末手当も変更になるということで、特別区長会と組合と交渉されているそうですけれども、これが実際の現場の人には何も相談なく、３回から２回に減らされるということで、その分、給料は減ってしまうという声も届いておりますので、そこもぜひ交渉の場を設けつつ、職場の意見を聞きながらやっていただきたいと思いますが、いかがでしょうか。次に、統一教会のほうに移ります。","respondent":"崎村人事課長、古巻総務課長","answer":"こちらについては、現在、職員労働組合の２３区の共同体であります特別区職員労働組合連合会と区長会で労使交渉の方向になっているところですので、労使交渉の協議の結果を踏まえて、適切に対応していきたいと考えております。旧統一教会に関する調査の期間についてですけれども、東京都の調査期間を参考にさせていただいたということで、何年が適切かというのは、なかなかこれは難しいというふうに思いますけれども。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"会計年度任用職員の格差是正は、ぜひ引き続きやっていただきたいと要望しておきたいと思います。統一教会のところは、なかなか基準は難しいということですが、そうすると、区の書類の保存期間にならって決まったということなのか伺います。保存期間は何年というものを区が持っているのか。実際に書類は何年分残っているのか伺います。","respondent":"古巻総務課長","answer":"保存期間と連動した期間の設定をしたものではございません。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"ということは、書類はまだ残っているということなのでしょうか。伺います。","respondent":"古巻総務課長","answer":"残っているもの、残っていないものがあると思いますけれども、そこの保存期間の考え方につきましては、品川区の文書事務の基準にのっとっているところです。","id":"exchange-078"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、２０５ページ、しながわ文化プログラム、それから１７３ページ、シティプロモーション推進経費を質問します。結果として、新型コロナウイルスの発生によって１年延長した後、無観客となってしまいましたが、メディアを通じてしか観戦できないということが、世界中全員同じ条件で応援をするということになって、逆に今まで以上にオリ・パラ大会に関心が高まったのではないかとも思っております。","respondent":"篠田文化観光課長","answer":"昨年は、オリンピック・パラリンピック実施年ということで、事業としては、８本ほど、３００万円規模の助成事業と、８０万円の助成事業がございました。こちらはそれぞれ、例えば、スローレーベルというグループであれば、今回、午前中もお話がありましたが、「あつまれ！","id":"exchange-079"},{"speaker":"湯澤委員","kind":"質問・要望","question":"今、お話がありましたけれども、オリンピック・パラリンピックのレガシーでもあります、「する」、「みる」、「ささえる」は、スポーツの域を超えて、文化芸術、そして教育といった様々な分野で広げていってほしいと考えています。関心を持ったことに自分のスタイルで誰もが参加できる、そういった機会は今後の文化プログラムにおいて行っていただきたいと考えています。","respondent":"篠田文化観光課長","answer":"今年度から、そのことも引き継ぎながら、改めて品川区における文化団体等の掘り起こし等も含めて、規模は少し小さくなっているのですけれども、昨年までの例えば助成が３００万円とか８０万円とかということではなくて、１団体当たり５０万円の。","id":"exchange-080"},{"speaker":"湯澤委員","kind":"意見","question":"いろいろな人が参加できるものの１つとして、盆踊りに注目させていただきました。そういったイベントは、外国人観光客にとっても大きな魅力の１つであると思います。私はこういった新しいスタイルの盆踊りに物すごく衝撃を受けましたし、可能性も感じました。ぜひ目玉企画にしてもよいのかなというふうに思っているのですけれども、その辺のお考えをお知らせいただければと思います。","respondent":"篠田文化観光課長","answer":"ただ、区として、盆ダンスをどんどんやろうかということになると、なかなかイベントの中でどういうやり方をするかということもありますし、また、イベント自体、区が主催するものよりも、どちらかというと、それぞれの実行委員会ですとか。","id":"exchange-081"},{"speaker":"湯澤委員","kind":"提案","question":"他区のほうでは、どういった盆踊りをしているかと私も調査してみました。そこで、提案なのですけれども、品川区民が一体感を持って参加できるような、品川盆踊りサミットを創設してはいかがでしょうか。この品川盆踊りサミットの創設によって、しながわ文化プログラムを拡充していただきたいとも思いますが、ご見解をお伺いします。","respondent":"篠田文化観光課長","answer":"すぐにできるかどうかという話にはなかなかなりづらいのですけれども、今後、地区における文化面の機運醸成といった意味でも、今後、研究してまいりたいというふうに考えるところです。","id":"exchange-082"},{"speaker":"湯澤委員","kind":"質問・要望","question":"イベントを行うと、一部の地域の方だけが盛り上がっているなとか、偏った世代だけが楽しんでいるという印象を受ける方もいらっしゃるのですけれども、先ほどの「にしこやまつり」などは、目黒区との境にあるのですけれども、本当に何度もになりますけれども、大変盛り上がっていましたので、そのノウハウをぜひ、既存の企画のメニューにも取り入れていただいたりして、地域や年齢、そして障害。","respondent":"大澤広報広聴課長","answer":"その後は、コロナ禍によって発信方法などを変えてまいりました。いずれにしましても、シティプロモーションの主役は区民であるという方針の下に、区民とともに進める魅力発信を大事に進めているところです。","id":"exchange-083"},{"speaker":"湯澤委員","kind":"意見","question":"シティプロモーション推進経費の中に、交通機関活用による認知度向上とありますけれども、こちらもシティプロモーションの一環として、主にバスや電車において、品川区の宣伝を効果的に行っていくものだと認識しております。これを区内、区外、どちらに向けて行っているのかもお願いいたします。","respondent":"大澤広報広聴課長","answer":"令和２年は、これに加えまして、京浜東北線の中吊り広告もやったところです。交通機関でのＰＲにつきましては、どちらかといいますと、当区を訪れる方とか、当初は東京２０２０大会で訪れる方に向けて発信したものです。","id":"exchange-084"},{"speaker":"湯澤委員","kind":"意見","question":"認知度向上というところで、どのような効果があったのか、検証は難しいと思うのですが、このプロモーションの検証については、どのような検証を行っているのか、費用対効果についてもお聞かせいただければと思います。令和３年度から令和４年度に向けて予算が減額している理由も併せてお知らせください。","respondent":"大澤広報広聴課長","answer":"直接的な効果の検証は難しいところですが、トレインチャンネルのニュースや天気予報と並んで、自治体のトレインチャンネルというのは珍しいことから、民間事業者のホームページでも紹介されるなど、一定の話題性や注目度があったかというふうに思っております。","id":"exchange-085"},{"speaker":"湯澤委員","kind":"質問・要望","question":"効果があるものはぜひ行っていただきたいと思いますし、効果が難しいと感じたものは、担当部署の判断で取りやめも検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"せお委員","kind":"質問・要望","question":"総務省からの通知で、選挙の立候補に関しては、旧姓の通称申請があった場合には、戸籍の謄本または抄本を確認すれば、証明書類を求めることなく通称認定して差し支えないと示されました。そして、この通知以降、対応が変わったのであれば、令和３年度の部分だと、都議会議員選挙、衆議院議員選挙の部分かと思いますけれども、この対応をする上で、何か予算はかかってきていますでしょうか。お聞かせください。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご質問の届出に関する旧姓等の使用についてですが、ご指摘のとおり、令和２年に総務省から通知がありまして、国の立候補届出に関しては考え方が変わる、プライバシーの配慮をということで内容が変わるということで通知がありまして、その通知で。","id":"exchange-087"},{"speaker":"せお委員","kind":"質問","question":"予算がかからないでこういった政治参加が身近になるのであれば、区としてどんどん進めていきたいと思います。は前進したので、ありがたいなと思っています。そこで、今挙げた中の政治や選挙を子どもの教育の場で取り上げることに関しては、選挙管理委員会として、令和３年度はどのような取組をしましたでしょうか。そして、今年度も含めて、今後、新しい取組が決まっていましたら教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"子どもの頃から選挙に関して知識を得たり、関心を持ったりというための活動ですが、品川区におきましては、平成２６年度から、品川区明るい選挙推進協議会と連携いたしまして、区立の小中学校における出前模擬選挙という事業を実施しております。","id":"exchange-088"},{"speaker":"せお委員","kind":"提案","question":"私たちも議会側からそれを様々取り組んでいきたいと思っています。さらには、投票に行ってもらうきっかけは、いろいろ取り組んでみてつくれると思っているのですけれども、今までも区では様々取り組んでいただきましたが、まず、投票済証を、私も提案させていただきましたシナモロールが描かれた名刺のようなすてきなものに変更になりました。ただ、ネットでの転売も行われてしまったと私は確認しています。","respondent":"鈴木選挙管理委員会事務局長","answer":"転売等に関してですけれども、これは著作権を持つサンリオにも確認はしたのですが、やはり有償、無償に関わらず、どなたかに譲渡した場合には、所有権自体が移ってしまいますので、その先の転売を禁じたり、強制的にやめさせることはできないですので。","id":"exchange-089"},{"speaker":"せお委員","kind":"質問・要望","question":"ポスターもその前に一新されていて、こちらに関しては、民間の方でポスターを張りたいという方もお声があったので、もう少し広げて、ポスターは民間の方も張れるようにしていただきたいなと、そこだけ要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"あくつ委員","kind":"確認","question":"私からは、１７５ページ、情報システム運営費、２１１ページ、個人番号カード経費、１９１ページ、国際交流推進事業、時間があれば、１６８ページ、総務費からお伺いしたいと思います。情報システム運営費、個人番号カード、昨日に引き続き、マイナンバーカードについて伺っていきたいと思います。品川区の１０月末の段階での申請率と、また交付率を教えてください。","respondent":"吉野戸籍住民課長","answer":"マイナンバーカードの申請件数ですけれども、２７万８,０００件、申請率が６９％になっております。交付率は５３.４％に上っております。","id":"exchange-091"},{"speaker":"あくつ委員","kind":"確認","question":"まだ申請された全員の区民の方が受け取ったわけではないですが、６９％ということで、約７割の方が申請を終えられているということを確認させていただきました。品川区の場合は、大都市ですから、区に住んでいない方もたくさんいらっしゃるという。ただ、都城市は地方ですから、恐らく市内の方が多いのだろうということで、多分、職員の方は、ほぼマイナンバーカードを作っているということがあると思います。","respondent":"宮澤情報推進課長","answer":"これら、マイナンバーカードをどういう形で進めていくかというところで、ＤＸ推進基本方針でも、全庁的な取組のビジョンとして策定しているところです。その中で、推進体制として、ＤＸ推進戦略会議を設けております。","id":"exchange-092"},{"speaker":"あくつ委員","kind":"質問・要望","question":"７割の方がもう申請が終わっている、約７割弱ですけれども。地域センターでマイナポイント申請手続、これ、結構難しいのですよね。そうではなくて、外から見て分かるようにという質問の趣旨だったのですけれども、その辺りのこの前のご答弁、ちょっと私は釈然としなかったものですから、周知するというご答弁だったのですけれども、どのように周知をお考えになっているのか教えてください。","respondent":"吉野戸籍住民課長","answer":"周知ですけれども、ポスターで周知していきたいと考えておりますが、やはり場所とか、そういったところもありますので、関係各課と地域センターと、その辺の場所の件については話し合っていきたいと考えております。","id":"exchange-093"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国際交流推進事業、ウクライナ避難民への支援についてというところで、改めてこれもお伺いします。それとも、そもそも収入が少ないから、一般区民と同じような段階が適用されていて最低限度になっているのか教えていただきたいということが１つ。ほかの区でやっているような保育料の減免とか、区立保育園等への優先的な受け入れ、こういうことをお考えになられるのか教えてください。","respondent":"古巻総務課長","answer":"子育ての支援につきましては、具体的にということで、今はまだ検討が具体的になっているわけではないのですけれども、所管と話をする中では、例えば、優先的にというか、受入れをしっかり積極的にやっていくというようなことは所管からも話をいただいておりますので。","id":"exchange-094"},{"speaker":"あくつ委員","kind":"質問・要望","question":"端的に申し上げます。最も強い要望があったのは、体育施設、運動施設の無料、減免の使用ということなのですけれども、この件については検討していただけるということで、再質問で部長にご答弁いただいているのですが、これは早急にやっていただきたいと思いますが、この辺りの検討をどのようにお考えか教えてください。","respondent":"古巻総務課長","answer":"こちらにつきましても、区の施設ですが、庁内の関係部署と話をさせていただきながら、調整なり、必要なことについてはさせていただきたいというふうに思います。","id":"exchange-095"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、１８９ページの地域美化推進補助、１８７ページの地域振興経費で大崎地区地域情報サイト経費、１７５ページの情報システム運営費の中から事務管理システム運用保守等経費についてお伺いします。","respondent":"川島地域活動課長","answer":"こちらは、区がこれを補助する目的というか、こちらは品川区歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例にありますように、その目的を達成するために、品川区の１３地区の連合町会のほうに補助をしまして。","id":"exchange-096"},{"speaker":"芹澤委員","kind":"質問・要望","question":"もし減っていないとすれば、もしくは減り止まりしているとすれば、先ほど来、お話がいろいろありますけれども、例えば、空き缶があれば、ごみ箱をつくるというのも１つの選択肢ですし、私はたばこを吸わないので、喫煙所があまり増えるのもちょっとあれなのですが、例えば、吸い殻があるのであれば喫煙所を増やすといった、そういった検討もしていくのかなと思うのですけれども、これまでのごみの量と。","respondent":"川島地域活動課長","answer":"こちらは地域の連合町会に補助金を交付しまして、年度当初に交付したものが、実績報告を上げていただいて経費が確定するというような形でやっているものです。なかなか効果測定という意味での厳密なごみの量を測定するというふうには今はなっていないところです。","id":"exchange-097"},{"speaker":"芹澤委員","kind":"確認","question":"やっぱり寒いから温かい物を買うわけです。そういう意味でいうと、この事業に参加している方々が、ぜひ増えていってほしいなと思うのですが、現実、私の肌感覚ですけれども、町会の役員さんが頑張っていらっしゃって、なかなか新たな方が増えてこないというような認識もあるのですけれども、そこに対して、まず区がどうお考えなのかお聞かせください。","respondent":"川島地域活動課長","answer":"今、様々なご提案をいただいているところですけれども、この事業につきましては、実施内容について連合町会のほうで内容を定めて、それがこちらの補助要綱の趣旨に合致するものについて補助金を支出するというような形になっているので、なかなか細かな実施のやり方。","id":"exchange-098"},{"speaker":"芹澤委員","kind":"提案","question":"私が提案しているのは、連合町会、町会の方々が、ごみをなくせるようにしましょう、自動販売機をつくりましょうという話ではなくて、連合町会の、もしくは町会の方々にごみを拾っていただいている、それと並行して、品川区がまちにごみを出さない取組を進めるべきではないかというような思いでお話をしていますので、そこについてはもう一度ご答弁をお願いいたします。次の項目も併せてお伺いします。","respondent":"川島地域活動課長、宮澤情報推進課長","answer":"こちらは、まちを美しくするということが郷土愛につながるということですので、こちらの活動につきまして、区として何か活動がしやすくなるような支援につながることについては検討させていただければと思います。新しく行います品川区が独自に調達します電子申請サービスと、東京都の共同運営サービスとのサービス利用料の部分につきましては、金額としては増加するです。","id":"exchange-099"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私は２０１９年の一般質問の中で、正にこのサービスについていろいろ触れていまして、旧サービスというのですか、東京都のサービスでは、本人確認が実際に電子認証で行われていないので、これはなかなかセキュリティ的に問題なのではないかというようなお話をさせていただきました。新たなシステムでは、品川区が開発をして、本人認証もできるようになるという認識でよろしいでしょうか。","respondent":"宮澤情報推進課長","answer":"新しい電子申請サービスにつきましては、個人のＩＤ等を登録していただいて、本人確認等もマイナンバーカードを活用するという形で行います。","id":"exchange-100"},{"speaker":"芹澤委員","kind":"質問・要望","question":"当時、私もこの新しいサービスとまでは言っていませんけれども、電子認証をして、介護認定とか、そういった分野においても、よりセキュリティの高い分野においても申請ができるようにしてほしいというような要望をさせていただいて、この１１月２日の資料だと、これから介護認定もできるというふうに伺っていますので、非常に安心しています。これは要望で終わります。","respondent":"川島地域活動課長","answer":"こういったホームページですとかを活用した情報発信、それから、今までいろいろなイベントの申込みが、例えば窓口に来ていただくですとか、電話でとかということではなくて、こういったホームページを活用してできるようになったということで。","id":"exchange-101"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これは非常にすばらしい取組ですので、ぜひ他の地域でも展開していただきたいと思います。","respondent":"川島地域活動課長","answer":"町会のホームページの支援につきましては、今、２６町会がホームページを区の支援で作成したということで、独自作成２０町会と合わせて４６町会がホームページがあるということですけれども、なかなか更新等。","id":"exchange-102"},{"speaker":"くにば委員","kind":"質問","question":"２１０ページ、選挙費、１９３ページ、喫煙マナーアップについてです。投票率向上の施策についてです。半年前の予算特別委員会の総括質疑でも触れさせていただきました。そこで、先日の区長選挙、区議会議員補欠選挙の際に実施した広報以外に、さらなる上乗せで取り組んでおられる広報等の施策はあるのでしょうか。お聞きします。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただし、再選挙についての情報は、やはり皆さんご存じない方が多いので、区の広報紙の選挙特集号で、再選挙についての説明も加えた上で、皆さんに投票に行っていただくような呼びかけをしたいというふうに予定をしています。","id":"exchange-103"},{"speaker":"くにば委員","kind":"提案","question":"３点目が、品川区のＹｏｕＴｕｂｅチャンネル、ここもトップページに、今、最初に自動再生される動画が１本指定できるのですけれども、今は品川区民憲章についての広報動画ですけれども、ここも区長再選挙についての広報動画、これをＹｏｕＴｕｂｅチャンネルの一番トップに表示するような形で、多分、広報したほうがいいと思いますけれども、そのような施策について、何かお考えがありましたら。","respondent":"鈴木選挙管理委員会事務局長","answer":"それから２点目のツイッターですが、こちらにつきましては、やはり区としてのツイッターは、ホームページのバナーと同様に、やはり様々な情報がいきますので、一定程度、ご指摘のあったような選挙期間中であるとか、限定的であっても。","id":"exchange-104"},{"speaker":"くにば委員","kind":"質問・要望","question":"そして２点目、喫煙関係、マナーアップについてです。これは昨日申し上げようと思っていた点なのですけれども、区内某所のコンビニの前に設置されている灰皿の喫煙者による副流煙の煙害について、地域の方々から繰り返し陳情をいただいておりまして、住民の方々からも直接区に苦情であるとか、灰皿の撤去を求める申入れを重ねているのですけれども、なかなかこれの進展が見られません。そこでお聞きします。","respondent":"森田生活安全担当課長","answer":"道路におきましては、指定地区であるならば、そのまま取締りということも考えられますが、現状のところ、道路につきまして指定地区以外のところの取締りはちょっとできないところから、いろいろとご意見もお伺いしているところではありますが、パトロールなどをして。","id":"exchange-105"},{"speaker":"くにば委員","kind":"質問・要望","question":"時間が短いので、意見として述べさせていただきたいのですけれども、こういったあまりにも被害がひどい、もちろん区内様々である同様なケースだと思いますので、こういった場所に、例えばパーティションを設置するとか、そういったことに対して区のほうで助成をするなり、そういった件について事業者と話合いを進めて、何かしらいま一歩踏み込んだ対策をとっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、１８３ページの庁舎計画費について伺いたいと思います。新庁舎整備基本計画の答申案が出されました。このことについて伺いたいと思います。同じこれまでの検討経緯なのに、なぜこれを外したのか、まずお聞かせください。","respondent":"山下新庁舎整備課長","answer":"これまでの経緯といたしまして、庁舎機能検討委員会を踏まえて、実際に令和３年度から、新庁舎整備基本構想・基本計画策定委員会ということで立ち上げまして議論を行ってまいりました。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、機能検討委員会の答申まではこの項目が入っていたのに、なぜ今回、基本構想や、そして基本計画から外したのかと、この理由を伺ったので、理由をお聞かせいただきたいと思います。今のは答弁にはなっていないと思います。なぜ外したのかというのは理由をまた改めてお聞かせいただきたいと思います。これを検討するに当たって、この報告書を見られていないのか伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"実際、令和３年１２月に基本構想を策定した段階でも、これまでの検討経緯といたしましてお示ししておりますのは、平成２９年６月の行財政改革特別委員会を始期とするものでお示ししておりますので、私どもといたしましては、ここが議論の出発点であったというような認識です。","id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この検討をどう説明するのかということでも伺いたいと思います。そうしたら税金の無駄遣いになるのではないか。これは当時、総務部長だった榎本部長が契約者になっているのに、報告書が総務部に届いていないと、そのようなことがあるのでしょうか。このことも私はもう本当に不思議でおかしいのではないかというふうに思っているのですけれども、そのことも伺いたいと思います。そのことを伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"３点目にあります、実際にその活用いかんというようなところですけれども、先ほど来申し上げておりますとおり、庁舎機能検討委員会での議論、答申を経まして、私ども、新庁舎整備基本構想を令和３年１２月に策定し、今現在、新庁舎整備基本計画。","id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうな形で検討されているのに、それを庁舎で共有しない、そういう税金の使い方はあるのでしょうか。その報告書は、担当のところだけで、では、何のためにそれはやったのですか。基本計画をつくるためにやったわけですよね。このところは、今でも総務部長も、それから総務課も、それから、今回の庁舎検討の課長たちも、一切、一切、その報告書はご覧になられていないのでしょうか。","respondent":"山下新庁舎整備課長","answer":"過日の行財政改革特別委員会でもご答弁させていただいたかと思いますけれども、実際、新庁舎の在り方を検討する行財政改革特別委員会、当時で言いますと、令和元年８月２７日ですけれども、Ａ、Ｂ、Ｃ、Ｄということでお示しする。","id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしたら、では、何のための委託を検討して２,５００万円もかけてきたその税金の使い方そのものが問われることになるのではないでしょうか。そうしたら、２つの基本計画の案が示されているのか、そこのところが見られているのかどうなのか。それから、では、なぜ、そもそもＪＲとの協定を外したのか、この答弁もありませんので、それはだって途中まで入っていたわけですから、それなのになぜ外したのか。","respondent":"山下新庁舎整備課長","answer":"したがいまして、繰り返しですけれども、実際上、私どもは、庁舎機能検討委員会から、庁舎整備基本構想・基本計画の策定という流れで、この間、進めてきておりますので、ご指摘の点は、どういうふうに捉えればいいかというところは、そこはちょっと難しいかと考えています。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この報告書をご覧になったのかどうなのかということも聞いたので、そのことだけ伺います。","respondent":"山下新庁舎整備課長","answer":"今回、我々で準備しているものは全く別のものですので、見たような記憶はございません。","id":"exchange-112"},{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、１９３ページ、歩行喫煙防止推進経費についてのみお聞きいたします。そもそもこれまで本数の確認をしてこなかったにも関わらず、なぜ今年になって確認を求めるようになったのか教えていただきたいのと、また、統計を始めてから、具体的にどのぐらいの本数を回収したのか。この統計が、喫煙所整備に向けた意味を含めているのかどうか、３点についてお伺いします。","respondent":"森田生活安全担当課長","answer":"これはまだ１年は経過しておりませんが、毎月１６万本という数がありますので、これはやはりマナーアップ啓発も継続してやるべきでございましょうし、引き続きの対策も何かを考えていく検討の素材としても扱わさせていただこうと考えています。","id":"exchange-113"},{"speaker":"小芝委員","kind":"質問","question":"毎月１６万本ということは、大変多い数だと思います。どうにかしてもらいたいとの依頼を受け、現場に行きお声かけしましたところ、一応その場では全ての方がたばこの火を消してくれました。そこでお聞きしますが、この路上喫煙禁止・地域美化推進地区ではない場所であっても、生活環境がすぐそばにあるような、そういった場所におけます路上喫煙について、区の見解を教えてください。","respondent":"森田生活安全担当課長","answer":"表示物につきましても、横断幕または路上の表示物などもやりまして、それでもいろいろと、条例でもなかなか取締りというところまではできないところでありつつも、私どもも知恵を絞りながら、パトロールも含めてですけれども、対策をそれぞれしています。","id":"exchange-114"},{"speaker":"小芝委員","kind":"質問・要望","question":"やはりこういった場では、もう何度も何度もしつこくてもいいから、こういったパトロール、注意喚起を促していく以外にない、一方では、喫煙所の整備が求められるのではないかと考えておるわけです。続きまして、コンテナ型喫煙所についてお聞きします。開始から半年が経過し、環境の変化はどのように変わったのでしょうか。この整備にかかった費用について教えてください。","respondent":"森田生活安全担当課長","answer":"指定喫煙所としましても、そのまま再開するということが、ちょっとこれは懸念されるところですし、いろいろ苦情もいただいているところでございましたので、再開をどのようにしようかということで、いろいろと検討を進めていたところです。","id":"exchange-115"},{"speaker":"小芝委員","kind":"質問","question":"整備について大変に苦労もあったと思います。当初予算では、大井町のほうにも同様の喫煙所を設置する予算が計上されておったわけですが、地盤の関係で難しくなったと聞いております。そういう中で、例えば、どんたく通りなど、車の往来が比較的少ない道路、また、歩道上に、こういったコンテナ型の喫煙所の整備を検討すべきと思いますが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"大井町につきましては、ほかのところの地区もいろいろと検討させていただきましたが、コンテナ型のものにつきまして、ある程度の大きさと重さに対応できるものでないとできないのだなということで、いろいろ考えて設置を進めている中で、状況が出てきているところですが。","id":"exchange-116"},{"speaker":"小芝委員","kind":"質問・要望","question":"大変厳しい状況であることは分かりました。しかし、あとはまた周知といったところもあります。昨年度から品川区独自の施策としまして、民間事業者に喫煙所を提供してもらう民間公共喫煙所の制度が始まっておりますが、この１年間を通じました進捗状況と、また、どのように周知を行ってきたのか教えていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"そういった中で、令和３年度はまかりならなかったところですが、令和４年度につきましては、補助金を変えまして、指定地区については５分の４に定めるなど、そういった要綱を変更するなどの努力をさせていただきまして、継続して進めているところです。","id":"exchange-117"},{"speaker":"小芝委員","kind":"質問・要望","question":"補助率を変えていくということも１つの手である、本当にそのとおりだと思いますし、また一方で、喫煙所内に例えばモニターを設けて、企業のコマーシャルを流すなど、広告の収益、そういったものを例えば事業者に割り当てることでメリットを与えるということも検討してもいいのかなとは思いますが、お考えを教えていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"今、私どものつくっています要綱につきましては、モニターの設置については禁止にはなっておりませんので、設置は可能です。","id":"exchange-118"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひ積極的に取り組んでいただきたいと思います。それをホームページでも見やすいような形で、ぜひ周知もお願いしたいと思いますが、最後、お考えをお聞かせください。","respondent":"森田生活安全担当課長","answer":"今、ホームページのリニューアルをして、各場所についてもやっております。委員からのご意見もありますので、これについては、また参考にさせていただきながら進めさせていただきたいと思います。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、ウクライナの問題とか様々ありまして、電気、ガス、水道料等がかなり値上がりしてくるという中で、国のほうでもいろいろ対策をされるということですが、今ここにあるのは庁舎だけになると思うのですけれども、今この庁舎の電気、ガス、水道、この決算では１億２,０００万円ぐらいになっていますが、今、これが値上がりの影響というのですか。","respondent":"東野経理課長","answer":"今年度、令和４年度につきましては、委員からもお話がありましたとおり、世界情勢、経済情勢の影響によりまして、従量料金だけではなく、燃料費調整額等もかなり単価が上がっている状況です。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問","question":"学校だとかいろいろ、そういうものを総合的に見ている部署、企画部なのか分かりませんけれども、見て、どれくらい去年に比べて上がりそうなのか、それに対して、例えば節電も含めて、どのような対策をとるとか、そういう全体を見渡しているようなところがあれば教えてください。","respondent":"黒田財政課長","answer":"個々の数字ではございませんが、消費者物価指数で言いますと、電気とかエネルギーのところが、昨年度比で３０％ぐらい増加しているところがありますので、そういったところが費用に反映されているといったところと、先ほど経理課長が申し上げたとおり。","id":"exchange-121"},{"speaker":"たけうち委員","kind":"確認","question":"もう１つのほうの庁舎清掃ですけれども、私、第２回定例会のときに、男性トイレのサニタリーボックスのお話をさせていただいて、既に設置をしていただいているけれどもという中で確認をしたら、今年の５月時点では、本庁舎、第２庁舎、第３庁舎および議会棟の各階の男性トイレの個室のうち１か所設置しましたというお答えがありました。","respondent":"東野経理課長","answer":"１点目の節電への対応というところですけれども、庁舎内に限って言いますと、総務課ならびに環境課からの呼びかけ、各課への呼びかけ等によりまして、節電、特に昼休みの消灯ですとか、午後５時１５分以降の消灯ですとか、そういうところを呼びかけているような状況です。","id":"exchange-122"},{"speaker":"たけうち委員","kind":"質問・要望","question":"サニタリーボックス、これは費用対効果とかではかるようなものではないので、利用があろうとなかろうと、やっぱりそういう方が安心して利用できるようにということで、今後、本庁舎以外のところでも、区有施設については広めていっていただくというふうに、そのときの答弁がございましたので、今後これをどのように、既に広まっているのか、それとも。","respondent":"古巻総務課長、東野経理課長","answer":"節電の関係です。今、経理課長からもご答弁させていただきましたけれども、環境施策ということで環境課、それから総務課も一体となりまして全庁的に、今後、冬の節電の取組なども必要になってまいりますので、進めしています。男性用サニタリーボックスの区有施設の広がりにつきましては、順次設置に対応してということで、第２回定例会のときにもご答弁させていただいたかと思います。","id":"exchange-123"},{"speaker":"たけうち委員","kind":"質問・要望","question":"節電のところですけれども、やっぱり各施設でばらばらに取り組むよりは、一定程度、ガイドラインみたいなものをつくって全体的にやっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"１８３ページ、庁舎等管理費の庁舎計画費、１７１ページに戻ってしまいますが、財政管理費の予算関係管理費。新庁舎建設で４００億円以上の建設費というのは、今まで様々な議論が行われています。以前に起債についてお尋ねしたのですが、まだちょっと理解できないのでお願いします。新庁舎の中の庁舎機能部分における建設費の起債についてお尋ねします。どこに起債について書かれているのでしょうか。","respondent":"黒田財政課長","answer":"要は、起債につきましては、建物がどういうものができるかとか、庁舎の中がどういう機能かというところによって起債のメニューも変わってまいりますので、引き続き、また東京都とも連携をとりながら、財源の調達については検討していきたいというふうに考えてあります。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、今、東京都と協議を進めているということですが、今、協議しているということは、起債したいので、そこで協議して同意を求めている、用語がちょっと違うかもしれませんが、そのところなのか。どこまで進んでいるのかということです。今、協議をしているとお話しされたのですが、床がどれで、どれだけではないと、庁舎部分がどれだか分からないという段階でも協議はできるのですか。","respondent":"黒田財政課長","answer":"用語で、いわゆる起債の事前協議ではありませんので、まだ、実際の事前協議ということではなくて、庁舎を建てるに当たっての資金調達で、区としては起債を考えているというところの情報交換も含めて、東京都の担当者と、令和３年１２月に打合せをしたです。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"協議ではなくて情報交換ということは分かりました。今、都と話しているということで、それは、そもそも財政計画をつくるのは大変だと思っています。私は起債自体を否定するものでは全くありません。そうすると、今お話にあったように、民間資金という形になると、これはかなり区の負担も大きくなるのですが、それも含めて、今、情報交換しているということでよろしいでしょうか。","respondent":"黒田財政課長","answer":"そういった意味では、銀行から、銀行等引受債ですと、財政資金よりも利率は若干高いのですが、そこは長期にわたって資金を調達するという中の資金調達のコストをどのように考えるかというところがありますので、また、そういったところにつきましても。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々な資金調達の方法を模索していただいていると。ぜひとも今後の交渉に期待しますが、東京都との協議の状況で、今後、許可という言い方なのか、それとも、協議で同意するというのか、言葉がちょっと私は分からないのですが、その見込みはいかがでしょうか。","respondent":"黒田財政課長","answer":"地方債制度の中では、かつては許可制度だったのですが、現在は東京都と協議をして、最終的には同意を得るというような手続になろうかと思いますので、その同意を得る中で、庁舎の計画に対して。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１９３ページ、荏原町安全安心ステーション、同じく１９３ページ、喫煙所設置、維持管理についてお伺いします。最初に、荏原町安全安心ステーションについてお伺いしたいと思います。荏原町安全安心ステーションは、２００７年１２月に開設していると思います。既にこれはもう１５年が経過して、地域の方々のご協力で、今現在も推し進められています。初めに、今の現状を教えていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"委員のご説明がありましたとおり、平成１９年３月の荏原町駅前交番の廃止に伴いまして、地域の皆様方のご要望もありまして、品川区で荏原町安全安心ステーションを設置したものです。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１９名の方で、恐らく６町会だと思うのですけれども、ご協力をいただいています。いずれはシルバー人材センターとか、そういうところに委託をしたほうがいいのではないかと私は個人的に思っているのですけれども、今後の区としての見解、見通し、どういうふうにお考えになっているのかをお聞きしたいと思います。","respondent":"森田生活安全担当課長","answer":"最近の事例で申しますと、具合の悪い女子高校生がいらっしゃったときに、いろいろとそこで対応していただいて、そこから１１９番通報していただいたり、また、拾得物もときどきありまして、警察ではないので全ての対応はできませんので、近くの交番にお届けいただくとか。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、同じく１９３ページ、喫煙所設置、維持管理についてお伺いいたします。先ほど、小芝委員からも、この喫煙所、コンテナ型という質疑がございました。これはすぐできるようなことではないと思うので、今後は指定喫煙所内でのコンテナ設置を求めて要望をしたいと思います。今後パーティションの指定喫煙所をこの先やっていく方向だと私は認識しているのですけれども、改めてお聞きしたいと思います。","respondent":"森田生活安全担当課長","answer":"ですので、なるべくは密閉型という形で進めたいとは思っておりますが、やはりその設置がかなわないところも当然ありますので、そういった場合には、付近の皆様方のご理解等々もいただきながら、１つの方向としては考えていきたいと考えています。","id":"exchange-131"},{"speaker":"大倉委員","kind":"質問・要望","question":"１８７ページ、児童参加地域事業補助で、将来の地域活動の担い手となる児童の参加を促す事業ということで、要綱を見ると、イベントを運営する側の食糧費が出ないということで、当日のイベントの昼食費も出ないということなのですが、なぜ出ないのかということと、当日の昼食代は出せるようにすべきだと思っているのですが、それについても教えてください。","respondent":"川島地域活動課長、辻スポーツ推進課長、鈴木選挙管理委員会事務局長","answer":"ただし、当日に参加者と同じお弁当を一緒に食事に供して食べるとかという部分はイベントの一部ということで。現在、教育委員会と連携しながら、私どもの地域資源として、どのようなものがあるかという、１つは地域スポーツクラブ、それ以外ですと。特に、特定の事業者なり、もしくは政党を支持する事業者の方に活用されるようなこともないとは限りませんので。","id":"exchange-132"},{"speaker":"大倉委員","kind":"質問・要望","question":"児童参加地域事業補助金のほうは分かりました。選挙のほう、１点伺います。聞き忘れたのですけれども、発行状況、どのくらいの方が投票済証を手にとったのかということが分かれば教えてください。えばら」についてですが、かなり人も出ていて、念願の荏原地域での文化イベントということで、地域の方たちも非常に喜んでいるというところと、１万人ぐらいの方が来ているというお話は伺いました。","respondent":"鈴木選挙管理委員会事務局長、篠田文化観光課長","answer":"シナモロールを活用した投票済証の配布の状況ですが、これはあくまで選挙を済まされた方で申出があった方だけに配布をしておりまして、投票区内の有権者数によっても若干異なりますが。「にしこやまつり」のほうは「にしこやまつり」のほうで、独自のチラシ等も作って対応していただいたということもありますので、その関わり方によって。","id":"exchange-133"},{"speaker":"大倉委員","kind":"質問・要望","question":"荏原全体が盛り上がってほしいと思って聞いておりますので、そうした声のかけ方もあるのかなということで、ぜひ、今後またやっていく上では、さらなるにぎわいにつなげていただきたいと思うのと、西小山はかなりにぎわっていたということで、ロータリーを活用したことも１つあるのかなというところであります。えばら」をどうやって継続的に続けていくのか教えてください。","respondent":"篠田文化観光課長","answer":"今後の展開ということですが、こういったイベント物は、何分に、その都度、予算がどうやってつくのかといったことも踏まえながら進めていくものですから、私どもとしましては、今回の成功を受けまして。","id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"イベントは、結構地元の人たちが愛着を持って続けていただけるので、お祭りなどもそうですけれども、ぜひこの愛着の醸成とかにもつなげていっていただきたいと思います。ぜひ頑張っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"石田委員","kind":"質問","question":"私からは、１８１ページの男女共同参画推進事業から、リプロダクティブ・ヘルス・アンド・ライツについて伺いたいと思います。先日の一般質問でも共産党は取り上げさせていただきましたけれども、改めて、リプロダクティブ・ヘルス・アンド・ライツとは何か、どのようなものなのか、区の認識を伺いたいと思います。","respondent":"加島人権啓発課長","answer":"リプロダクティブ・ヘルス／ライツに関する区の認識というお尋ねですけれども、こちらは、女性は妊娠・出産をする可能性があり、ライフサイクルを通じて男性とは異なる健康上の問題に直面するため、女性の生涯を通じた健康支援に関わる理念だと認識しております。","id":"exchange-136"},{"speaker":"石田委員","kind":"質問","question":"ちょっと一般質問のときの答弁からも思ったのですけれども、リプロダクティブということが、要は、生殖に関することなのです。ですので、権利だという認識はあるでしょうか。伺います。","respondent":"加島人権啓発課長","answer":"リプロダクティブ・ヘルス／ライツということで、性と生殖の健康と権利ということですが、今、ご答弁申し上げましたとおり、女性の健康を支援する概念というふうに区では捉えております。","id":"exchange-137"},{"speaker":"石田委員","kind":"質問・要望","question":"大くくりで言われているかなという感じはするのですけれども。そして、それを権利として、産む、産まない、女性の自己決定です。その権利があるということなので、ぜひそうした認識で進めていただきたいと思うのです。このリプロダクティブ・ヘルス・アンド・ライツの視点も踏まえというのは、これはどのように計画には踏まえられているのか伺いたいと思います。","respondent":"加島人権啓発課長","answer":"女性の健康という観点から、思春期、妊娠・出産期から高齢期まで、女性の生涯を通じた健康保持に関することといたしまして、区では、リプロダクティブ・ヘルス／ライツの視点を、年代や性差に応じた健康づくり、また、心の健康づくりへの支援という形で掲げているところです。","id":"exchange-138"},{"speaker":"石田委員","kind":"質問","question":"何もないじゃない」という感じがしてならないのですけれども。視点を踏まえてということでは、広がらないと私は思うのです。やはり「リプロダクティブ・ヘルス・アンド・ライツ」という言葉自体がまだ知られていません。もちろん中身もまだ知られていません。そういう下で、まずは権利であるということの普及啓発をしていくことが必要だと思わないでしょうか。伺います。","respondent":"加島人権啓発課長","answer":"今、委員のほうから計画内容のご紹介、ご案内がございましたけれども、そういった視点がこの中に反映されているものと区では認識しております。","id":"exchange-139"},{"speaker":"石田委員","kind":"質問","question":"こういうふうに視点を踏まえてとか、あと、ほかの計画でも、計画に言葉は入っていないけれども理念はあるのですとか、そういうことを品川区はよく言われるのです。だから、そういうごまかしのような、言い訳のような言い回しはやめていただいて、しっかりと区民に推進すべき計画として、このリプロダクティブ・ヘルス・アンド・ライツというものを位置づけるべきだと思うのですけれども、いかがでしょうか。","respondent":"加島人権啓発課長","answer":"こちらのリプロダクティブ・ヘルス／ライツの視点を新たに計画に書き加えるか、明記するかにつきましては、策定時等の委員検討を踏まえて進めていくべきものと考えており、現段階では可能性としての答弁となることをご了承いただければと存じます。","id":"exchange-140"},{"speaker":"石田委員","kind":"質問","question":"私も２３区の男女共同参画の推進計画や行動計画を調べました。多くの区が、リプロダクティブ・ヘルス・アンド・ライツの権利の普及啓発を進めると計画に位置づけています。ただでさえ、このリプロダクティブ・ヘルス・アンド・ライツは近年出てきた権利、認識であるので、広がっていないのは当然ですけれども、品川区はここからさらに出遅れていると私は思うのですけれども、そこの認識はいかがでしょうか。","respondent":"加島人権啓発課長","answer":"計画に文言としての明記はございませんけれども、こちらはリプロダクティブ・ヘルス／ライツの考え方をきちんと理解いたしまして、今現在、男女共同参画の啓発講座、それから女性相談員による総合相談、併せまして。","id":"exchange-141"},{"speaker":"石田委員","kind":"質問・要望","question":"今おっしゃられたのは、一般質問の答弁と全く同じですけれども、今までやられてきたことをそのままやっている、やりますということですけれども、やはりリプロダクティブ・ヘルス・アンド・ライツ、性と生殖の健康と権利、このことを位置づけなければ、権利の周知も、区の立場も、考え方も変わっていかないと思うのです。ぜひそこは位置づけていただきたいと思います。その半数が１０代、２０代。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１８３ページ、庁舎計画費、それから１７５ページの情報システム運営費、こちらは主に母子手帳のデジタル化ということについて伺いたいと思います。これから基本設計に向けて進んでいくわけですけれども、どのように位置づけているのかということをお伺いしたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"華美な意匠は避け、シンプルで機能美があふれる外観デザインであるよう考えていきたいと考えています。品川区の歴史を踏まえつつ、周辺環境などと調和したデザインとなるよう、設計段階で検討をしてまいりたいと考えています。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問","question":"この質問は行財政改革特別委員会でもさせていただいて、ご答弁もいただいているところでございましたけれども、今日は、さらにこれを、今言ったようなデザインを実現するために、どういった形を、手法をとって進めていくのか。","respondent":"大友新庁舎建設担当課長","answer":"その後、外観を詰めていく形につきましては、これからどういう手法があるかというところについて検討していく形になるかと考えています。","id":"exchange-144"},{"speaker":"塚本委員","kind":"質問","question":"あれを見ていると、本当にやっぱり品川区というのは、長い歴史の中で、いろいろな出来事もありましたし、いろいろな方々が生活され、本当に江戸時代からずっと存続しているお寺とかが、その江戸時代当時の絵に残っているとか、非常に感銘を受けるところがありまして、そういった区の歴史とか、伝統とか、そういった品川区の文化というのですか、そういったことをしっかりと反映できるような。","respondent":"大友新庁舎建設担当課長","answer":"デザインに関して、その知見がある方というところにつきましては、まず第一段階のプロポーザルの段階でも、学識経験者、特に建築デザインの意匠を専門とする方等を含めて検討してまいりたいと考えています。","id":"exchange-145"},{"speaker":"塚本委員","kind":"質問・要望","question":"その一環として、申請とは微妙に違うのかもしれませんけれども、母子手帳のデジタル化ということで、これは区としては、こういった母子手帳のデジタル化を、この一連の庁舎のデジタル化、手続のデジタル化という中で含まれているのかということ、デジタル化ということで、母子手帳もデジタル化の対象として検討を進めていますよという状況にあるのかどうか、現状をお知らせいただきたいと思います。","respondent":"宮澤情報推進課長","answer":"母子手帳のデジタル化というところでのお問合せです。手続としまして、妊娠の届出につきましては、オンラインでの手続はもう既に実施しています。","id":"exchange-146"},{"speaker":"塚本委員","kind":"質問・要望","question":"今ご答弁にもありましたけれども、これは国が、来年度ですか、母子手帳を見直すというところで、その中で、中身の見直しとともにデジタル化を進めるのだと。","respondent":"宮澤情報推進課長","answer":"そういったところで、マイナポータルとのＡＰＩ連携ということで、システムとの連携という形もあります。これは新しく入れる電子申請サービスでも今後活用していくですので、そういったところを技術的にも含めて進めたいと考えています。","id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"確認","question":"基金を一般の区民の方に出すときには、９１４億円ということで間違いないでしょうかということも確認させてください。９月に犯罪被害者支援キャンペーンを行っていたのは承知しておりますが、このようなことがあっては困るのですけれども、万が一、区民の方に犯罪被害者が出たときに、区として改めてどういう対応をしていくか、この点についてお考えを教えてください。","respondent":"黒田財政課長、大澤広報広聴課長","answer":"基金の関係ですが、決算書の５２８ページに書かれておりますのは、財産に関する調書というところで、このページに書かれているものは、令和３年４月１日から令和４年３月３１日までの決算年度中の増減を表しまして。以上のように、被害者の方にとって一番身近である区の相談室が調整役となって、関係課、また関係機関と連携して対応に当たるという支援を行っております。","id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"決算上の関係は、さっきも言ったのですけれども、何か方法をとっていただいて、分かるような形をとっていただきたいということを、もう１回要望しておきます。基金も乗っているのですから、これから区として新庁舎の建築のためにスタートしていく、その基金を積んだということを、やはり区民の皆さんに分かりやすいように出しておいていただきたいと、これも要望しておきます。これも要望しておきます。","respondent":"古巻総務課長、黒田財政課長","answer":"人と人の交流ですけれども、コロナの感染が拡大して以降、なかなか国際的な人の交流が難しい状況にあって、実施できていない部分がございましたけれども、この間におきましても、オンラインでの交流を進めたり。流用の考え方ですが、委員からご指摘ありましたとおり、基本的には、事業内での流用が原則で流用は行っておりまして、基本的には、事業を見積りする際に、その翌年度の事業量を想定して予算を編成して。","id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"分かりました。国際交流に関しては、友好都市、姉妹都市との交流をまた復活していただきたいと思いますけれども、例えば、区長が代わったということ自体は、姉妹都市に連絡はいっているのでしょうか。もうこれは聞くだけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816325?Template=document&Id=1518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":118848,"voices":347}}]);
